  '[[\'In the Stripe Dashboard add a webhook endpoint with this URL and the events payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.created, customer.subscription.updated, customer.subscription.deleted, invoice.paid and invoice.payment_failed, then save its signing secret above. An endpoint set up earlier for Flux Forms keeps working.\', \'en\']]' => 'Stripe ダッシュボードで、この URL とイベントpayment_intent.succeeded、payment_intent.payment_failed、payment_intent.canceled、charge.refunded、customer.subscription.created、customer.subscription.updated、customer.subscription.deleted、invoice.paid、および invoice.payment_failed を含む Webhook エンドポイントを追加し、その署名シークレットを上記に保存します。 Flux Forms 用に以前に設定されたエンドポイントは引き続き機能します。',
