  '\\nDonations, donors and recurring gifts at a glance.\\n' => '寄付、寄付者、定期的なギフトの概要。',
  'All donations' => 'すべての寄付',
  'Period' => '期間',
  '7 days' => '7日間',
  '30 days' => '30日',
  '90 days' => '90日',
  '\\nCustom\\n' => 'カスタム',
  '\\nThe dashboard needs JavaScript.\\n' => 'ダッシュボードには JavaScript が必要です。',
  '\\nSorry, you are not allowed to do that.\\n' => '申し訳ありませんが、それは許可されていません。',
  'Organisation' => '組織',
  'Categories' => 'カテゴリー',
  '\\nTracking\\n' => '追跡',
  '\\nExtra tabs\\n' => '追加のタブ',
  'System check' => 'システムチェック',
  '[[\'Settings sections\\n' => '設定セクション',
  '\\nDefault currency\\n' => 'デフォルトの通貨',
  '\\nTurkish lira (₺)\\n' => 'トルコ リラ (₺)',
  '\\nEuro (€)\', \'en\']]' => 'ユーロ (€)',
  '\\nUS dollar ($)\\n' => '米ドル ($)',
  '\\nPound sterling (£)\\n' => '英ポンド (£)',
  '\\nDashboard totals are in this currency; gifts in other currencies are listed but not added to the totals.\\n' => 'ダッシュボードの合計はこの通貨で表示されます。他の通貨でのギフトはリストに表示されますが、合計には追加されません。',
  '\\nTracking module\\n' => '追跡モジュール',
  '\\nChosen donation types get one item per unit with a code, sent to partners (with agreed prices and settlement), files and history. Leave it off if you do not need it.\\n' => '選択した寄付タイプでは、コード付きのユニットごとに 1 つのアイテムがパートナーに送信され (価格と決済が合意された)、ファイルと履歴が付与されます。必要ない場合はオフのままにしておきます。',
  '[[\'A Reports screen with editable JSON reports (always on with the tracking module).\\n' => '編集可能な JSON レポートを含むレポート画面 (追跡モジュールでは常にオン)。',
  '[[\'Gifts on behalf of a person\\n' => '個人に代わってギフト',
  '[[\'Adds a proxy (vekâlet) text the donor accepts, intentions and one item per unit with the name of the person it is given for. Turns tracking on too.\\n' => '寄付者が受け入れる委任状 (vekâlet) テキスト、意図、および贈られた人の名前を含むユニットごとに 1 つのアイテムを追加します。追跡もオンにします。',
  '\\nWhich payments are donations?\\n' => 'どの支払いが寄付ですか?',
  '\\nEvery payment taken through a Flux Forms form\\n' => 'Flux Forms フォームを通じて行われたすべての支払い',
  '\\nOnly payments through the forms selected below (and forms linked to a donation type)\\n' => '以下で選択したフォーム (および寄付タイプにリンクされたフォーム) による支払いのみ',
  'Save settings' => '設定を保存する',
  '\\nHow donations are recorded", \'tr\']]' => '寄付の記録方法',
  '\\nA donation is stored when a Flux Forms payment is completed: at the final form submission (with name, phone and e-mail from the form), from the payment provider\\\'s notifications (refunds, renewals of recurring gifts) and by an hourly check that catches payments whose form was not submitted.\\n' => '寄付金は、Flux Forms の支払いが完了すると保存されます。最終的なフォーム送信時 (フォームからの名前、電話番号、電子メールによる送信)、支払いプロバイダーの通知 (払い戻し、定期的なギフトの更新)、およびフォームが送信されなかった支払いを確認する 1 時間ごとの小切手によって保存されます。',
  '\\nDonors are matched on phone number or e-mail address, never on name alone.\\n' => '寄付者は名前だけではなく、電話番号または電子メール アドレスで照合されます。',
  '\\nShown on receipts, donation pages and in exports. Empty fields fall back to the site name, the theme logo and the theme colours.\\n' => '領収書、寄付ページ、エクスポートに表示されます。空のフィールドは、サイト名、テーマのロゴ、テーマの色に戻ります。',
  '\\nOrganisation name\\n' => '組織名',
  'Logo' => 'ロゴ',
  '\\nChoose a logo\\n' => 'ロゴを選択してください',
  'Choose logo' => 'ロゴを選択してください',
  '[[\'brand color\\n' => 'ブランドカラー',
  '\\nHex color such as #1F2937. Empty = the theme\'s primary colour.\\n' => '#1F2937 などの 16 進数の色。空 = テーマの原色。',
  '\\nReceipt text\\n' => '受信テキスト',
  '\\nA thank-you note printed on the donation receipt.\\n' => '寄付受領書に感謝のメッセージが印刷されます。',
  '\\nFooter text\\n' => 'フッターのテキスト',
  '\\nAddress, registration number, bank details and similar; printed at the bottom of receipts.\', \'en\']]' => '住所、登録番号、銀行口座情報など。レシートの下部に印刷されます。',
  '\\nDonation type categories\\n' => '寄付タイプのカテゴリ',
  '\\nGroup donation types, e.g. Sacrifice, Ramadan, General. The key is stored on the types; a category that is in use cannot be removed.\\n' => 'グループ寄付のタイプ (例:犠牲、ラマダン、将軍。キーはタイプに保存されます。使用中のカテゴリは削除できません。',
  'Add category' => 'Add category',
  '[[\'Save categories\\n' => 'カテゴリを保存',
  '[[\'Used by%stype\', \'en\']]' . chr(0) . '[[\'Used by%stypes\', \'en\']]' => '%sタイプで使用',
  '\\nRemove category\\n' => 'カテゴリを削除',
  '\\nThe words on the tracking screens. A donation type can use its own words (Donation types › Tracking); empty fields use these, and empty ones here the built-in words.\\n' => '追跡画面上の単語。寄付の種類には独自の言葉を使用できます (寄付の種類 › 追跡)。空のフィールドにはこれらの単語が使用され、空のフィールドには組み込みの単語が使用されます。',
  '\\nEarly days\\n' => '初期の頃',
  '\\nHow many days before the target date an item may already be done. After the target day it is still allowed, but shown as late.\\n' => '項目が目標日の何日前にすでに完了している可能性があります。対象日を過ぎても許可されますが、遅いと表示されます。',
  '\\nProxy (vekâlet) text\\n' => 'プロキシ (vekâlet) テキスト',
  '\\nThe text a donor accepts to authorise the organisation to give on their behalf. Every change is saved as a new version; each donation keeps the version that was accepted.\\n' => '寄付者が寄付者に代わって寄付を組織に許可するために受け入れるテキスト。すべての変更は新しいバージョンとして保存されます。各寄付では、受け入れられたバージョンが保持されます。',
  '\\nWho items are sent to, their agreed prices and payments are kept under Donations › Partners.\\n' => 'アイテムの送付先、合意された価格および支払いは、「寄付」 > 「パートナー」に保管されます。',
  '\\nProxy text versions\\n' => 'プロキシ テキストのバージョン',
  '\\nNo text yet. Donations of types that require a proxy cannot be paid until a text is saved.\\n' => 'まだテキストがありません。代理人が必要なタイプの寄付は、テキストが保存されるまで支払うことができません。',
  '\\nVersion%1$s·%2$s\\n' => 'バージョン%1$s·%2$s',
  '\\nAdd your own tabs with fields to tracked records ("on": "item") or donations ("on": "donation"), for all or some donation types. Leave it empty if you do not need any.\\n' => 'すべてまたは一部の寄付タイプについて、追跡レコード ("on": "item") または寄付 ("on": "donation") にフィールドを含む独自のタブを追加します。必要ない場合は空のままにしておきます。',
  '\\nTabs (JSON list)\\n' => 'タブ (JSON リスト)',
  '\\nTabs in use\\n' => '使用中のタブ',
  'Donation page' => '寄付ページ',
  '\\nRecord page\\n' => 'レコードページ',
  '[[\'%dfield\', \'en\']]' . chr(0) . '[[\'%dfields\', \'en\']]' => '%dフィールド',
  '\\nfrom a plugin\\n' => 'プラグインから',
  '\\nNo extra tabs yet.\\n' => '追加のタブはまだありません。',
  'Example' => '例',
  '\\nReads completed payments stored by Flux Forms and adds the missing ones as donations. Safe to run more than once: a payment is never imported twice.\\n' => 'Flux Forms に保存されている完了した支払いを読み取り、不足している支払いを寄付として追加します。複数回実行しても安全です。支払いが 2 回インポートされることはありません。',
  '\\nFlux Forms\\\'s payment table was not found. Is Flux Forms installed?\\n' => 'Flux Forms\\ の支払いテーブルが見つかりませんでした。 Flux Forms はインストールされていますか?',
  '\\nImporting...\\n' => 'インポート中...',
  '\\nImport now\\n' => '今すぐインポート',
  '\\nLast run%1$s:%2$spayments checked,%3$simported.\\n' => '最後の実行%1$s:%2$sの支払いがチェックされ、%3$sがインポートされました。',
  'Closed' => '閉店',
  'Archived' => 'アーカイブ済み',
  '\\nUpcoming (%s)\\n' => '今後の予定 (%s)',
  'Ended' => '終了しました',
  '\\nNew donation type\\n' => '新しい寄付タイプ',
  '\\nDonation types and campaigns\\n' => '寄付の種類とキャンペーン',
  '\\nWhat people can give for: each type has its own prices and options, dates, goal and linked forms.\\n' => '人々が寄付できるもの: 各タイプには独自の価格、オプション、日付、目標、リンクされたフォームがあります。',
  '\\nOpen and closed\\n' => '開いた状態と閉じた状態',
  'Archive' => 'アーカイブ',
  '\\nThe archive is empty\\n' => 'アーカイブは空です',
  '\\nNo donation types yet\\n' => '寄付の種類はまだありません',
  '\\nCreate a type such as a general donation, a sapling or a kurban share, set its prices, and link the forms that collect for it.\\n' => '一般寄付、苗木、クルバン株などのタイプを作成し、価格を設定し、寄付を集めるフォームをリンクします。',
  'Order' => '注文',
  'Prices' => '価格',
  'Progress' => '進捗状況',
  'Dates' => '日付',
  'Forms' => 'フォーム',
  'Move up' => '上に移動',
  'Move down' => '下に移動',
  '\\nNo category\\n' => 'カテゴリがありません',
  '\\n(inactive)\\n' => '(非アクティブ)',
  '\\n(price not set)\\n' => '(価格は設定されていません)',
  '\\nfree amount (min.%s)\\n' => '無料金額 (最小%s)',
  '\\nfree amount\\n' => '無料金額',
  '[[\'quantity\\n' => '数量',
  '\\nrecurring\\n' => '繰り返し',
  '\\n%1$sof%2$s(%3$s%%)\\n' => '%1$s/%2$s(%3$s%%)',
  '\\nOpen-ended\\n' => '無制限',
  'Edit' => '編集',
  '\\nLoad sample types\\n' => 'サンプル タイプをロードします',
  '\\nAdds ready-made types and categories that you can edit. Types whose sample price is 0 start closed until you set their prices.\\n' => '編集可能な既製のタイプとカテゴリを追加します。サンプル価格が 0 のタイプは、価格が設定されるまでクローズ状態になります。',
  '\\nSample set\\n' => 'サンプル セット',
  'Load' => 'ロード',
  '\\nDonation type not found\', \'en\']]' => '寄付の種類が見つかりません',
  '\\nEdit donation type\\n' => '寄付タイプを編集',
  'Basics' => '基本',
  'Title' => 'タイトル',
  'Category' => 'カテゴリ',
  '\\nEdit categories\\n' => 'カテゴリを編集',
  '\\nSlug\\n' => 'ナメクジ',
  '\\nOptional; created from the title.\\n' => 'オプション。タイトルから作成されました。',
  '\\nPrices and the goal are in this currency. A linked form must charge in the same currency, otherwise its payments are stopped.\\n' => '価格と目標はこの通貨で表示されます。リンクされたフォームは同じ通貨で請求する必要があります。そうでない場合、支払いは停止されます。',
  'Short description' => '簡単な説明',
  'Automatic' => '自動',
  'Heart' => 'ハート',
  'Gift' => 'ギフト',
  '\\nSheep\\n' => '羊',
  'Cattle' => '牛',
  '\\nCamel\\n' => 'ラクダ',
  '\\nCard subtitle", \'en\']]' => 'カードのサブタイトル',
  '\\nOne short line under the title on the type cards, e.g. "Sheep or goat".\', \'en\']]' => 'タイプ カードのタイトルの下に 1 行の短い行があります。例: "羊またはヤギ".',
  'Icon' => 'アイコン',
  '\\nShown when the type has no image.\\n' => 'タイプに画像がない場合に表示されます。',
  'Image' => '画像',
  '\\nChoose an image\\n' => '画像を選択してください',
  'Choose image' => '画像を選択してください',
  '\\nPrices and options\\n' => '価格とオプション',
  '\\nOne option is a fixed price per unit (e.g. one sapling). Several options give the donor a choice (e.g. adak, akika, şifa). The amount charged is always computed on the server from these prices.\\n' => 'オプションの 1 つは、単位あたりの固定価格です (例: 苗木 1 本)。いくつかのオプションがドナーに選択肢を与えます (adak、akika、şifa など)。請求金額は常にこれらの価格に基づいてサーバー上で計算されます。',
  '\\nA price of 0 means the price is not announced yet: the option is shown but cannot be paid. An inactive option is hidden and cannot be paid.\\n' => '価格 0 は、価格がまだ発表されていないことを意味します。オプションは表示されていますが、支払うことはできません。非アクティブなオプションは非表示になっているため、支払うことができません。',
  'Add option' => 'オプションを追加',
  '[[\'Free amount allowed\\n' => '許可される無料金額',
  '\\nMinimum amount\\n' => '最低金額',
  '\\nQuantity allowed\\n' => '許可される数量',
  '\\nMaximum quantity\\n' => '最大数量',
  '\\nEmpty = no limit.\\n' => '空 = 制限なし。',
  '[["Recurring giving allowed\\n' => '定期的な寄付は許可されています',
  '\\nLinked forms\\n' => 'リンクされたフォーム',
  '\\nGifts through these Flux Forms forms count for this type. Map each priced choice of the form to an option: the form then charges the price set here.\\n' => 'これらの Flux Forms フォームを介したギフトは、このタイプにカウントされます。フォームの各価格選択肢をオプションにマッピングします。その後、フォームはここで設定された価格を請求します。',
  '\\nNo payment form found in Flux Forms yet.\\n' => 'Flux Forms には支払いフォームがまだ見つかりません。',
  '\\nalso linked to:%s\\n' => '次にもリンクされています:%s',
  '\\nSave after choosing a form to map its choices.\\n' => 'フォームを選択した後、その選択肢をマップするために保存します。',
  '\\nHide the choice in the form when it was preselected\\n' => '事前に選択されていた場合、フォーム内の選択肢を非表示にします',
  '\\nWhen the page passes a choice (flxb_opt in the address or FLXB.preselect()), the form shows a short summary with a "Change" link instead of the choice list.\\n' => 'ページが選択肢 (アドレスの flxb_opt または FLXB.preselect()) を渡すと、フォームには選択肢リストの代わりに「変更」リンクを含む短い概要が表示されます。',
  'Publishing' => '出版',
  '\\nA closed type keeps its history but its forms no longer take payments.\\n' => 'クローズドタイプは履歴を保持しますが、そのフォームは支払いを受け付けなくなります。',
  'Start date' => '開始日',
  '\\nEnd date\\n' => '終了日',
  '\\nGoal amount\\n' => '目標金額',
  '\\nOptional. Shown as a progress bar.\\n' => 'オプション。進行状況バーとして表示されます。',
  '\\nShow it on the site\\n' => 'サイトに表示します',
  '\\nAdd baslik="hayir" to hide the title and description.\\n' => 'タイトルと説明を非表示にするには、baslik="hayir" を追加します。',
  '\\nDelete this donation type\\n' => 'この寄付タイプを削除します',
  '\\nDelete this donation type?\\n' => 'この寄付タイプを削除しますか?',
  '\\nThis type has gifts, so it can be archived but not deleted.\\n' => 'このタイプにはギフトがあるため、アーカイブすることはできますが、削除することはできません。',
  '\\nOption name\\n' => 'オプション名',
  '\\ne.g. Sapling, Adak, Iftar\\n' => 'e.g.苗木、アダック、イフタール',
  '\\nfrom the name\\n' => '名前から',
  '\\nRemove option\\n' => 'オプションを削除',
  'Unit' => '単位',
  '\\n— note set\\n' => '— ノートセット',
  '\\nUnits per choice\\n' => '選択肢ごとの単位',
  '\\ne.g. a whole animal = 7 shares\\n' => 'e.g.動物全体 = 7 シェア',
  'Badge' => 'バッジ',
  '\\nnot offered\', \'en\']]' => '提供されていません',
  '\\nTranslations\\n' => '翻訳',
  '\\nShown on the donation page, the cart and the checkout in that language (Flux Lang). Empty fields use the texts above. Records keep the texts above. Save once after adding options to translate their names.\\n' => '寄付ページ、カート、チェックアウトにその言語 (Flux Lang) で表示されます。空のフィールドには上記のテキストが使用されます。記録には上記のテキストが残っています。名前を翻訳するオプションを追加した後、一度保存します。',
  '\\nOption:%s\\n' => 'オプション:%s',
  '\\nEach unit of a gift becomes its own item with a 7-digit code: approved, sent to a partner, completed, delivered to the owner, with files and history.\\n' => 'ギフトの各ユニットは、7 桁のコードを持つ独自のアイテムになります。承認、パートナーへの送信、完了、所有者への配送、ファイルと履歴が含まれます。',
  '\\nTrack every unit one by one\\n' => 'すべてのユニットを 1 つずつ追跡します',
  '\\nAlways on for gifts given on behalf of a person.\\n' => '個人に代わって贈られるギフトの場合は常に有効です。',
  '\\nThe first file marks it completed\\n' => '最初のファイルは完了をマークします',
  '\\nWords for this type\', \'en\']]' => 'このタイプの単語\'、\'en\']]',
  '\\nOn behalf of a person\\n' => '個人を代表して',
  '\\nFor types given on behalf of a named person: each unit becomes its own item with that person\\\'s name, and the donor must accept the proxy (vekâlet) text.\\n' => '指定された人物に代わって提供されたタイプの場合: 各ユニットはその人物の名前が付いた独自のアイテムとなり、寄付者は代理 (vekâlet) テキストを受け入れる必要があります。',
  '\\nProxy (vekâlet) required\\n' => 'プロキシ (vekâlet) が必要です',
  '\\nAnimal\\n' => '動物',
  '\\nCattle (7 shares)\\n' => '牛 (7 株)',
  '\\nAll of the meat goes to people in need\\n' => 'すべての肉は困っている人々に寄付されます',
  '\\nMapping for “%s”\\n' => '「%s」のマッピング',
  '\\nThis form charges in%1$sbut the donation type is in%2$s: its payments are stopped until both use the same currency.\\n' => 'このフォームの料金は%1$sですが、寄付タイプは%2$sです。両方が同じ通貨を使用するまで支払いは停止されます。',
  '\\nThis form has no priced choices to map.\\n' => 'このフォームには、マップする価格の選択肢がありません。',
  '\\nForm choice\\n' => 'フォームの選択',
  '\\nUnits\\n' => '単位',
  '\\nform price:%s\\n' => '形式価格:%s',
  '\\nNot mapped (form price)\\n' => 'マッピングされていません (フォーム価格)',
  '\\nQuantity field\\n' => '数量フィールド',
  '\\nFree amount field\\n' => '無料金額フィールド',
  '\\nOn behalf of (names field)\\n' => '(名前フィールド) を代表して',
  '\\nOne name per line. Units without a name are given on behalf of the donor.\\n' => '1 行に 1 つの名前。名前のないユニットは寄付者に代わって提供されます。',
  '\\nProxy consent field\\n' => 'プロキシ同意フィールド',
  '\\nMonthly, weekly or yearly gifts charged automatically by the payment provider.\\n' => '毎月、毎週、または毎年のギフトは、決済プロバイダーによって自動的に請求されます。',
  '\\nName, e-mail, phone, reference...\\n' => '名前、電子メール、電話番号、参照先...',
  '\\nNo recurring donations yet\\n' => '定期的な寄付はまだありません',
  '\\nA recurring donation is created when a payment form is set to charge every day, week, month or year.\\n' => '定期的な寄付は、支払いフォームが毎日、毎週、毎月、または毎年請求されるように設定されている場合に作成されます。',
  '[[\'%srecurring donation\', \'en\']]' . chr(0) . '[[\'%srecurring donations\', \'en\']]' => '%s定期的な寄付',
  '\\nInterval\\n' => '間隔',
  'Started' => '開始しました',
  '\\nNext charge\\n' => '次の充電',
  '\\nAttempt%1$sof%2$sfailed:%3$s\\n' => '%2$sの%1$sの試行が失敗しました:%3$s',
  '\\ncanceled%s\\n' => 'キャンセルされました%s',
  '\\nCancel this recurring donation at the payment provider? No further charges will be made.\\n' => '支払いプロバイダーでこの定期的な寄付をキャンセルしますか?それ以上の料金は発生しません。',
  'WooCommerce' => 'ウーコマース',
  '\\nCard payments: the official iyzico plugin is enabled.\\n' => 'カード支払い: 公式 iyzico プラグインが有効になっています。',
  '\\nCard payments: Flux Donate iyzico (the official iyzico plugin is not enabled).\\n' => 'カード支払い: Flux Donate iyzico (公式 iyzico プラグインは有効になっていません)。',
  '\\nCard payments:%s.\\n' => 'カード支払い:%s。',
  '\\nNo card method is enabled (WooCommerce › Settings › Payments).\\n' => '有効なカード方法はありません (WooCommerce › 設定 › 支払い)。',
  '\\nMonthly donations: Flux Donate iyzico is ready.\\n' => '毎月の寄付: Flux Donate iyzico が準備できました。',
  '\\nMonthly donations are off: enable "Card (iyzico) - Flux Donate" and enter iyzico keys.\\n' => '毎月の寄付はオフです: 「カード (iyzico) - Flux Donate」を有効にして、iyzico キーを入力してください。',
  '\\nBank transfer (donations) is enabled.\', \'en\']]' => '銀行振込 (寄付) が有効になっています。',
  '\\nBank transfer (donations) is disabled.\\n' => '銀行振込(寄付)は無効になっています。',
  '\\nFlux Certificates is connected.\\n' => 'Flux 証明書が接続されました。',
  '\\nFlux Certificates is active but has no active template.\\n' => 'Flux 証明書はアクティブですが、アクティブなテンプレートがありません。',
  '\\nFlux Certificates is not active: no certificate is made after payment.\\n' => 'Flux 証明書がアクティブではありません。支払い後に証明書は作成されません。',
  '\\nDonation page:\\n' => '寄付ページ:',
  '\\nThe donation options are not on a page yet.\\n' => '寄付オプションはまだページにありません。',
  '\\nWooCommerce is not active. Donations are paid through WooCommerce from version 2.0: install and activate WooCommerce.\\n' => 'WooCommerce はアクティブではありません。バージョン 2.0 以降、寄付は WooCommerce を通じて支払われます。WooCommerce をインストールしてアクティブ化します。',
  '\\nSapling packages, prices and badges are edited on the donation type (Donations › Donation types). Which types give a certificate is set there too.\\n' => '苗木のパッケージ、価格、バッジは寄付の種類に応じて編集されます (寄付 › 寄付の種類)。どのタイプが証明書を与えるかもそこに設定されます。',
  'Template' => 'テンプレート',
  '[[\'Automatic ("Fidan Bağış Sertifikası")\\n' => '自動 ("フィダン・バシュ・セルティフィカス")',
  'Event' => 'イベント',
  '\\nWhen chosen, online donation certificates count for this open event.\\n' => '選択すると、オンライン寄付証明書がこのオープン イベントにカウントされます。',
  '\\nSend by\\n' => '送信者',
  '\\nWhen the payment is confirmed the certificate link goes out on these channels. With a WhatsApp route no SMS is sent.\\n' => '支払いが確認されると、証明書のリンクがこれらのチャネルに送信されます。 WhatsApp ルートでは SMS は送信されません。',
  '\\n"Online + printed certificate"\\n' => '「オンライン + 印刷された証明書」',
  '\\nShown as "Coming soon" (cannot be chosen)\\n' => '「近日公開」と表示されます(選択できません)',
  '\\nCan be chosen\\n' => '選択可能',
  'Hidden' => '隠された',
  '\\nPrinted certificate fee (per line)\\n' => '印刷証明書の料金 (1 行あたり)',
  '\\n0 = free. Orders with a printed certificate stay "Processing"; set them to "Completed" when sent.\\n' => '0 = 無料。証明書が印刷された注文は「処理中」のままです。送信時に「完了」に設定します。',
  '\\nComplete paid orders with an online certificate automatically\\n' => 'オンライン証明書を使用して有料注文を自動的に完了します',
  '\\nIBAN, recipient and reference code: WooCommerce › Settings › Payments › Bank transfer (donations). The transfer details and the receipt link are added to WooCommerce\\\'s "on hold" e-mail.\\n' => 'IBAN、受信者および参照コード: WooCommerce › 設定 › 支払い › 銀行振込 (寄付)。送金の詳細と受領リンクが WooCommerce の「保留中」電子メールに追加されます。',
  '\\nShort notification\\n' => '簡単な通知',
  '\\nA short message to the donor\\\'s phone when a transfer is registered (through Flux Mail, or Flux Certificates\\\'s providers). With both ticked, SMS only goes out when there is no WhatsApp route.\\n' => '(Flux Mail または Flux Certificates のプロバイダー経由で) 送金が登録されるときの、寄付者の電話への短いメッセージ。両方にチェックを入れると、WhatsApp ルートがない場合にのみ SMS が送信されます。',
  '\\nWhatsApp text\\n' => 'WhatsApp のテキスト',
  '\\nPlaceholders:{ad}{tutar}{siparis}{alici}{iban}{aciklama}{link}{site}\\n' => 'プレースホルダー:{ad}{tutar}{siparis}{alici}{iban}{aciklama}{link}{site}',
  '\\nSMS text\\n' => 'SMS テキスト',
  '\\nLargest receipt file (MB)\\n' => '最大のレシート ファイル (MB)',
  '\\nTell this address when a receipt is uploaded\\n' => '領収書をアップロードするときにこのアドレスを教えてください',
  'Cart and checkout' => 'カートとチェックアウト',
  '\\nAfter "Donate"\\n' => '「寄付」後',
  '\\nGo straight to the checkout\\n' => 'そのままチェックアウトに進んでください',
  '\\nGo to the cart\\n' => 'カートに移動します',
  '\\nStay on the page\\n' => 'ページに留まります',
  '\\nCurrencies donors can choose\\n' => '寄付者が選択できる通貨',
  '\\n(store currency)\\n' => '(ストア通貨)',
  '\\nWith more than one, donors pick the currency (shortcode [flx_bagis_para_birimi] or the theme). There are no exchange rates: set each option\\\'s price per currency on the donation type; options without a price in a currency are not offered in it. Check that your payment methods take these currencies.\', \'en\']]' => '複数の場合、寄付者は通貨 (ショートコード [flx_bagis_para_birimi] またはテーマ) を選択します。為替レートはありません。寄付の種類に応じて通貨ごとの各オプションの価格を設定します。通貨での価格のないオプションは提供されません。お支払い方法でこれらの通貨が利用できることを確認してください。',
  '\\nDo not ask for an address at the checkout when the cart holds only donations\\n' => 'カートに寄付のみが入っている場合は、チェックアウト時に住所を尋ねないでください',
  '\\nSupport WhatsApp number\\n' => 'WhatsApp 番号をサポート',
  '\\nShown at the checkout and with the bank transfer details as "Any trouble? Write to us on WhatsApp". Leave empty to hide.\\n' => 'チェックアウト時に「何か問題がありましたら、WhatsApp にご連絡ください」という銀行振込の詳細が表示されます。非表示にするには空のままにしておきます。',
  '\\n— Choose —\\n' => '— 選択 —',
  '\\n"Donate" links and the hidden product pages go here.\\n' => '「寄付」リンクと非表示の製品ページはここにあります。',
  '\\nCard payment method\\n' => 'カード支払い方法',
  '\\nAutomatic: another virtual POS if one is enabled (e.g. EsnekPOS), otherwise iyzico\\n' => '自動: 有効な場合は別の仮想 POS (EsnekPOS など)、そうでない場合は iyzico',
  '\\niyzico\\n' => 'iyzico',
  '\\nShow every enabled card method\', \'en\']]' => '有効なカード メソッドをすべて表示',
  '\\nDonors see one card method; now:%s. Monthly donations always use Flux Donate iyzico (it stores the card). Bank transfer is always shown.\\n' => '寄付者には 1 つのカード方式が表示されます。現在:%s。毎月の寄付には常に Flux Donate iyzico を使用します (カードを保存します)。銀行振込は常に表示されます。',
  '\\nall\\n' => '\\n\\n',
  '\\nShow other payment plugins on the checkout block\\n' => 'チェックアウト ブロックに他の支払いプラグインを表示します',
  '\\nVirtual POS plugins that take the card on their own page but have no checkout block support (for example EsnekPOS) are added to the Checkout block. Plugins with their own card fields need the classic checkout.\\n' => 'カードを独自のページに表示するが、チェックアウト ブロックをサポートしていない仮想 POS プラグイン (EsnekPOS など) は、チェックアウト ブロックに追加されます。独自のカード フィールドを持つプラグインには、クラシック チェックアウトが必要です。',
  '\\nFlux Forms payment forms continue on the WooCommerce checkout\\n' => 'Flux Forms 支払いフォームは引き続き WooCommerce チェックアウトで使用できます',
  '\\nThe donor picks card or bank transfer there; the form entry, the certificate automation and the donation record are completed when the order is paid.\\n' => '寄付者はそこでカードまたは銀行振込を選択します。注文の支払いが完了すると、フォームの入力、証明書の自動化、寄付の記録が完了します。',
  '\\nCard payment screen\\n' => 'カード決済画面',
  '\\nOur own card fields on the checkout (3D Secure, installments, saved cards)\\n' => 'チェックアウト時の独自のカード フィールド (3D セキュア、分割払い、保存されたカード)',
  '\\niyzico payment page (as before)\\n' => 'iyzico 支払いページ (以前と同様)',
  '\\nOfficial iyzico plugin for one-time donations\\n' => '1 回限りの寄付用の公式 iyzico プラグイン',
  '\\nCard numbers go straight to iyzico and are never stored on this site. Monthly donations always use Flux Donate iyzico (it stores the card).\\n' => 'カード番号は iyzico に直接送信され、このサイトに保存されることはありません。毎月の寄付には常に Flux Donate iyzico を使用します (カードが保存されます)。',
  '\\nMost installments\\n' => 'ほとんどの分割払い',
  '[["Single payment only\\n' => '一括支払いのみ',
  '[[\'With our own card fields. The options and any interest come from iyzico for each card.\\n' => '独自のカードフィールド付き。オプションと利息は各カードの iyzico から提供されます。',
  '\\nAdd the "Donation options" block to any page, or create a ready page:\\n' => '「寄付オプション」ブロックを任意のページに追加するか、準備ができたページを作成します:',
  '\\nCreate the online donation page\\n' => 'オンライン寄付ページを作成します',
  '\\nProduct list (XML)\\n' => '製品リスト (XML)',
  '\\nFor iyzico "upload your products with XML" and Google Merchant Center. Every fixed-price option on sale is one product; free amounts are left out. Updating daily is enough.\\n' => 'iyzico の場合は、「XML を使用して商品をアップロード」および Google Merchant Center を使用します。販売されている固定価格オプションはすべて 1 つの製品です。無料の金額は省略されています。毎日更新するだけで十分です。',
  'Address' => '住所',
  '\\nShortcode and block\\n' => 'ショートコードとブロック',
  '\\nWithout attributes it shows the donation types marked "Show in the Donation options block". tur="slug1,slug2" shows only those types; sekme="slug" opens that type\\\'s tab first. In the editor: "Donation options" block.\\n' => '属性がないと、「寄付オプション ブロックに表示」とマークされた寄付タイプが表示されます。 tur="slug1,slug2" はそれらのタイプのみを表示します。 sekme="slug" は、最初にそのタイプのタブを開きます。エディタ内: 「寄付オプション」ブロック。',
  'Online donation' => 'オンライン寄付',
  '\\nChoose a sapling package or give any amount you like. You can pay by card or bank transfer; a certificate is made in your name.\\n' => '苗木のパッケージを選択するか、お好きな量を与えてください。カードまたは銀行振込でお支払いいただけます。証明書はあなたの名前で作成されます。',
  '\\nOnline donation page\\n' => 'オンライン寄付ページ',
  '\\nHow this type appears in the "Donation options" block and the WooCommerce cart. Its hidden WooCommerce product is kept in step automatically.\\n' => 'このタイプが「寄付オプション」ブロックと WooCommerce カートにどのように表示されるか。非表示の WooCommerce 製品は自動的に同期されます。',
  '[[\'Show in the "Donation options" block (donation page) and the product XML\\n' => '「寄付オプション」ブロック (寄付ページ) と製品 XML に表示されます',
  '\\nGive a certificate (Flux Certificates)\\n' => '証明書を与える (Flux 証明書)',
  'Certificate template' => '証明書テンプレート',
  '\\nSame as the WooCommerce settings\\n' => 'WooCommerce 設定と同じ',
  '\\nOption with a − / + quantity\\n' => '- / + 数量のオプション',
  '\\nThis option\\\'s card gets − / + buttons (e.g. "1 sapling"); price = number × this option\\\'s price, checked again on the server. The other options stay fixed packages. Use "Maximum quantity" above for the limit.\\n' => 'このオプションのカードには - / + ボタンが表示されます (例: 「1 苗木」);価格 = 数値 × このオプションの価格。サーバー上で再度確認されます。他のオプションは固定パッケージのままです。制限には上記の「最大数量」を使用してください。',
  '\\nPreset amounts (free amount)\\n' => 'プリセット金額 (無料金額)',
  '\\nSeparated by spaces, e.g. 250 500 1000.\\n' => 'スペースで区切ります。例: 250 500 1000。',
  '\\nPreset amounts in%s\\n' => '%sのプリセット量 ',
  '\\nPage address\\n' => 'ページアドレス',
  '\\nOptional: where its product page and the product XML link go. Empty = the donation page in the WooCommerce settings.\\n' => 'オプション: 製品ページと製品 XML リンクの場所。空 = WooCommerce 設定の寄付ページ。',
  '\\nWooCommerce product #%d(hidden from the shop).\\n' => 'WooCommerce 製品番号%d(ショップでは非表示)。',
  '\\nThis order has no donation line.\\n' => 'この注文には寄付ラインがありません。',
  '\\nDonation records:\\n' => '寄付記録:',
  '\\nReference code:\\n' => '参照コード:',
  '\\nMake the certificate\\n' => '証明書を作成します',
  '\\nRefund this amount to the donor\'s card?\\n' => 'この金額を寄付者のカードに返金しますか?',
  '\\nRecord this refund? The money is not sent back automatically for this payment method.\\n' => 'この払い戻しを記録しますか?この支払い方法では、お金は自動的に返金されません。',
  '\\nRecord refund\\n' => '払い戻しを記録する',
  '\\nRefunded through WooCommerce and the payment method; the record follows.\\n' => 'WooCommerce および支払い方法を通じて返金されます。記録が続きます。',
  '\\nRecorded in WooCommerce only: send the money back yourself (e.g. by bank transfer).\\n' => 'WooCommerce でのみ記録されます: ご自身で返金してください (銀行振込など)。',
  'Order not found.' => '注文が見つかりません。',
  '\\nOrder line not found.\\n' => '注文明細行が見つかりません。',
  '\\nEnter an amount up to what is left to refund.\\n' => '払い戻し可能な残額までの金額を入力してください。',
  '\\nRefunded from Flux Donate by%s\\n' => '%sによる Flux Donate から返金されました ',
  '\\nNo donation lines.\\n' => '寄付ラインはありません。',
  '\\nUnknown donation type.\\n' => '寄付の種類が不明です。',
  '\\nThe donation product could not be created.\\n' => '寄付商品を作成できませんでした。',
  'Enter an amount.' => '金額を入力します。',
  '\\nRecorded in Flux Chat (donation #%d).\\n' => 'Flux Chat に記録されました (寄付 #%d)。',
  '\\nCanceled in Flux Donate.\\n' => 'Flux Donate でキャンセルされました。',
  '\\nPut on hold in Flux Donate.\\n' => 'Flux Donate を保留します。',
  '\\nMarked as failed in Flux Donate.\\n' => 'Flux Donate で失敗としてマークされました。',
  '\\nThis payment link has expired. Please fill in the form again.\\n' => 'この支払いリンクの有効期限が切れています。フォームにもう一度入力してください。',
  '\\nFlux Forms entry%scompleted by this payment.\\n' => 'この支払いにより、Flux Forms エントリ%sが完了しました。',
  '\\nAfter you place the order you will see the IBAN and your own reference code. Once you have paid you can upload the receipt on the site; your certificate is sent when the payment is confirmed.\\n' => '注文すると、IBAN と独自の参照コードが表示されます。支払いが完了したら、サイトに領収書をアップロードできます。支払いが確認されると証明書が送信されます。',
  'Recipient' => '受信者',
  'Bank' => '銀行',
  'Reference' => '参考資料',
  '\\nYour pre-registration is in\\n' => '事前登録は完了しています',
  '\\nTo complete your donation, make a bank transfer to the account below. Please write your own reference code in the description.\\n' => '寄付を完了するには、以下の口座に銀行振込を行ってください。説明に独自の参照コードを記述してください。',
  'Make the bank transfer' => '銀行振込をする',
  '\\nThe reference code lets us match your payment to your donation.\\n' => '参照コードを使用すると、お支払いと寄付を照合できます。',
  'Upload your receipt' => '領収書をアップロードする',
  '[[\'Receive your certificate\\n' => '証明書を受け取ります',
  '\\nOnce the payment is confirmed your certificate is sent by WhatsApp and e-mail; it also appears under My account › Orders.\\n' => '支払いが確認されたら、証明書は WhatsApp と電子メールで送信されます。 [マイ アカウント] › [注文] にも表示されます。',
  '\\nWe confirm your donation\\n' => 'あなたの寄付を確認します',
  '\\nOnce the payment is confirmed the order is completed and you get an e-mail; it also appears under My account › Orders.\\n' => '支払いが確認されると注文が完了し、電子メールが届きます。 [マイ アカウント] › [注文] にも表示されます。',
  '\\nMy pending donations\\n' => '保留中の寄付',
  'Bank transfer details' => '銀行振込の詳細',
  'After paying, upload your receipt:' => '支払い後、領収書をアップロードします。',
  'Please write the reference above in the transfer description. After paying, upload your receipt:' => '転送説明に上記の参照先を記載してください。支払い後、領収書をアップロードします。',
  'Upload receipt' => '領収書のアップロード',
  '\\nCard number\\n' => 'カード番号',
  '\\nName on the card\\n' => 'カード上の名前',
  '\\nExpiry (MM/YY)\\n' => '有効期限 (MM/YY)',
  'context_def6e4575e04\\nMM/YY\\n' => 'MM/YY',
  '\\nCVC\\n' => 'CVC',
  '\\nSave my card for next time\\n' => '次回のためにカードを保存してください',
  '\\niyzico keeps the card; this site never stores card numbers.\\n' => 'iyzico はカードを保持します。このサイトではカード番号は保存されません。',
  '\\nFor the monthly donation iyzico keeps your card and charges it once a month. You can cancel at any time.\\n' => '毎月の寄付については、iyzico がカードを保管し、月に 1 回請求します。いつでもキャンセルできます。',
  '\\nUse another card\\n' => '別のカードを使用してください',
  '\\nYour saved cards\\n' => '保存したカード',
  '\\nInstallments\\n' => '分割払い',
  '\\nSingle payment\', \'en\']]' => '一括支払い',
  '\\n%1$sinstallments ×%2$s(total%3$s)\\n' => '%1$s分割払い ×%2$s(合計%3$s)',
  '\\nInstallment options appear after the card number.\\n' => 'インストール オプションはカード番号の後に表示されます。',
  '\\nPlease check the card number.\\n' => 'カード番号を確認してください。',
  '\\nPlease write the name on the card.\\n' => 'カードに名前を書いてください。',
  '\\nPlease check the expiry date.\\n' => '有効期限を確認してください。',
  '\\nPlease check the security code (CVC).\\n' => 'セキュリティ コード (CVC) を確認してください。',
  '[[\'Paid with 3D Secure through iyzico. Your bank may send you a code.\\n' => 'iyzico を通じて 3D セキュアで支払いました。銀行からコードが送信される場合があります。',
  '\\nTest mode: use an iyzico test card, e.g. 5528 7900 0000 0008, 12/30, 123.\', \'en\']]' => 'テスト モード: iyzico テスト カードを使用します。 5528 7900 0000 0008、12/30、123.',
  '\\nFill in the test card\', \'en\']]' => 'テストカードに記入してください',
  '\\nTest mode accepts only iyzico test cards. Use "Fill in the test card".\\n' => 'テスト モードでは、iyzico テスト カードのみが受け入れられます。 「テスト カードに記入」を使用してください。',
  '\\nCard payments are not configured on this site. Please choose another payment method.\\n' => 'このサイトではカード支払いが設定されていません。別のお支払い方法を選択してください。',
  '\\nThe amount must be greater than zero.\\n' => '金額はゼロより大きくなければなりません。',
  '\\nThis saved card cannot be used any more. Please enter the card.\\n' => 'この保存されたカードはもう使用できません。カードを入力してください。',
  '\\nThis installment option is not available for the card. Please choose another.\\n' => 'このカードではこの分割払いオプションは利用できません。別のものを選択してください。',
  '\\nCard payment could not start:%1$s(card%2$s,%3$s).\\n' => 'カード支払いを開始できませんでした:%1$s(カード%2$s、%3$s)。',
  '\\ntest mode\\n' => 'テストモード',
  '\\nlive\\n' => 'ライブ',
  '\\nCard payment started:%1$sinstallments,%2$scharged by the bank.\\n' => 'カード支払いが開始されました:%1$s分割払い、銀行によって%2$s請求されます。',
  '\\niyzico 3D Secure:%s\\n' => 'iyzico 3D セキュア:%s',
  '\\nThe bank did not confirm the 3D Secure code. Please try again.\\n' => '銀行は 3D セキュア コードを確認しませんでした。もう一度試してください。',
  '\\nThis card is not enrolled for 3D Secure. Please call your bank or use another card.\\n' => 'このカードは 3D セキュアに登録されていません。銀行に電話するか、別のカードを使用してください。',
  '\\nThe bank could not check the card. Please try again or use another card.\\n' => '銀行はカードを確認できませんでした。もう一度試すか、別のカードを使用してください。',
  '\\niyzico: the payment was not completed (%s).\\n' => 'iyzico: 支払いは完了しませんでした (%s)。',
  '[[\'Default address\\n' => 'デフォルトのアドレス',
  '\\nThe page has expired. Please try again.\\n' => 'ページの有効期限が切れています。もう一度試してください。',
  '\\nPlease fill in the name, address and city.\\n' => '名前、住所、市区町村を入力してください。',
  'Address saved.' => 'アドレスが保存されました。',
  '\\nAddress deleted.\\n' => 'アドレスが削除されました。',
  '\\nDefault address changed.\\n' => 'デフォルトのアドレスが変更されました。',
  '\\nAddress book\\n' => 'アドレス帳',
  '\\nSaved addresses are offered in a list at the checkout. The default one is filled in automatically.\\n' => '保存された住所はチェックアウト時にリストに表示されます。デフォルトの値は自動的に入力されます。',
  'Default' => 'デフォルト',
  'Make default' => 'デフォルトにする',
  '\\nDelete this address?\\n' => 'このアドレスを削除しますか?',
  '\\n+ Add a new address\\n' => '+ 新しいアドレスを追加',
  '\\nAddress name\\n' => 'アドレス名',
  '\\ne.g. Home, Office\\n' => 'e.g.自宅、オフィス',
  'Save address' => '保存アドレス',
  '\\nSaved address\\n' => '保存されたアドレス',
  '\\nWrite the new address below; it is saved to your address book with the order.\\n' => '新しいアドレスを下に記入してください。注文と一緒にアドレス帳に保存されます。',
  '\\nManage addresses\\n' => 'アドレスの管理',
  '\\nKeys are read from the iyzico WooCommerce plugin settings.\\n' => 'キーは iyzico WooCommerce プラグイン設定から読み取られます。',
  '\\nKeys are read from Donations › Settings › Payments › iyzico.\\n' => 'キーは、寄付 › 設定 › 支払い › iyzico から読み取られます。',
  '\\nNo iyzico keys found. Enter them in the iyzico WooCommerce plugin or in Donations › Settings › Payments › iyzico.\\n' => 'iyzico キーが見つかりません。これらを iyzico WooCommerce プラグインまたは寄付 › 設定 › 支払い › iyzico に入力してください。',
  '\\nEnvironment: sandbox (test).\\n' => '環境: サンドボックス (テスト)。',
  '\\nEnvironment: live.\\n' => '環境: ライブ。',
  '\\niyzico reported a payment (%s) that does not match this order (amount, currency or basket). Check it in the iyzico panel before doing anything.\\n' => 'iyzico は、この注文 (金額、通貨、またはバスケット) と一致しない支払い (%s) を報告しました。何かを行う前に、iyzico パネルで確認してください。',
  '\\niyzico payment received:%1$s, payment id%2$s(%3$s).\\n' => 'iyzico 支払いを受け取りました:%1$s、支払い ID%2$s(%3$s)。',
  '\\nEnter an amount to refund.\\n' => '返金する金額を入力してください。',
  '\\nThis order has no iyzico transaction to refund.\\n' => 'この注文には返金する iyzico トランザクションがありません。',
  '\\nThe amount is more than what is left to refund at iyzico.\\n' => '金額が iyzico で返金できる残額を超えています。',
  '\\niyzico refused the refund:%s\\n' => 'iyzico が払い戻しを拒否しました:%s',
  '\\nRefunded at iyzico:%1$s.%2$s\\n' => 'iyzico で返金:%1$s。%2$s',
  '\\nClassic\\n' => 'クラシック',
  '\\nOne card: type tabs on top, the choices under them, the total at the bottom.\\n' => '1 枚のカード: 上部にタブ、その下に選択肢、下部に合計を入力します。',
  '\\nA · Steps + summary\\n' => 'A · 手順 + 概要',
  '\\nNumbered steps on the left, a summary with the total and the button on the right.\\n' => '左側に番号付きのステップ、右側に合計の概要とボタンが表示されます。',
  '\\nB · Two panels\\n' => 'B · 2 つのパネル',
  '\\nTypes as a list on the left, the details on the right; a dark total bar.\\n' => '左側にリストとして入力し、右側に詳細を入力します。暗い合計バー。',
  '\\nC · Picture cards\\n' => 'C · 絵カード',
  '[[\'Large cards with the type picture or icon; the details open below.\\n' => 'タイプの画像またはアイコンが付いた大きなカード。詳細は以下で開きます。',
  'List' => 'リスト',
  '\\nAll options one under the other.\\n' => 'すべてのオプションは下にあります。',
  '\\nDrop-down\\n' => 'ドロップダウン',
  '\\nOne row: the option in a drop-down menu and the quantity beside it.\\n' => '1 行: ドロップダウン メニューのオプションとその横の数量。',
  '\\nList, then one row\\n' => 'リスト、次に 1 行',
  '\\nThe list first; after a pick it folds into one row (drop-down + quantity) and the rest of the form opens.\\n' => 'リストが最初です。選択後、1 行 (ドロップダウン + 数量) に折りたたまれ、フォームの残りの部分が開きます。',
  'Theme' => 'テーマ',
  '\\nThe look of WooCommerce and the theme.\\n' => 'WooCommerce の外観とテーマ。',
  'A · Side-by-side cards' => 'A・サイドバイサイドカード',
  '\\nMethods as cards with icons; the details of the picked one below.\\n' => 'アイコン付きのカードとしてのメソッド。選択したものの詳細は以下をご覧ください。',
  'B · Plain list' => 'B・プレーンリスト',
  '\\nRows one under the other; the picked row opens.\\n' => '行を上下に並べます。選択した行が開きます。',
  'C · Segmented tabs' => 'C · 分割されたタブ',
  '\\nOne row of tab buttons; the details of the picked one below.\\n' => '1 行のタブ ボタン。選択したものの詳細は以下をご覧ください。',
  '\\nOptions and amount\\n' => 'オプションと金額',
  '\\nOn whose behalf\\n' => '誰に代わって',
  '\\nCertificate design\\n' => '証明書のデザイン',
  '\\nRepeat every month\\n' => '毎月繰り返します',
  'Appearance' => '外観',
  'Donation form' => '寄付フォーム',
  '\\nHow the "Donation options" block looks on the site. Prices, options and names are set under Donation types.\\n' => 'サイト上の「寄付オプション」ブロックの外観。価格、オプション、名前は「寄付の種類」で設定します。',
  '\\nView the page\\n' => 'ページを見る',
  '\\nHeading over the types\\n' => 'タイプの見出し',
  '\\nShown in the A and C layouts.\\n' => 'A および C レイアウトで表示されます。',
  '\\nHeading over the options\\n' => 'オプションの見出し',
  '\\nChoose an option\\n' => 'オプションを選択してください',
  '\\nHow the options are shown\\n' => 'オプションの表示方法',
  '\\nOrder of the sections\\n' => 'セクションの順序',
  '\\nThe type choice is always first and the total always last. Sections a type does not use are skipped.\\n' => 'タイプの選択は常に最初であり、合計は常に最後になります。タイプが使用しないセクションはスキップされます。',
  '\\nAsk a phone number for every share (types with a proxy). The video or certificate of that share can be sent there too.\\n' => 'すべての共有について電話番号を尋ねます (プロキシを使用するタイプ)。その共有のビデオまたは証明書もそこに送信できます。',
  '\\nPayment options at the checkout\\n' => 'チェックアウト時の支払いオプション',
  '\\nHow card, PayPal, bank transfer and the other methods are shown. The methods themselves are turned on under WooCommerce › Settings › Payments.\\n' => 'カード、PayPal、銀行振込、その他の方法が表示されます。メソッド自体は、「WooCommerce」 > 「設定」 > 「支払い」で有効になります。',
  '\\nColours and corners\\n' => '色と角',
  '\\nUsed by the form and the payment options. Empty fields follow the theme.\\n' => 'フォームと支払いオプションで使用されます。空のフィールドはテーマに従います。',
  'Main colour' => 'メインカラー',
  'Accent colour' => 'アクセントカラー',
  '\\nCorner radius (px)\\n' => 'コーナー半径 (ピクセル)',
  '\\n0 = square, 4 = plain corporate, 16 = round.\\n' => '0 = 正方形、4 = 普通の企業、16 = 円形。',
  '\\nTransaction fee\\n' => '取引手数料',
  '\\nDonors can choose to also pay the fee of the payment method, so the whole donation reaches you. The fee is added at the checkout for the method they pick.\\n' => '寄付者は、寄付金全額が届くように、支払い方法の手数料も支払うことを選択できます。料金は、選択した方法に応じてチェックアウト時に追加されます。',
  '\\nShow "I will cover the transaction fee" on the donation form\\n' => '寄付フォームに「取引手数料は私が負担します」と表示します',
  '\\nTicked by default\\n' => 'デフォルトでチェックマークが付いています',
  '\\nFixed\\n' => '修正されました',
  '\\nEmpty or 0 = no fee for that method (for example bank transfer). Fee = donation × % + fixed.\\n' => '空または 0 = その方法 (銀行振込など) の手数料はかかりません。料金 = 寄付 × % + 固定。',
  '\\nPlease choose what you would like to donate for.\\n' => '寄付したいものを選択してください。',
  '\\nThis option cannot be donated in%s. Please choose another currency.\\n' => 'このオプションは%sでは寄付できません。別の通貨を選択してください。',
  '\\nThis option cannot be donated online at the moment.", \'en\']]' => 'このオプションは現時点ではオンラインで寄付できません。',
  '\\nThe number must be between 1 and%s.\', \'en\']]' => '数値は 1 ~%sの間である必要があります。',
  '\\nThe amount must be at least%s.\\n' => '金額は少なくとも%sである必要があります。',
  '\\nFor this amount please get in touch with us.\\n' => 'この金額については、お問い合わせください。',
  '\\nPlease choose an option.\\n' => 'オプションを選択してください。',
  '\\nPrinted certificates are not available yet. Please choose the online certificate.\\n' => '印刷された証明書はまだ利用できません。オンライン証明書を選択してください。',
  '\\nPlease write the postal address for the printed certificate.\\n' => '印刷された証明書の住所を記入してください。',
  '\\nPlease write the name of the person you are donating for.\\n' => '寄付する人の名前を書いてください。',
  '\\nThis donation needs a proxy (vekâlet) consent, but it is not set up yet. Please contact the site administrator.\\n' => 'この寄付には代理人 (vekâlet) の同意が必要ですが、まだ設定されていません。サイト管理者に連絡してください。',
  '\\nThe proxy (vekâlet) text has been updated. Please read it again and accept it.\\n' => 'プロキシ (vekâlet) テキストが更新されました。もう一度読んで同意してください。',
  '[[\'Please write at most%sname (one per share).\', \'en\']]' . chr(0) . '[[\'Please write at most%snames (one per share).\', \'en\']]' => '%s名は最大でも 1 つずつ書いてください (シェアごとに 1 つ)。',
  '\\nThe phone number does not look right. Example: 0532 123 45 67\\n' => '電話番号が正しくありません。例: 0532 123 45 67',
  '\\nThe e-mail address does not look right.\\n' => '電子メール アドレスが正しくありません。',
  '\\nThis cause does not take monthly donations.\\n' => 'この活動には毎月の寄付は必要ありません。',
  '\\nMonthly donations are not available at the moment.\\n' => '現在、毎月の寄付はご利用いただけません。',
  '\\nDonations in%scannot be paid here at the moment.\\n' => '%sでの寄付は、現時点ではここでお支払いいただけません。',
  '\\nThe donation product could not be found.\\n' => '寄付製品が見つかりませんでした。',
  '\\nIt could not be added to the cart.\\n' => 'カートに追加できませんでした。',
  '\\nA donation in your cart cannot be paid in%sand was removed.\\n' => 'カート内の寄付は%sで支払うことができないため、削除されました。',
  '\\nA donation in your cart is no longer available and was removed.\\n' => 'カート内の寄付は利用できなくなったため、削除されました。',
  '\\nPrinted certificates can only be paid in the store currency; your certificate will be sent online.\\n' => '印刷された証明書はストア通貨でのみ支払うことができます。証明書はオンラインで送信されます。',
  '\\nProducts in your cart can only be paid in%1$s.<a href="%2$s">Switch to%1$s</a>\\n' => 'カート内の商品は%1$sでのみお支払いいただけます。<a href="%2$s">%1$s</a>に切り替えます ',
  '\\nPrinted certificate delivery\\n' => '印刷された証明書の配信',
  '\\nRepeats\\n' => '繰り返し',
  'Every month' => '毎月',
  '[[\'Names (one per share)\\n' => '名前 (共有ごとに 1 つ)',
  '\\nDesign\\n' => 'デザイン',
  '\\nName on the certificate\\n' => '証明書の名前',
  '\\nSent to\\n' => '送信先',
  '\\ncopy to me\\n' => '私にコピーしてください',
  '\\nPostal address\\n' => '郵便番号',
  '\\naccepted (text version%s)\\n' => '受け入れられました (テキスト バージョン%s)',
  '\\nOnline + printed\\n' => 'オンライン + 印刷',
  'Online' => 'オンライン',
  '\\n%sSapling Donation\\n' => '%s苗木の寄付',
  '\\nCertificate no\\n' => '証明書がありません',
  '\\nThe certificate could not be made: no Flux Certificates template was found (Donations › Settings › WooCommerce).\\n' => '証明書を作成できませんでした。Flux 証明書テンプレートが見つかりませんでした (寄付 › 設定 › WooCommerce)。',
  '\\nThe certificate could not be made:%s\\n' => '証明書を作成できませんでした:%s',
  '\\nNot sent yet.\\n' => 'まだ送信されていません。',
  '\\nCertificate made:%1$s(%2$s).%3$s\\n' => '作成された証明書:%1$s(%2$s)。%3$s',
  '\\nCertificates made again (%d); the old ones were revoked.\\n' => '証明書が再度作成されました (%d);古いものは取り消されました。',
  '\\nNo delivery channel is chosen.\\n' => '配信チャネルが選択されていません。',
  '\\nQueued:%s.\\n' => 'キューに登録されました:%s。',
  '\\nCopy to the donor:%s.\\n' => '寄付者にコピーします:%s。',
  'Link copied' => 'リンクがコピーされました',
  '\\nThe preview could not be drawn. You can open it with "View certificate".\\n' => 'プレビューを描画できませんでした。 「証明書の表示」で開くことができます。',
  '[[\'Your certificate is ready\', \'en\']]' . chr(0) . '[[\'Your certificates are ready\', \'en\']]' => '証明書の準備ができました',
  '\\nNo:%s\\n' => 'いいえ:%s',
  'Download PDF' => 'PDFをダウンロード',
  '\\nView certificate\\n' => '証明書を表示',
  '\\nYour certificate is being prepared. It will be sent by WhatsApp and e-mail in a few minutes; you can also refresh this page to see it.\\n' => '証明書を準備中です。数分以内に WhatsApp と電子メールで送信されます。このページを更新して表示することもできます。',
  '\\nThis certificate design cannot be chosen any more. Please pick another one.\\n' => 'この証明書のデザインはもう選択できません。別のものを選択してください。',
  '\\nPlease fill in "%s" for the certificate.\\n' => '証明書には「%s」と入力してください。',
  '\\nPick the design of your certificate. The donation amount does not change.\\n' => '証明書のデザインを選択してください。寄付額は変わりません。',
  'Standard' => '標準',
  '\\n"%s" was paid once: the card was not stored, so it will not repeat monthly.\\n' => '「%s」は一度支払われました: カードは保存されていないため、毎月繰り返されることはありません。',
  '\\n"%1$s" repeats monthly (recurring donation #%2$d); the card is stored at iyzico.\\n' => '「%1$s」は毎月繰り返されます (定期的な寄付 #%2$d)。カードは iyzico に保管されます。',
  '\\nCard (iyzico), monthly\\n' => 'カード (iyzico)、毎月',
  '\\nMonthly renewal of recurring donation #%1$d(first order #%2$s).\\n' => '定期的な寄付 #%1$dの毎月の更新 (最初の注文 #%2$s)。',
  '\\nMonthly charge accepted by iyzico:%1$s, payment id%2$s.\\n' => 'iyzico が受け入れた月額料金:%1$s、支払い ID%2$s。',
  '\\nMonthly charge failed after the last attempt:%s\\n' => '最後の試行後に月額請求が失敗しました:%s',
  '\\nMonthly charge failed, it will be retried:%s\\n' => '月額請求に失敗しました。再試行されます:%s',
  '\\nFlux Donate always uses EsnekPOS\'s secure payment page; the bank asks for 3D Secure there when needed.\\n' => 'Flux Donate は常に EsnekPOS の安全な支払いページを使用します。銀行は必要に応じて 3D セキュアを要求します。',
  '\\nFlux Donate\\n' => 'フラックス寄付',
  '\\nFlux Donate runs this payment method: classic and block checkout, payment links without a cart, and every payment is confirmed with EsnekPOS from the server before the order is marked paid. For a test, enter merchant TEST1234 and the test merchant key from EsnekPOS\\\'s developer page.\\n' => 'Flux Donate は、この支払い方法を実行します。クラシック チェックアウトとブロック チェックアウト、カートを使用しない支払いリンク、注文が支払い済みとしてマークされる前に、すべての支払いがサーバーから EsnekPOS で確認されます。テストするには、EsnekPOS の開発者ページから販売者 TEST1234 とテスト販売者キーを入力します。',
  '\\nDonation #%d\\n' => '寄付 #%d',
  '\\nEsnekPOS did not answer (HTTP%d).\\n' => 'EsnekPOS が応答しませんでした (HTTP%d)。',
  '\\nEsnekPOS payment could not start:%s\\n' => 'EsnekPOS 支払いを開始できませんでした:%s',
  '\\nEsnekPOS payment could not start:%1$s(%2$s).\\n' => 'EsnekPOS 支払いを開始できませんでした:%1$s(%2$s)。',
  '\\nThe payment is being checked. Please wait a moment and refresh the page.\\n' => '支払いを確認中です。しばらく待ってからページを更新してください。',
  '\\nEsnekPOS payment could not be checked:%s\\n' => 'EsnekPOS 支払いを確認できませんでした:%s',
  '\\nThe payment could not be verified yet. If money was taken from your card, please contact us before trying again.\\n' => '支払いはまだ確認できませんでした。カードからお金が引き落とされた場合は、再試行する前に当社にご連絡ください。',
  '\\nEsnekPOS payment received: reference%1$s,%2$sinstallment(s),%3$scharged.\\n' => 'EsnekPOS 支払いを受け取りました: 参照%1$s、%2$s分割払い、%3$sが請求されました。',
  '\\nEsnekPOS reported a payment (%s) that does not match this order (amount or reference). Check it in the EsnekPOS panel before doing anything.\\n' => 'EsnekPOS は、この注文 (金額または参照) と一致しない支払い (%s) を報告しました。何かを行う前に、EsnekPOS パネルで確認してください。',
  '\\nEsnekPOS return said success but EsnekPOS did not confirm the payment:%s\\n' => 'EsnekPOS 返品は成功と表示されましたが、EsnekPOS は支払いを確認しませんでした:%s',
  '\\nEsnekPOS: the payment was not completed (%s).\\n' => 'EsnekPOS: 支払いが完了しませんでした (%s)。',
  '\\nTest mode (merchant TEST1234).\\n' => 'テスト モード (マーチャント TEST1234)。',
  '\\nFlux Donate sends the order lines, no cart needed.\\n' => 'Flux Donate は注文明細を送信します。カートは必要ありません。',
  '\\nFlux Donate asks EsnekPOS (ProcessQuery) before the order is marked paid.\\n' => 'Flux Donate は、注文が支払い済みとしてマークされる前に EsnekPOS (ProcessQuery) を要求します。',
  '\\nOn EsnekPOS\\\'s payment page, as set in the EsnekPOS panel.\\n' => 'EsnekPOS パネルで設定された EsnekPOS の支払いページ。',
  '\\nRefund in the EsnekPOS panel, then mark the order refunded.\\n' => 'EsnekPOS パネルで返金し、注文に返金済みのマークを付けます。',
  '[[\'Donation of%1$ssapling.%2$splants it for you and sends an online certificate in your name. Pay by card or bank transfer.\', \'en\']]' . chr(0) . '[[\'Donation of%1$ssaplings.%2$splants them for you and sends an online certificate in your name. Pay by card or bank transfer.\', \'en\']]' => '%1$sの苗木の寄付。%2$sはあなたのためにそれらを植え、あなたの名前でオンライン証明書を送信します。カードまたは銀行振込でお支払いください。',
  '\\nDonation packages\\n' => '寄付パッケージ',
  '\\nDonation >%s\\n' => '寄付 >%s',
  '\\nI will also cover the transaction fee\\n' => '取引手数料も私が負担します',
  '\\nSo your whole donation reaches its purpose. The exact fee depends on the payment method and is shown at the checkout.\\n' => 'したがって、あなたの寄付金はすべてその目的を達成できます。正確な料金は支払い方法によって異なり、チェックアウト時に表示されます。',
  '\\nTransaction fee (covered by you)\\n' => '取引手数料 (お客様負担)',
  '\\nAny trouble? Write to us on WhatsApp:\\n' => '何か問題はありますか? WhatsApp でご連絡ください:',
  '\\nNo badge\\n' => 'バッジがありません',
  '\\nBest value\\n' => '最良の価値',
  '\\nMost popular\', \'en\']]' => '最も人気のある\'、\'en\']]',
  '\\nFamily pack\\n' => 'ファミリー パック',
  '\\nHello{ad}, your donation of{tutar}is registered. IBAN:{iban}Reference:{aciklama}Upload your receipt:{link}\\n' => 'こんにちは{ad}さん。{tutar}の寄付が登録されました。 IBAN:{iban}参照:{aciklama}領収書のアップロード:{link}',
  '\\nHello{ad}🌱\\n\\nYour donation of *{tutar}* is registered (No:{siparis}).\\n\\nBank transfer details:\\nRecipient:{alici}\\nIBAN:{iban}\\nReference: *{aciklama}*\\n\\nAfter the transfer you can upload your receipt here:\\n{link}\\n\\nThank you,\\n{site}\\n' => 'こんにちは{ad}🌱' . chr(10) . '' . chr(10) . 'あなたの *{tutar}* の寄付が登録されました (いいえ:{siparis})。' . chr(10) . '' . chr(10) . '銀行振込の詳細:' . chr(10) . '受取人:{alici}' . chr(10) . 'IBAN:{iban}' . chr(10) . '参照: *{aciklama}*' . chr(10) . '' . chr(10) . '送金後、ここに領収書をアップロードできます:' . chr(10) . '{link}' . chr(10) . '' . chr(10) . 'ありがとうございます。' . chr(10) . '{site}',
  '\\nPending transfer notification sent:%s.\\n' => '送信された保留中の転送通知:%s。',
  '\\nWooCommerce checks\\n' => 'WooCommerce チェック',
  'This check could not run: %s' => 'このチェックは実行できませんでした:%s',
  '\\nVersion%1$sis active. Flux Donate was checked up to%2$s; it uses only stable public WooCommerce functions, but test a donation after big WooCommerce updates.\\n' => 'バージョン%1$sはアクティブです。 Flux Donate は%2$sまでチェックされました。安定した公開 WooCommerce 機能のみを使用しますが、WooCommerce の大幅な更新後に寄付をテストします。',
  '\\nActive, version%s. Donations are paid through the WooCommerce cart and checkout.\\n' => 'アクティブ、バージョン%s。寄付は、WooCommerce カートとチェックアウトを通じて支払われます。',
  '\\nOne-time card payments are taken by%s; iyzico is not shown at the checkout.\\n' => '1 回限りのカード支払いは%sによって行われます。 iyzico はチェックアウト時に表示されません。',
  '\\nOne-time card payments are taken by the official iyzico WooCommerce plugin.\\n' => '1 回限りのカード支払いは、公式 iyzico WooCommerce プラグインによって行われます。',
  '\\nCard payments use our own card fields on the checkout (iyzico 3D Secure, installments, saved cards).\\n' => 'カード支払いでは、チェックアウト時に独自のカード フィールドを使用します (iyzico 3D セキュア、分割払い、保存されたカード)。',
  '\\nOne-time card payments are taken by Flux Donate iyzico (the official iyzico plugin is not enabled).\\n' => '1 回限りのカード支払いは Flux Donate iyzico によって行われます (公式 iyzico プラグインは有効になっていません)。',
  '\\nCard payments are taken by:%s.\\n' => 'カード支払いは%sによって行われます。',
  '\\nNo card method is enabled; donations can only be paid by bank transfer.\\n' => '有効なカード メソッドはありません。寄付は銀行振込でのみお支払いいただけます。',
  '\\nCard payments (WooCommerce)\\n' => 'カード支払い (WooCommerce)',
  '\\nMonthly donations\\n' => '毎月の寄付',
  '\\nFlux Donate iyzico stores the card at the first payment; a renewal order is opened and charged every month.\\n' => 'Flux Donate iyzico は最初の支払い時にカードを保管します。更新注文がオープンされ、毎月請求されます。',
  '\\nMonthly donations are off: enable "Card (iyzico) - Flux Donate" in WooCommerce › Settings › Payments and enter iyzico keys.\\n' => '毎月の寄付はオフです: WooCommerce › 設定 › 支払いで「カード (iyzico) - Flux Donate」を有効にし、iyzico キーを入力します。',
  '\\nBank transfer (donations)\\n' => '銀行振込(寄付)',
  '\\nNo IBAN entered.\\n' => 'IBAN が入力されていません。',
  '\\nThe payment method is disabled.\\n' => 'お支払い方法が無効になっています。',
  '\\nBank transfer settings\\n' => '銀行振込設定',
  '\\nTwo bank transfer methods\\n' => '2 つの銀行振込方法',
  '\\nWooCommerce\\\'s own "Direct bank transfer" is enabled next to the donation bank transfer. Donors see two similar choices and the receipt upload works only with the donation one; disable "Direct bank transfer".\\n' => 'WooCommerce\\ 独自の「直接銀行振込」は寄付銀行振込の隣で有効になります。寄付者には同様の 2 つの選択肢が表示され、領収書のアップロードは寄付の場合にのみ機能します。 「直接銀行振込」を無効にします。',
  '\\nThe shop currency is%1$s; these types use another currency and are charged in%1$sat the same number:%2$s\\n' => 'ショップ通貨は%1$sです。これらのタイプは別の通貨を使用し、同じ番号%1$sで請求されます:%2$s',
  '\\nWooCommerce settings\\n' => 'WooCommerce 設定',
  '\\nDonation types and the shop use%s.\\n' => '寄付の種類とショップでは%sを使用します。',
  '\\nDonation products\\n' => '寄付商品',
  '\\nThese types get their hidden WooCommerce product the first time they are donated to or saved:%s\\n' => 'これらのタイプは、初めて寄付または保存されたときに非表示の WooCommerce 製品を取得します:%s',
  '\\n%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.\\n' => '%dアクティブ タイプには、非表示の WooCommerce 製品があります。%dアクティブ タイプには、非表示の WooCommerce 製品があります。',
  '\\nNo page with the donation options block is selected.\\n' => '寄付オプション ブロックのあるページが選択されていません。',
  '\\nOther payment plugins\\n' => 'その他の支払いプラグイン',
  '\\nCheck these on the donation checkout:%s. Details: Donations › Settings › WooCommerce › Payment methods.\\n' => '寄付チェックアウトでこれらをチェックしてください:%s。詳細: 寄付 › 設定 › WooCommerce › 支払い方法。',
  'Payment methods' => '支払い方法',
  '\\nEnabled and shown on the donation checkout:%s.\\n' => '有効化され、寄付チェックアウトに表示されます:%s。',
  '\\nCertificates after payment\\n' => '支払い後の証明書',
  '\\nFlux Certificates makes the certificates of paid donation lines.\\n' => 'Flux Certificates は、有償寄付ラインの証明書を作成します。',
  '\\nFlux Certificates has no active template.\\n' => 'Flux 証明書にはアクティブなテンプレートがありません。',
  '\\nProduct XML\\n' => 'プロダクト XML',
  '\\n%1$slists%2$ddonation packages (Google Merchant format, e.g. for iyzico).\\n' => '%1$sには%2$d寄付パッケージのリストが表示されます (Google Merchant 形式、iyzico など)。',
  '\\nPayment forms on the checkout\\n' => 'チェックアウト時の支払いフォーム',
  '\\nDonation forms send their choice to the WooCommerce cart; "Payment completed" automations run when the order is paid.\\n' => '寄付フォームは選択内容を WooCommerce カートに送信します。注文の支払いが完了すると、「支払い完了」の自動化が実行されます。',
  '\\nFlux Forms%sis active. Forms are paid on the checkout, but their "Payment completed" automations need Flux Forms 2.1.0 or later.\\n' => 'Flux フォーム%sがアクティブです。フォームの支払いはチェックアウト時に行われますが、「支払い完了」の自動化には Flux Forms 2.1.0 以降が必要です。',
  'Plugins' => 'プラグイン',
  '\\nDonation e-mails\\n' => '寄付メール',
  '\\nSent by Flux Mail; the templates (group "Flux Donate") can be edited there. WooCommerce order e-mails stay in WooCommerce › Settings › Emails.\\n' => 'Flux メールで送信。テンプレート (グループ「Flux Donate」) はそこで編集できます。 WooCommerce の注文メールは、WooCommerce › 設定 › 電子メールに残ります。',
  '\\nE-mail templates\\n' => '電子メール テンプレート',
  '\\nFlux Mail is not active: the donation e-mails are sent as plain text with their default wording.\\n' => 'Flux Mail はアクティブではありません。寄付電子メールは、デフォルトの文言を含むプレーン テキストとして送信されます。',
  '\\nBank transfer (donation)\\n' => '銀行振込(寄付)',
  '\\nThe donor transfers the money with an order-specific reference and uploads the receipt on the site. The certificate is issued when you confirm the payment.\\n' => '寄付者は注文固有の参照を使用して送金し、サイトに領収書をアップロードします。支払いを確認すると証明書が発行されます。',
  'Enabled' => '有効',
  '\\nTake donations by bank transfer\\n' => '銀行振込で寄付を受け付けます',
  'Empty = "Bank transfer" in the site language.' => '空 = サイト言語では「銀行振込」。',
  'Text on the checkout page' => 'チェックアウトページのテキスト',
  'Empty = the default text in the site language.' => '空 = サイト言語のデフォルトのテキスト。',
  'Recipient (account holder)' => '受取人(口座名義人)',
  '\\nEmpty = the holder of the bank account below or, without an IBAN here, of WooCommerce\\\'s "Direct bank transfer" account (else the theme settings).\\n' => '空 = 以下の銀行口座の所有者、またはここで IBAN を持たない WooCommerce の「直接銀行振込」口座の所有者 (それ以外の場合はテーマ設定)。',
  '\\nThe account shown everywhere (donation page, checkout, call center). Empty = the first account of WooCommerce\\\'s "Direct bank transfer", else the theme settings; recipient and bank then come from that account too.\\n' => 'アカウントはあらゆる場所 (寄付ページ、チェックアウト、コールセンター) に表示されます。空 = WooCommerce の「直接銀行振込」の最初のアカウント、それ以外の場合はテーマ設定。受信者と銀行もその口座から取得されます。',
  'Bank (optional)' => '銀行 (オプション)',
  '\\nWhat the donor writes in the transfer description. Placeholders:{tur}(sapling donation / donation),{kod}(prefix + order no),{siparis},{ad}. Empty:{tur}{kod}{ad}\\n' => '寄付者が譲渡説明に記入する内容。プレースホルダー:{tur}(苗木寄付 / 寄付)、{kod}(プレフィックス + 注文番号)、{siparis}、{ad}。空:{tur}{kod}{ad}',
  'Code prefix' => 'コードプレフィックス',
  '\\nBank transfer pre-registration: waiting for the payment.\\n' => '銀行振込事前登録: 支払いを待っています。',
  '\\nCard (iyzico) - Flux Donate\\n' => 'カード (iyzico) - Flux Donate',
  '\\nCard payments on iyzico\'s secure page. Required for monthly donations (the card is stored by iyzico and charged each month); also used for one-time donations when the official iyzico plugin is not active.\\n' => 'iyzico の安全なページでのカード支払い。毎月の寄付に必要です (カードは iyzico によって保管され、毎月請求されます)。公式 iyzico プラグインがアクティブでない場合の 1 回限りの寄付にも使用されます。',
  'Enable' => '有効にする',
  '\\nCard payments through Flux Donate (iyzico)\\n' => 'Flux Donate (iyzico) によるカード支払い',
  '\\nCredit / debit card (iyzico)\\n' => 'クレジット/デビット カード (iyzico)',
  'Description' => '説明',
  'API keys' => 'APIキー',
  '\\nYou will pay on iyzico\'s secure page. For monthly donations your card is stored by iyzico and charged once a month; you can cancel at any time.\\n' => '支払いは iyzico の安全なページで行われます。毎月の寄付の場合、カードは iyzico によって保管され、月に 1 回請求されます。いつでもキャンセルできます。',
  '\\nDonation options\\n' => '寄付オプション',
  '\\nSapling packages, causes and free-amount donations; added to the cart and paid with WooCommerce.\\n' => '苗木パッケージ、寄付金、および無償寄付金。カートに追加され、WooCommerce で支払いました。',
  '\\nTab shown first\\n' => 'タブが最初に表示されます',
  '\\nThe first one\\n' => '最初のもの',
  '\\nNone chosen = the types marked "Show in the Donation options block".\\n' => '何も選択されていない = 「寄付オプション ブロックに表示」とマークされたタイプ。',
  '\\nPrices and options: Donations › Donation types. Certificates and cart: Donations › Settings › WooCommerce.\\n' => '価格とオプション: 寄付 › 寄付の種類。証明書とカート: 寄付 › 設定 › WooCommerce。',
  '[[\'Could not copy, please select it by hand.\\n' => 'コピーできませんでした。手動で選択してください。',
  'Uploading…' => 'アップロード中...',
  '\\nWe have your receipt. Thank you! We will let you know once the payment is confirmed.\\n' => '領収書を受け取りました。ありがとう!支払いが確認され次第、お知らせいたします。',
  'The file is too large.' => 'ファイルが大きすぎます。',
  'Something went wrong. Please try again.' => '何か問題が発生しました。もう一度試してください。',
  'Add another receipt' => '別の領収書を追加する',
  '\\nReceipt under review\\n' => '領収書は審査中です',
  '\\nPlease write a WhatsApp number or an e-mail address (at least one).\\n' => 'WhatsApp 番号または電子メール アドレス (少なくとも 1 つ) を入力してください。',
  '\\nPlease enter a valid e-mail address.\\n' => '有効な電子メール アドレスを入力してください。',
  '\\nPlease enter a valid phone number.\\n' => '有効な電話番号を入力してください。',
  '\\nPlease write at most one name per share.\\n' => '1 つの共有につき最大 1 つの名前を入力してください。',
  '\\n/ month\\n' => '/月',
  '\\n(up to%s)\\n' => '(%sまで)',
  '[[\'%sSapling\', \'en\']]' . chr(0) . '[[\'%sSaplings\', \'en\']]' => '%s苗木',
  '\\nWho is this donation for?\\n' => 'この寄付は誰のためのものですか?',
  '\\nFor myself\\n' => '自分用',
  '\\nOn behalf of someone else\\n' => '他の人の代理として',
  '\\nTheir name\\n' => '彼らの名前',
  '\\ne.g. Ayşe Yılmaz or the Yılmaz family\\n' => 'e.g.アイシェ・ユルマズまたはユルマズ家',
  '\\nOptional. If you leave it empty, the name from the checkout is used.\\n' => 'オプション。空のままにすると、チェックアウトの名前が使用されます。',
  '\\nWritten on the certificate and the donation record.\\n' => '証明書と寄付記録に記載されます。',
  '\\nWritten on the donation record.\\n' => '寄付記録に記載されています。',
  '\\nWhere should the certificate go?\\n' => '証明書はどこに行けばよいですか?',
  '\\nEmpty fields use the phone and e-mail of your account or the checkout.\\n' => '空のフィールドでは、アカウントまたはチェックアウトの電話と電子メールが使用されます。',
  '\\nTheir phone and e-mail. Empty fields use yours.\', \'en\']]' => '電話と電子メール。空のフィールドにはあなたのフィールドを使用してください。',
  '\\nSend me a copy too\\n' => '私にもコピーを送ってください',
  '\\nOnline certificate\\n' => 'オンライン証明書',
  '\\nSent by WhatsApp and e-mail once the payment is confirmed, ready to download.\\n' => '支払いが確認されたら、WhatsApp と電子メールで送信され、ダウンロードの準備が整います。',
  '\\nOnline + printed certificate\\n' => 'オンライン + 印刷された証明書',
  '\\nA printed certificate is also posted to your address.\\n' => '印刷された証明書もあなたの住所に郵送されます。',
  'Free' => '無料',
  'Coming soon' => '近日公開予定',
  '\\nPostal address for the printed certificate\\n' => '印刷された証明書の住所',
  '\\nName, full address, district / city, phone\', \'en\']]' => '名前、完全な住所、地区/都市、電話番号',
  '\\nBy card, stop any time.\\n' => 'カードでいつでも停止できます。',
  '\\nYour donation was added to the cart.\\n' => 'あなたの寄付がカートに追加されました。',
  '\\nGo to cart\\n' => 'カートに移動',
  '\\nYour donation\\n' => 'あなたの寄付',
  'Continue' => '続ける',
  'Add to cart' => 'カートに追加',
  '\\nfrom%s\\n' => '%sから ',
  '\\nPayments are taken securely by iyzico.\\n' => '支払いは iyzico によって安全に行われます。',
  '\\nPay safely by card or bank transfer.\\n' => 'カードまたは銀行振込で安全にお支払いください。',
  '\\nYour card details are never stored on our site.\\n' => 'あなたのカードの詳細が当社のサイトに保存されることはありません。',
  '\\nHow many saplings would you like to donate?\\n' => '何本の苗木を寄付したいですか?',
  '\\nAnother amount\\n' => '別の金額',
  'Fewer' => '少ない',
  'Number of saplings' => '苗木の数',
  'More' => 'もっと見る',
  'Donation amount' => '寄付金額',
  '\\nOr write another amount\\n' => 'または別の金額を記入してください',
  '\\nAt least%s\\n' => '少なくとも%s',
  '\\nOn whose behalf?\\n' => '誰に代わって?',
  '\\nGiven in your name, as you write it at the checkout.\\n' => 'チェックアウト時に記入するあなたの名前が与えられます。',
  '\\nShares without a name are given in the name from the checkout. With a phone number we can also send that person the news on WhatsApp.\\n' => '名前のない共有には、チェックアウト時の名前が付けられます。電話番号を使用すると、WhatsApp でその人にニュースを送信することもできます。',
  '\\nShares without a name are given in the name from the checkout.\\n' => '名前のない共有には、チェックアウト時の名前が付けられます。',
  '\\nRead the proxy (vekâlet) text (version%s)\\n' => 'プロキシ (vekâlet) テキストを読み取ります (バージョン%s)',
  '\\nI give my proxy (vekâlet) for the sacrifice according to this text.\\n' => 'このテキストに従って、私は犠牲の代理人 (vekâlet) を捧げます。',
  '\\nShare%s\\n' => '%sを共有',
  '\\nApply to all\\n' => 'すべてに適用',
  '\\ne.g. Ali Yılmaz\\n' => 'e.g.アリ・ユルマズ',
  'Phone (optional)' => '電話(オプション)',
  '\\nNo receipt is expected for this donation.\\n' => 'この寄付には領収書は必要ありません。',
  '\\nAt most 5 receipts can be uploaded for a donation.\\n' => '寄付のためにアップロードできる領収書は最大 5 枚です。',
  'The file could not be uploaded. Please try again.' => 'ファイルをアップロードできませんでした。もう一度試してください。',
  'The file can be at most %s MB.' => 'ファイルは最大%sMB まで可能です。',
  'Only PDF, JPG, PNG, WEBP or HEIC files can be uploaded.' => 'PDF、JPG、PNG、WEBP、または HEIC ファイルのみをアップロードできます。',
  'The file could not be saved.' => 'ファイルを保存できませんでした。',
  '\\nThe donor uploaded a receipt:%1$s(%2$s). Check the payment and confirm it.\\n' => '寄付者が領収書をアップロードしました:%1$s(%2$s)。支払いを確認して確定します。',
  'WhatsApp' => 'ワッツアップ',
  '\\nthe site\\n' => 'サイト',
  '[[\'Warning: this receipt was uploaded before (%1$dtime, via%2$s). Check it before confirming the payment.\', \'en\']]' . chr(0) . '[[\'Warning: this receipt was uploaded before (%1$dtimes, via%2$s). Check it before confirming the payment.\', \'en\']]' => '警告: この領収書は以前 (%1$d回、%2$s経由) にアップロードされました。支払いを確認する前に必ずご確認ください。',
  '\\nEarlier donation: #%d.\\n' => '以前の寄付: #%d。',
  'We have your receipt. We will let you know once the payment is confirmed.' => '領収書はございます。ご入金が確認できましたらお知らせいたします。',
  'Choose a receipt or drop it here' => '領収書を選択するか、ここにドロップしてください',
  'PDF, JPG or PNG · up to %s MB' => 'PDF、JPG、または PNG · 最大%sMB',
  'Send receipt' => '領収書の送信',
  'Please choose a file.' => 'ファイルを選択してください。',
  'We have your receipt. Thank you!' => '領収書はございます。ありがとう!',
  '\\nWooCommerce checkout\\n' => 'WooCommerce チェックアウト',
  '\\nYou will choose how to pay (card or bank transfer) on the next page.\\n' => '次のページで支払い方法 (カードまたは銀行振込) を選択します。',
  '\\nMonthly donations are paid by card; the card is stored by iyzico and charged once a month.\\n' => '毎月の寄付はカードで支払われます。カードは iyzico によって保管され、月に 1 回請求されます。',
  '\\nThis form is not linked to a donation type. Please contact the site administrator.\\n' => 'このフォームは寄付の種類にリンクされていません。サイト管理者に連絡してください。',
  '\\nThe donation type of this form was not found.\\n' => 'このフォームの寄付タイプが見つかりませんでした。',
  '\\nThe amount could not be calculated. Please review your choices and try again.\\n' => '金額を計算できませんでした。選択内容を確認して、再試行してください。',
  'Pending donations' => '保留中の寄付',
  '\\nYou have no pending donations.\\n' => '保留中の寄付はありません。',
  '\\nDonations made by bank transfer appear here until the payment is confirmed.\\n' => '銀行振込による寄付は、支払いが確認されるまでここに表示されます。',
  'Donate' => '寄付する',
  '\\nYour bank transfer donations. If you have made the payment, upload your receipt; your certificate is sent once it is confirmed.\\n' => '銀行振込による寄付。支払いを完了した場合は、領収書をアップロードしてください。証明書が確認されると送信されます。',
  '\\nDonation #%s\\n' => '寄付 #%s',
  'Awaiting payment' => '支払い待ち',
  '[[\'%sdonation is awaiting payment\', \'en\']]' . chr(0) . '[[\'%sdonations are awaiting payment\', \'en\']]' => '%sの寄付は支払いを待っています',
  '\\nIf you have made the transfer, upload your receipt.\\n' => '送金を行った場合は、領収書をアップロードしてください。',
  '\\nPlease write your e-mail or phone number (at least one).\\n' => '電子メール アドレスまたは電話番号 (少なくとも 1 つ) を入力してください。',
  'Donation summary' => '寄付概要',
  '\\nWrite at least one. We send your receipt and certificate there.\\n' => '少なくとも 1 つ書き込んでください。領収書と証明書をそこにお送りします。',
  '\\nContinue to payment\\n' => '支払いを続行',
  '\\nI have read and accept the%1$sprivacy policy%2$sand the%3$sdonation agreement%4$s.\\n' => '%1$sプライバシー ポリシー%2$sおよび%3$s寄付契約%4$sを読み、同意します。',
  '\\nMake payment\\n' => '支払いを行う',
  '\\nPlease read and accept the terms to continue.\\n' => '続行するには、規約を読んで同意してください。',
  '\\nDonation terms\\n' => '寄付条件',
  '\\nPrivacy policy\\n' => 'プライバシー ポリシー',
  '\\nThese terms apply to donations made on this site to%s.\\n' => 'これらの規約は、このサイトで%sに行われた寄付に適用されます。',
  '\\nA donation is a gift without anything in return. It is used for the purpose chosen on the donation form (for example sapling planting). When a purpose is fully funded, the association may use the donation for a similar purpose.\\n' => '寄付は何も見返りのない贈り物です。寄付フォームに記載された目的(苗木の植樹など)に使用させていただきます。目的の資金が全額満たされた場合、協会はその寄付を同様の目的に使用することができます。',
  '\\nCard payments are processed by the licensed payment institution iyzico with 3D Secure. Card details are not stored on this site. For bank transfers, the donation is confirmed when the money reaches the association account.\\n' => 'カード支払いは、3D セキュアを使用して認可された支払い機関 iyzico によって処理されます。カードの詳細はこのサイトには保存されません。銀行振込の場合、寄付金が協会の口座に到着した時点で寄付が確認されます。',
  '\\nA monthly donation is charged to the same card every month until you cancel it. You can cancel it at any time from your account page or by writing to us.\\n' => '毎月の寄付は、キャンセルするまで毎月同じカードに請求されます。アカウント ページから、または当社に書面で連絡することで、いつでもキャンセルできます。',
  '\\nThe online certificate is sent to the e-mail address or phone number you give after the payment is confirmed. Please check the names you write on the certificate.\\n' => 'オンライン証明書は、支払いが確認された後、指定した電子メール アドレスまたは電話番号に送信されます。証明書に記入した名前を確認してください。',
  '\\nCancellation and refunds\\n' => 'キャンセルと返金',
  '\\nIf a donation was made by mistake (wrong amount or a double payment), write to us within 14 days and it is refunded to the same card or account.\\n' => '寄付が誤って行われた場合(金額の間違いまたは二重支払い)、14 日以内に私たちに書面でご連絡いただければ、同じカードまたは口座に返金されます。',
  'Personal data' => '個人データ',
  '\\nYour name and contact details are used to record the donation, send the receipt and certificate, and contact you about your donation. See the privacy policy for details.\\n' => 'あなたの名前と連絡先の詳細は、寄付の記録、領収書と証明書の送付、寄付に関する連絡に使用されます。詳細については、プライバシー ポリシーを参照してください。',
  '\\nFor any question about your donation, write to us on WhatsApp:%s\\n' => '寄付に関するご質問は、WhatsApp:%sまでお問い合わせください ',
  '\\nFor any question about your donation, write to us through the contact page.\\n' => '寄付に関するご質問は、お問い合わせページからご連絡ください。',
  '\\n%sprocesses your personal data under the Turkish Personal Data Protection Law (KVKK).\\n' => '%sは、トルコ個人データ保護法 (KVKK) に基づいてお客様の個人データを処理します。',
  '\\nWhat we collect\\n' => '収集するもの',
  '\\nName, e-mail address, phone number and the details of your donation. Card details are entered on the payment institution and are not stored by us.\\n' => '名前、電子メール アドレス、電話番号、および寄付の詳細。カードの詳細は支払い機関に入力され、当社では保管されません。',
  'Why' => 'なぜ',
  '\\nTo record donations, send receipts and certificates, meet legal obligations and answer your questions.\\n' => '寄付を記録し、領収書と証明書を送信し、法的義務を果たし、質問に答えます。',
  '\\nYour rights\\n' => 'あなたの権利',
  '\\nYou can ask what data we hold about you, have it corrected or deleted, by writing to us.\\n' => '弊社があなたに関してどのようなデータを保持しているのか、修正または削除を依頼するには、書面で問い合わせることができます。',
  '\\nBlock checkout\\n' => 'チェックアウトをブロック',
  '\\nNo address\\n' => 'アドレスがありません',
  '\\nServer check\\n' => 'サーバーチェック',
  '\\nSaved cards\\n' => '保存されたカード',
  '\\nRefund from site\\n' => 'サイトからの返金',
  'Monthly' => '毎月',
  '\\nShown on a checkout page built with the Checkout block. The classic checkout ([woocommerce_checkout]) shows every method.\\n' => 'チェックアウト ブロックで構築されたチェックアウト ページに表示されます。従来のチェックアウト ([woocommerce_checkout]) にはすべてのメソッドが表示されます。',
  '\\nPays an existing order from its payment link (call center, "pay again"), without a cart.\\n' => 'カートを使用せずに、支払いリンク (コールセンター、「再支払い」) から既存の注文を支払います。',
  '[["Works on our checkout that asks no address: Flux Donate fills the organisation\'s city and address in.\\n' => '住所を要求しないチェックアウトでは機能します: Flux Donate は組織の都市と住所を入力します。',
  '\\nThe payment is confirmed with the provider from the server before the order is marked paid.\\n' => '注文が支払い済みとしてマークされる前に、サーバーからプロバイダーに支払いが確認されます。',
  '\\nThe donor can pay in installments.\\n' => '寄付者は分割払いも可能です。',
  '\\nThe donor can save a card for the next donation.\\n' => '寄付者は次回の寄付のためにカードを保存できます。',
  '\\nThe Refund button on the order sends the refund to the provider.\\n' => '注文の [返金] ボタンをクリックすると、プロバイダに返金が送信されます。',
  '\\nMonthly donations charge a stored card every month. Only Flux Donate iyzico does this.\\n' => '毎月の寄付では、保存されているカードに毎月請求されます。これを行うのは Flux Donate iyzico だけです。',
  '\\nAdded by Flux Donate (the plugin has no block support).\\n' => 'Flux Donate によって追加されました (プラグインはブロックをサポートしていません)。',
  '\\nAdded by Flux Donate once the method is enabled.\\n' => 'メソッドが有効になると、Flux Donate によって追加されます。',
  '\\nTurn on "Show other payment plugins on the checkout block".\', \'en\']]' => '「チェックアウト ブロックに他の支払いプラグインを表示する」をオンにしてください。',
  '\\nThe plugin shows its own card fields only on the classic checkout. Use the classic checkout page or ask the provider for block support.\\n' => 'プラグインは、クラシック チェックアウトでのみ独自のカード フィールドを表示します。従来のチェックアウト ページを使用するか、プロバイダにブロック サポートを依頼してください。',
  '\\nMost plugins work; try a payment link once.\\n' => 'ほとんどのプラグインは動作します。支払いリンクを一度試してください。',
  '\\nDepends on the plugin; ask the provider.\\n' => 'プラグインによって異なります。プロバイダに問い合わせてください。',
  '\\nIf the provider offers it, on its payment page.\\n' => 'プロバイダーが提供する場合は、その支払いページで。',
  '\\nRefund in the provider\'s panel, then mark the order refunded.\\n' => 'プロバイダーのパネルで返金し、注文に返金済みのマークを付けます。',
  '[[\'Confirmed by hand after the receipt.\\n' => '受領後、手作業で確認されました。',
  '\\nnot shown on the block checkout page\\n' => 'ブロック チェックアウト ページには表示されません',
  'Yes' => 'はい',
  '\\nYes, by Flux Donate\\n' => 'はい、Flux Donate により',
  '\\nOn the provider\\\'s page\\n' => 'プロバイダのページ',
  'No' => 'いいえ',
  'Unknown' => '不明',
  '\\nEvery WooCommerce payment plugin (virtual POS) works on the donation checkout: install it, enter its settings in WooCommerce › Settings › Payments and enable it. This table shows what each one can do here.\\n' => 'すべての WooCommerce 支払いプラグイン (仮想 POS) は寄付チェックアウトで動作します。インストールし、WooCommerce › 設定 › 支払いに設定を入力して有効にします。この表は、ここで各ユーザーができることを示しています。',
  '\\nWooCommerce payments\\n' => 'WooCommerce での支払い',
  '\\nPayment logos on the site\\n' => 'サイト上の支払いロゴ',
  '\\nCheckout page:%s.\\n' => 'チェックアウト ページ:%s。',
  '\\nCheckout block\\n' => 'チェックアウトブロック',
  '\\nclassic\\n' => 'クラシック',
  'Method' => '方法',
  'On' => 'オン',
  'Off' => 'オフ',
  '\\nOnly one card method is shown to donors. Change it under Cart and checkout › Card payment method.\\n' => '寄付者に表示されるカード方法は 1 つだけです。 [カートとチェックアウト] › カード支払い方法で変更します。',
  '\\nHidden at checkout\\n' => 'チェックアウト時に非表示',
  'yes' => 'はい',
  '\\non the provider\'s page\\n' => 'プロバイダーのページ',
  'no' => 'いいえ',
  '\\nunknown, test it\\n' => '不明です、テストしてください',
  '\\nPoint at a mark for details.\\n' => '詳細については、マークをポイントしてください。',
  '[[\'Donation type not found.\\n' => '寄付の種類が見つかりません。',
  'Manual' => 'マニュアル',
  '\\nof%sgoal\\n' => '%sゴール',
  '\\nGoal progress\\n' => '目標の進捗状況',
  '\\nreached\\n' => '到達しました',
  '[[\'donor\', \'en\']]' . chr(0) . '[[\'donors\', \'en\']]' => '寄付者',
  '[[\'day left\', \'en\']]' . chr(0) . '[[\'days left\', \'en\']]' => '残り日数',
  '\\nEnter a name.\\n' => '名前を入力してください。',
  '\\nPartner not found.\\n' => 'パートナーが見つかりません。',
  '\\nEach tab must be a JSON object.\\n' => '各タブは JSON オブジェクトである必要があります。',
  '\\nA tab needs an "id".\\n' => 'タブには「ID」が必要です。',
  '[[\'Tab%1$s: "on" must be item or donation, not%2$s.\\n' => 'Tab%1$s: "on" は%2$sではなく、アイテムまたは寄付である必要があります。',
  '\\nTab%s: every field needs a "key".\\n' => 'タブ%s: すべてのフィールドには「キー」が必要です。',
  '\\nTab%1$s, field%2$s: unknown type%3$s.\', \'tr\']]' => 'タブ%1$s、フィールド%2$s: 不明なタイプ%3$s.',
  '\\nThe JSON could not be read:%s\\n' => 'JSON を読み取れませんでした:%s',
  '\\nTracked items\\n' => '追跡対象アイテム',
  'Record' => '記録',
  'Files' => 'ファイル',
  'Approved' => '承認済み',
  '\\nSent to partner\\n' => 'パートナーに送信されました',
  '\\nDelivered to owner\\n' => '所有者に届けられました',
  '\\nSend to a partner\\n' => 'パートナーに送信',
  '\\nTake back from the partner\\n' => 'パートナーから取り戻す',
  '\\nMark completed\\n' => '完了としてマークを付ける',
  '\\nYour gift on behalf of%1$sis completed. Thank you. Code:%2$s\\n' => '%1$sを代表するギフトが完了しました。ありがとう。コード:%2$s',
  'Menu name' => 'メニュー名',
  '\\nPage title\\n' => 'ページのタイトル',
  '\\nOne item\\n' => '1 つのアイテム',
  '\\nStatus: sent to partner\\n' => 'ステータス: パートナーに送信済み',
  '\\nStatus: completed\\n' => 'ステータス: 完了',
  '\\nButton: send to partner\\n' => 'ボタン: パートナーに送信',
  '\\nButton: take back\\n' => 'ボタン: 取り戻す',
  '\\nButton: mark completed\\n' => 'ボタン: 完了マークを付けます',
  '\\nWhatsApp text with the file (%1$sname,%2$scode)\\n' => 'WhatsApp テキストとファイル (%1$s名、%2$sコード)',
  'Recorded' => '録音済み',
  '\\nFile added\\n' => 'ファイルが追加されました',
  '\\nFile removed\\n' => 'ファイルが削除されました',
  '\\nFile sent to owner\\n' => 'ファイルは所有者に送信されました',
  '\\nDetails changed\\n' => '詳細が変更されました',
  'Imported' => '輸入品',
  '\\nChoose:%s.\\n' => '選択:%s。',
  '\\nnot waiting\\n' => '待っていません',
  '\\napprove it first\\n' => 'まず承認してください',
  '\\nalready completed or canceled\\n' => 'すでに完了またはキャンセルされました',
  '\\npayment not received\\n' => '支払いが受け取られていません',
  '\\nalready with this partner\\n' => 'すでにこのパートナーと付き合っています',
  '\\nnot with a partner, or already completed\\n' => 'パートナーと協力していないか、すでに完了しています',
  '\\nsend it to a partner first\\n' => 'まずパートナーに送信します',
  '\\nnot completed yet\\n' => 'まだ完了していません',
  '[[\'take it back from the partner first\\n' => '[[まずパートナーから取り戻してください',
  '\\ncannot be canceled\\n' => 'キャンセルできません',
  '\\nonly approved or canceled items\\n' => '\\承認またはキャンセルされたアイテムのみ',
  '\\nunknown step\\n' => '不明なステップ',
  '\\nFlux Chat is needed to send over WhatsApp.\\n' => 'WhatsApp 経由で送信するには、Flux Chat が必要です。',
  '\\nThere is no phone number for the owner.\\n' => '所有者の電話番号がありません。',
  '\\nThe file was not found.\\n' => 'ファイルが見つかりませんでした。',
  '\\nThere is no WhatsApp connection.\\n' => 'WhatsApp 接続がありません。',
  '[[\'The WhatsApp chat could not be opened.\\n' => 'WhatsApp チャットを開けませんでした。',
  '\\nPlease sign in.\\n' => 'サインインしてください。',
  '\\nreceived%s\\n' => '%sを受信しました',
  '\\nRecurring donation started\\n' => '定期的な寄付が開始されました',
  '\\nSent to the donor when a monthly (card) donation is set up.\\n' => '毎月(カード)寄付が設定されると寄付者に送信されます。',
  '\\nDonor name\\n' => '寄付者の名前',
  '\\nInterval (monthly...)\\n' => '間隔 (毎月...)',
  '\\nDate of the next payment\\n' => '次回の支払い日',
  '\\nCancel link\\n' => 'リンクをキャンセル',
  '\\nmonthly\\n' => '毎月',
  '\\nYour recurring donation to{kurum}\\n' => '{kurum}への定期的な寄付 ',
  '\\nThank you,{ad}\\n' => 'ありがとう、{ad}',
  '\\nYour{aralik}donation of{tutar}is set up. The next payment will be taken on{sonraki}.\\n' => '{tutar}の{aralik}寄付が設定されました。次の支払いは{sonraki}に行われます。',
  '\\nYou can cancel your recurring donation at any time with the button below.\\n' => '下のボタンでいつでも定期的な寄付をキャンセルできます。',
  '\\nRecurring donation could not be charged\\n' => '定期的な寄付を請求できませんでした',
  '\\nSent to the donor when the card was declined on every attempt and the recurring donation is paused.\\n' => 'カードがすべての試行で拒否され、定期的な寄付が一時停止された場合に寄付者に送信されます。',
  '\\nNumber of attempts\\n' => '試行回数',
  '\\nWe could not take your donation to{kurum}\', \'en\']]' => 'あなたの寄付を{kurum}\', \'en\' に受け取ることができませんでした]]',
  '\\nYour recurring donation is paused\\n' => '定期的な寄付は一時停止されています',
  '\\nDear{ad},\\n' => '{ad}様',
  '\\nWe tried{deneme}times but could not charge your card for your{aralik}donation of{tutar}, so it is paused. If you would like to continue, please make a new donation on our website or contact us.\\n' => '{deneme}回試しましたが、{tutar}の{aralik}寄付をカードに請求できなかったため、一時停止されています。継続をご希望の場合は、当社の Web サイトで新たに寄付を行うか、当社までご連絡ください。',
  '\\nDonate again\\n' => 'もう一度寄付してください',
  '\\nBank transfer receipt uploaded\\n' => '銀行振込領収書がアップロードされました',
  '\\nSent to the donations manager when a donor uploads a transfer receipt (dekont).\\n' => '寄付者が振込受領書 (dekont) をアップロードすると、寄付マネージャーに送信されます。',
  '\\nOrder number\\n' => '注文番号',
  '\\nTransfer reference\\n' => '転送リファレンス',
  '\\nFile name\\n' => 'ファイル名',
  '\\nOrder link (admin)\\n' => '注文リンク (管理者)',
  '\\nReceipt uploaded: donation #{siparis}({ad})\\n' => '領収書のアップロード: 寄付 #{siparis}({ad})',
  '\\nA transfer receipt was uploaded\', \'en\']]' => '振込受領書がアップロードされました',
  '\\nAmount:{tutar}\\n' => '金額:{tutar}',
  '\\nReference:{aciklama}\\n' => '参照:{aciklama}',
  '\\nFile:{dosya}\\n' => 'ファイル:{dosya}',
  '\\nCheck the payment at the bank and press "Confirm payment" on the order; the certificate is then issued and sent automatically.\\n' => '銀行で支払いを確認し、注文の「支払いを確認する」を押してください。その後、証明書が発行され、自動的に送信されます。',
  '\\nOpen the order\\n' => '注文を開く',
  'Payment rejected' => '支払いが拒否されました',
  '\\nSent to the donor when a manager rejects a bank transfer, with the reason.\\n' => 'マネージャーが銀行振込を拒否した場合、その理由とともに寄付者に送信されます。',
  '\\nWe could not confirm your donation payment\\n' => '寄付金の支払いを確認できませんでした',
  '\\nWe could not confirm your payment\\n' => 'お支払いを確認できませんでした',
  '\\nHello{ad},\\n' => '{ad}さん、こんにちは。',
  '\\nWe could not confirm the payment of your{tutar}donation.\\n' => '{tutar}寄付金の支払いを確認できませんでした。',
  '\\nReason:{aciklama}\\n' => '理由:{aciklama}',
  '\\nIf you think this is a mistake, please reply to this e-mail. Thank you.\\n' => 'これが間違いだと思われる場合は、このメールにご返信ください。ありがとうございます。',
  '\\nSet the organisation name\\n' => '組織名を設定します',
  '\\nThe name shown on receipts and donor e-mails (max. 190 characters).\\n' => '領収書および寄付者の電子メールに表示される名前 (最大 190 文字)。',
  '\\nThe organisation name cannot be empty.\\n' => '組織名を空にすることはできません。',
  '\\nOrganisation name saved:%s\\n' => '保存された組織名:%s',
  '\\nSet the default currency\\n' => 'デフォルトの通貨を設定します',
  '\\nUsed for new donation types and manual entries.\\n' => '新しい寄付タイプと手動入力に使用されます。',
  '\\nUnsupported currency.\\n' => 'サポートされていない通貨です。',
  '\\nDefault currency:%s\\n' => 'デフォルトの通貨:%s',
  '\\nOpen a donation type\\n' => '寄付の種類を開く',
  '\\nSets a closed donation type that already has a price (or a free amount) to active. Value: the type slug.\\n' => 'すでに価格 (または無料金額) が設定されているクローズ済みの寄付タイプを有効に設定します。値: タイプ スラッグ。',
  '\\nThis type has no option with a price and no free amount; set a price first.\\n' => 'このタイプには、価格や無料金額のオプションはありません。最初に価格を設定してください。',
  '\\nDonation type opened:%s\\n' => 'オープンした寄付タイプ:%s',
  '\\nSet a donation type\'s unit price\\n' => '寄付タイプの単価を設定します',
  '\\nValue "slug=price", e.g. "fidan=150". Every active option gets price × its units (1 sapling 150, 5 saplings 750). Linked forms update automatically.\\n' => '値「slug=price」、例: 「フィダン=150」。すべてのアクティブなオプションは、価格×その単位を取得します (苗木 1 つで 150、苗木 5 つで 750)。リンクされたフォームは自動的に更新されます。',
  '\\nThe price must be greater than 0.\\n' => '価格は 0 より大きくなければなりません。',
  '\\nThis type has no active option; add one on the Donation types page.\\n' => 'このタイプにはアクティブなオプションがありません。寄付の種類ページに追加してください。',
  '\\nUnit price of%1$sset to%2$s%3$s.\\n' => '%1$sの単価が%2$s%3$sに設定されました。',
  '\\nLink a form to a donation type\\n' => 'フォームを寄付タイプにリンクする',
  '\\nValue "slug=form id", e.g. "fidan=3". Forms:%s\\n' => '値「slug=フォームID」、例: 「フィダン=3」。フォーム:%s',
  '\\nNo form with this id.\\n' => 'この ID のフォームはありません。',
  '\\nThe form is already linked.\\n' => 'フォームはすでにリンクされています。',
  '\\nThe form could not be linked.\\n' => 'フォームをリンクできませんでした。',
  '\\nForm "%1$s" linked to%2$s.\\n' => 'フォーム「%1$s」は%2$sにリンクされています。',
  '\\nUse the form "slug=value".\\n' => '「slug=value」という形式を使用してください。',
  '\\nNo donation type with this slug.\\n' => 'このナメクジには寄付タイプがありません。',
  '\\nTracked records\\n' => '追跡されたレコード',
  'This month' => '今月',
  'Last month' => '先月',
  'Last 30 days' => '過去 30 日間',
  'This year' => '今年は',
  'Last year' => '昨年',
  'Last 12 months' => '過去 12 か月',
  'All time' => 'ずっと',
  '\\nPartner group\\n' => 'パートナー グループ',
  '\\nRegion\\n' => '地域',
  'Day' => '日',
  'Month' => '月',
  'Year' => '年',
  '\\nOne-time / regular\\n' => '一回限り/定期',
  'Channel' => 'チャンネル',
  '[[\'Margin\\n' => 'マージン',
  'Average' => '平均',
  'Created' => '作成されました',
  '\\nThe report must be a JSON object.\\n' => 'レポートは JSON オブジェクトである必要があります。',
  '\\nThe report needs an "id" (letters, digits, dash).\\n' => 'レポートには「ID」(文字、数字、ダッシュ) が必要です。',
  '\\nUnknown "source":%s. Use donations or items.\\n' => '不明な「ソース」:%s。寄付またはアイテムを使用してください。',
  '\\nUnknown "group" value:%s\\n' => '不明な「グループ」値:%s',
  '\\nGroup by at most two dimensions.\\n' => '最大でも 2 つの次元でグループ化します。',
  '\\nUnknown "metrics" value:%s\\n' => '不明な「メトリクス」値:%s',
  '\\n"sort" must be one of the group or metrics values:%s\\n' => '「sort」はグループ値またはメトリック値のいずれかである必要があります:%s',
  '\\npiece\\n' => 'ピース',
  '\\npieces\\n' => '個',
  'share' => 'シェアする',
  '\\nshares\\n' => '共有',
  'person' => '人',
  '\\npeople\\n' => '人々',
  '\\nsapling\\n' => '苗木',
  '\\nsaplings\\n' => '苗木',
  '\\npackage\\n' => 'パッケージ',
  '\\npackages\\n' => 'パッケージ',
  '\\nIn the trash\\n' => 'ゴミ箱の中',
  'Daily' => '毎日',
  'Weekly' => '毎週',
  '\\nYearly\\n' => '毎年',
  '\\nTest provider\\n' => 'テストプロバイダ',
  'Each line shows something the site needs and whether it is in place. Fix the errors first; warnings are worth a look.' => '各行は、サイトに必要なものと、それが適切に配置されているかどうかを示します。まずエラーを修正してください。警告は一見の価値があります。',
  'OK' => 'OK',
  'Warning' => '警告',
  'Error' => 'エラー',
  'Info' => '情報',
  '%1$d OK · %2$d warnings · %3$d errors' => '%1$dOK ·%2$d警告 ·%3$dエラー',
  'Check again' => 'もう一度確認してください',
  'Show only these (click again to show all)' => 'これらのみを表示します (すべてを表示するにはもう一度クリックします)',
  'Checked: %s' => 'チェック済み:%s',
  'Source' => 'ソース',
  'Action' => 'アクション',
  'No checks are registered.' => '小切手は登録されていません。',
  'System check found %d problem(s) that can stop donations or automations.' => 'システム チェックで、寄付や自動化を停止する可能性がある%dの問題が見つかりました。',
  'Open system check' => 'オープンシステムチェック',
  'Hide until the next update' => '次の更新まで非表示にします',
  'System: %d error(s)' => 'システム:%dエラー',
  'Scheduled tasks (cron)' => 'スケジュールされたタスク (cron)',
  'Security' => 'セキュリティ',
  '\\n%1$s(%2$s)\\n' => '%1$s(%2$s)',
  '\\nLast test%1$s:%2$s\\n' => '最後のテスト%1$s:%2$s',
  'WP-Cron mode' => 'WP-Cronモード',
  '[[\'WP-Cron is turned off in wp-config.php (DISABLE_WP_CRON). That is fine only if a server cron job calls%severy 5–15 minutes; without it recurring charges, retries and other scheduled tasks never run.\\n' => 'WP-Cron は wp-config.php (DISABLE_WP_CRON) でオフになっています。これは、サーバー cron ジョブが 5 ~ 15 分ごとに%sを呼び出す場合にのみ問題ありません。これがないと、定期的な料金、再試行、その他のスケジュールされたタスクは実行されません。',
  '\\nScheduled tasks are running, so a server cron is in place.\\n' => 'スケジュールされたタスクが実行されているため、サーバー cron が配置されています。',
  '\\nScheduled tasks have not run recently: check the server cron job (Hostinger: hPanel › Advanced › Cron Jobs).\', \'en\']]' => 'スケジュールされたタスクは最近実行されていません: サーバーの cron ジョブを確認してください (Hostinger: hPanel › Advanced › Cron Jobs)。',
  '\\nWP-Cron runs when someone visits the site. On a quiet site tasks can run late; for reliable recurring charges add a server cron job that calls wp-cron.php every 15 minutes and set DISABLE_WP_CRON to true (see KURULUM.md).\\n' => '誰かがサイトにアクセスすると、WP-Cron が実行されます。静かなサイトではタスクの実行が遅くなる可能性があります。信頼性の高い定期的な料金を得るには、15 分ごとに wp-cron.php を呼び出すサーバー cron ジョブを追加し、DISABLE_WP_CRON を true に設定します (KURULUM.md を参照)。',
  '\\nALTERNATE_WP_CRON is on.\\n' => 'ALTERNATE_WP_CRON がオンになっています。',
  '\\nFlux Donate hourly task", \'en\']]' => 'Flux 時間単位のタスクを寄付',
  '\\nLast run:%s. Recurring iyzico charges are checked every hour.\\n' => '最終実行:%s。 iyzico の定期的な料金は 1 時間ごとにチェックされます。',
  '\\nNot run yet; the first run is scheduled for%s.\\n' => 'まだ実行されていません。最初の実行は%sにスケジュールされています。',
  '\\nLast run:%s, more than 2 hours ago.\\n' => '最終実行:%s、2 時間以上前。',
  '\\nIt has never run.\\n' => '一度も実行されていません。',
  '\\nWP-Cron is off, so a server cron job must call wp-cron.php. It seems to be missing or failing.\', \'en\']]' => 'WP-Cron がオフになっているため、サーバー cron ジョブは wp-cron.php を呼び出す必要があります。見つからないか、失敗しているようです。',
  '\\nWP-Cron only runs on visits and may be blocked by the host or a security plugin. Use "Test cron" or add a server cron job.\\n' => 'WP-Cron は訪問時にのみ実行され、ホストまたはセキュリティ プラグインによってブロックされる可能性があります。 「Test cron」を使用するか、サーバー cron ジョブを追加します。',
  '\\nNext scheduled:%s.\\n' => '次のスケジュール:%s。',
  '[[\'The task is not scheduled; it is added again on the next page load.\\n' => 'タスクはスケジュールされていません。次のページのロード時に再び追加されます。',
  '\\nTest cron\\n' => 'cron をテストします',
  '\\nOverdue scheduled tasks\\n' => '期限を過ぎたスケジュールされたタスク',
  '\\n%1$dtask is more than 15 minutes late:%2$s.%1$dtasks are more than 15 minutes late:%2$s.\\n' => '%1$dタスクは 15 分以上遅れています:%2$s。%1$dタスクが 15 分以上遅れています:%2$s。',
  '\\nA few late tasks right after a quiet period are normal; many mean cron is not running.\\n' => '静かな期間の直後にいくつかのタスクが遅れるのは正常なことです。多くの場合、cron が実行されていないことを意味します。',
  '\\nNo task is late.\\n' => '遅れているタスクはありません。',
  '\\nCron test\\n' => 'Cron テスト',
  '\\nNot tested. The test asks this server to call wp-cron.php once, as WordPress does after a visit.\\n' => 'テストされていません。テストでは、WordPress がアクセス後に行うのと同じように、このサーバーに wp-cron.php を 1 回呼び出すように要求します。',
  '\\nCard payment provider\\n' => 'カード決済プロバイダー',
  '\\nNo payment provider is available.\\n' => '利用可能な支払いプロバイダーがありません。',
  '\\nPayment settings\\n' => '支払い設定',
  '\\nCard payments are taken with%s.\\n' => 'カード支払いは%sで行われます。',
  '\\n%sis the active provider but its keys are missing, so donation forms show "Online payment is unavailable".\\n' => '%sはアクティブなプロバイダですが、そのキーが見つからないため、寄付フォームには「オンライン支払いは利用できません」と表示されます。',
  '\\nEnter keys\\n' => 'キーを入力してください',
  '\\nKeys are read from the iyzico Subscription plugin settings.\\n' => 'キーは iyzico サブスクリプション プラグイン設定から読み取られます。',
  '\\nKeys are entered in Donations › Payments › iyzico.\\n' => 'キーは、寄付 › 支払い › iyzico に入力されます。',
  '[[\'No iyzico API key and secret key found (neither in the iyzico WooCommerce plugin nor in Flux Donate).\\n' => 'iyzico API キーと秘密キーが見つかりません (iyzico WooCommerce プラグインにも Flux Donate にもありません)。',
  '\\nMode: sandbox (test). No real money is collected; switch to live keys before launch.\\n' => 'モード: サンドボックス (テスト)。実際のお金は集められません。起動前にライブキーに切り替えてください。',
  '\\nMode: live. Real payments are taken.\\n' => 'モード: ライブ。実際の支払いが行われます。',
  '\\nUse "Test connection" to check the keys with iyzico.\\n' => '「接続のテスト」を使用して、iyzico でキーを確認します。',
  '\\niyzico keys\\n' => 'iyzico キー',
  'Test connection' => 'テスト接続',
  '\\nPaste into iyzico panel › Merchant notifications URL (İşyeri Bildirimleri Url):%s. Subscription notification URLs are not needed.\\n' => 'iyzico パネルに貼り付けます › 販売者通知 URL (İşyeri Bildirimleri Url):%s。サブスクリプション通知 URL は必要ありません。',
  '\\nLast notification received:%s.\\n' => '最後に受信した通知:%s。',
  '\\nNo notification received in the last 30 days (normal until the address is saved in the iyzico panel and a payment is made).\\n' => '過去 30 日間に通知を受信していません (アドレスが iyzico パネルに保存され、支払いが行われるまでは通常の状態です)。',
  '\\nNotifications for WooCommerce orders are forwarded to the iyzico WooCommerce plugin.\\n' => 'WooCommerce 注文の通知は iyzico WooCommerce プラグインに転送されます。',
  '\\niyzico notification URL\\n' => 'iyzico 通知 URL',
  '\\nShow addresses\\n' => 'アドレスを表示',
  '\\nFailed recurring charges\\n' => '定期的な請求が失敗しました',
  '[[\'%drecurring donation stopped after its card was declined 3 times.\', \'en\']]' . chr(0) . '[[\'%drecurring donations stopped after their cards were declined 3 times.\', \'en\']]' => '%dの定期的な寄付は、カードが 3 回拒否された後停止されました。',
  '\\nStripe keys\\n' => 'ストライプ キー',
  '\\nThe Stripe publishable key and secret key are missing.\\n' => 'Stripe 公開可能キーと秘密キーがありません。',
  '\\nMode: live.\\n' => 'モード: ライブ。',
  '\\nMode: test (pk_test_). No real money is collected.\\n' => 'モード: テスト (pk_test_)。実際のお金は徴収されません。',
  '\\nWebhook signing secret is set.\\n' => 'Webhook 署名シークレットが設定されています。',
  '\\nWebhook signing secret is missing: refunds and renewals made in Stripe will not show up in Flux Donate.\\n' => 'Webhook 署名シークレットがありません: Stripe で行われた払い戻しと更新は Flux Donate に表示されません。',
  '\\nFlux Forms is not active. Donation forms and card payments need it.\\n' => 'Flux フォームはアクティブではありません。寄付フォームとカード支払いが必要です。',
  '\\nActive, version%s.\\n' => 'アクティブ、バージョン%s。',
  '\\nVersion%1$sis active; Flux Donate needs%2$sor later for payments and prices to work together.\\n' => 'バージョン%1$sはアクティブです。 Flux Donate で支払いと価格を連携するには%2$s以降が必要です。',
  '\\nActive, version%s. Certificates can be sent after donations.\\n' => 'アクティブ、バージョン%s。寄付後に証明書を送信できます。',
  '\\nVersion%1$sis active;%2$sor later is recommended.\\n' => 'バージョン%1$sはアクティブです。%2$s以降を推奨します。',
  '\\nNot active. Donations are recorded, but no certificate is created or sent.\\n' => 'アクティブではありません。寄付は記録されますが、証明書の作成や送信は行われません。',
  '\\nWooCommerce is older than%s. Flux Donate 2.0 takes donations through WooCommerce; update it.\\n' => 'WooCommerce は%sよりも古いです。 Flux Donate 2.0 は WooCommerce を通じて寄付を受け付けています。更新してください。',
  '\\nWooCommerce is not active. Flux Donate 2.0 takes donations through the WooCommerce cart and checkout; until it is active, only the older Flux Forms payment layer works.\\n' => 'WooCommerce はアクティブではありません。 Flux Donate 2.0 は、WooCommerce カートとチェックアウトを通じて寄付を受け付けます。アクティブになるまでは、古い Flux Forms 支払いレイヤーのみが機能します。',
  '[[\'The old Flux WooCommerce Bağış plugin is still active. Flux Donate 2.0 replaces it: deactivate and delete it, otherwise orders get two certificates and two messages.\\n' => '古い Flux WooCommerce Bağış プラグインはまだアクティブです。 Flux Donate 2.0 がこれを置き換えます。無効化して削除します。そうでない場合、オーダーは 2 つの証明書と 2 つのメッセージを取得します。',
  '\\nWooCommerce is active.\\n' => 'WooCommerce はアクティブです。',
  '\\nThe iyzico WooCommerce plugin is active: it takes one-time card payments, and Flux Donate reads its iyzico keys for monthly donations.\\n' => 'iyzico WooCommerce プラグインはアクティブです。カード支払いは 1 回限りで、Flux Donate は毎月の寄付のために iyzico キーを読み取ります。',
  '\\nThe iyzico WooCommerce plugin is not active, but its saved keys are still used.\\n' => 'iyzico WooCommerce プラグインはアクティブではありませんが、保存されたキーは引き続き使用されます。',
  '\\nThe iyzico WooCommerce plugin is not active; Flux Donate uses its own iyzico keys.\\n' => 'iyzico WooCommerce プラグインはアクティブではありません。 Flux Donate は独自の iyzico キーを使用します。',
  '\\nThe iyzico Subscription plugin is active; it renews WooCommerce subscriptions only. Flux Donate recurring donations use their own hourly task.\', \'en\']]' => 'iyzico サブスクリプション プラグインはアクティブです。 WooCommerce サブスクリプションのみを更新します。 Flux Donate の定期的な寄付では、独自の時間ごとのタスクが使用されます。',
  '\\nWooCommerce and iyzico plugins\\n' => 'WooCommerce および iyzico プラグイン',
  '[[\'Open donation types\\n' => '寄付タイプを開く',
  '[[\'%ddonation type is open and priced.\', \'en\']]' . chr(0) . '[[\'%ddonation types are open and priced.\', \'en\']]' => '%d寄付タイプはオープンで価格も設定されています。',
  '\\nNo donation type is open with a price (or free amount), so forms cannot take donations.\\n' => '価格 (または無料金額) が公開されている寄付タイプがないため、フォームで寄付を受け付けることはできません。',
  '\\nForms of open donation types\\n' => 'オープンな寄付タイプのフォーム',
  '\\nNo (existing) form is linked to:%s. Visitors cannot give to these types online.\\n' => '(既存の) フォームが%sにリンクされていません。訪問者はこれらのタイプにオンラインで寄付することはできません。',
  '\\nEvery open donation type has a form.\\n' => 'すべてのオープンな寄付タイプにはフォームがあります。',
  '\\nDefault currency:%s.\\n' => 'デフォルトの通貨:%s。',
  '\\niyzico is not set up for this currency (Donations › Payments › iyzico › currencies).\\n' => 'iyzico はこの通貨に設定されていません (寄付 › 支払い › iyzico › 通貨)。',
  '\\nBank accounts (transfer)\\n' => '銀行口座 (振込)',
  '[[\'%dbank account is listed for bank transfer gifts.\', \'en\']]' . chr(0) . '[[\'%dbank accounts are listed for bank transfer gifts.\', \'en\']]' => '%d銀行口座は銀行振込ギフト用にリストされています。',
  '\\nNo bank account is listed. They come from the theme (filter flxb_bank_accounts) and are used when recording bank transfer gifts.\\n' => '銀行口座がリストされていません。これらはテーマ (フィルター flxb_bank_accounts) から取得され、銀行振込ギフトを記録するときに使用されます。',
  '\\nReceipts and e-mails show "%s".\', \'en\']]' => '領収書と電子メールには「%s」が表示されます。',
  '\\nNot set; receipts and e-mails use the site title "%s".\\n' => '設定されていません。領収書と電子メールでは、サイト タイトル「%s」が使用されます。',
  '[[\'E-mail sending\\n' => '電子メール送信',
  '\\nNot tested. Donor e-mails (recurring donation started, card declined) go out with wp_mail. The test sends one message to%s.\\n' => 'テストされていません。寄付者の電子メール (定期的な寄付が開始され、カードが拒否されました) は wp_mail で送信されます。テストは 1 つのメッセージを%sに送信します。',
  '\\nSend test e-mail\\n' => 'テスト電子メールを送信',
  'Permalinks' => 'パーマリンク',
  '\\nPlain permalinks are in use. Payment callbacks still work through ?rest_route=, but some hosts and security plugins block that; choose "Post name".\\n' => 'プレーンパーマリンクが使用されています。支払いコールバックは ?rest_route= を通じて引き続き機能しますが、一部のホストとセキュリティ プラグインはそれをブロックします。 「投稿名」を選択してください。',
  '\\nPretty permalinks are on; REST callbacks use /wp-json/.\\n' => 'きれいなパーマリンクがオンになっています。 REST コールバックは /wp-json/ を使用します。',
  '\\nThe site runs on HTTPS.\\n' => 'サイトは HTTPS で実行されます。',
  '\\nLocal test site without HTTPS. The live site must use HTTPS; payment providers refuse plain HTTP.\\n' => 'HTTPS を使用しないローカル テスト サイト。ライブ サイトでは HTTPS を使用する必要があります。支払いプロバイダはプレーン HTTP を拒否します。',
  '\\nThe site address is not HTTPS. Card payments and payment callbacks need HTTPS (Settings › General, and an SSL certificate from the host).\\n' => 'サイトのアドレスは HTTPS ではありません。カード支払いと支払いコールバックには HTTPS ([設定] › [一般]、およびホストからの SSL 証明書) が必要です。',
  'General settings' => '一般設定',
  '\\nWordPress security keys (salts)\\n' => 'WordPress セキュリティ キー (ソルト)',
  '\\nMissing or weak in wp-config.php:%s. Saved iyzico cards are encrypted with these keys; set unique values once (https://api.wordpress.org/secret-key/1.1/salt/) and do not change them afterwards, or saved cards stop working.\\n' => 'wp-config.php:%sが欠落しているか弱い。保存された iyzico カードはこれらのキーで暗号化されます。一意の値を一度設定 (https://api.wordpress.org/secret-key/1.1/salt/) し、その後は変更しないでください。変更しないと、保存されたカードが機能しなくなります。',
  '\\nSet in wp-config.php. Saved iyzico cards are encrypted with them: do not change them, or saved cards stop working.\\n' => 'wp-config.php で設定します。保存された iyzico カードは暗号化されます。変更しないでください。変更しないと、保存されたカードが機能しなくなります。',
  'Database tables' => 'データベーステーブル',
  '\\nUp to date (%s).\\n' => '最新の状態 (%s)。',
  '\\nTables are at version%1$s, expected%2$s. Deactivate and activate Flux Donate to update them.\\n' => 'テーブルのバージョンは%1$sですが、%2$sが必要です。 Flux Donate を非アクティブにしてからアクティブにして更新してください。',
  '\\nNo iyzico keys to test.\\n' => 'テストする iyzico キーがありません。',
  '\\nsandbox\\n' => 'サンドボックス',
  '\\nConnected; iyzico accepted the keys (%s).\\n' => '接続されました; iyzico はキー (%s) を受け入れました。',
  '\\niyzico refused the keys (%1$s):%2$s. Check that the keys belong to this environment.\\n' => 'iyzico はキー (%1$s) を拒否しました:%2$s。キーがこの環境に属していることを確認してください。',
  '\\nThis server could not reach its own wp-cron.php (%s). WP-Cron cannot start from visits; add a server cron job.\\n' => 'このサーバーは独自の wp-cron.php (%s) にアクセスできませんでした。 WP-Cron は訪問から開始できません。サーバー cron ジョブを追加します。',
  '\\nwp-cron.php answered; WP-Cron can start.\\n' => 'wp-cron.php が答えました。 WP-Cron を開始できます。',
  '\\nwp-cron.php answered with HTTP%d(blocked by the host or a security plugin?). Add a server cron job.\\n' => 'wp-cron.php は HTTP%dで応答しました (ホストまたはセキュリティ プラグインによってブロックされました?)。サーバー cron ジョブを追加します。',
  '\\n[%s] Test e-mail from Flux Donate\\n' => '[%s] Flux Donate からのテスト電子メール',
  '\\nThis is a test from Donations › Settings › System check. If you can read it, donor e-mails can be sent.\\n' => 'これは、「寄付」 > 「設定」 > 「システムチェック」からのテストです。読むことができれば、寄付者の電子メールを送信できます。',
  '\\nSent to%s. Check that it arrived (and not in spam).\\n' => '%sに送信されます。受信したことを確認してください (スパムではないこと)。',
  '\\nSending failed:%s. Set up SMTP (e.g. an SMTP plugin with your mail account).\\n' => '送信に失敗しました:%s。 SMTP をセットアップします (メール アカウントを使用した SMTP プラグインなど)。',
  'unknown error' => '不明なエラー',
  '[[\'Donations on WooCommerce: donation types and sapling packages sold as hidden products, cart and checkout (iyzico, bank transfer with receipt upload), monthly donations, online and printed certificates, donors, campaigns and a donation dashboard. Includes Flux WooCommerce Bağış.\', \'en\']]' => 'WooCommerce での寄付: 非表示の商品として販売される寄付タイプと苗木パッケージ、カートとチェックアウト (iyzico、領収書のアップロードによる銀行振込)、毎月の寄付、オンラインおよび印刷された証明書、寄付者、キャンペーン、寄付ダッシュボード。 Flux WooCommerce Bağış.\', \'en\']] が含まれます。',
  '\\n%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived\\n' . chr(0) . '\\n%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived\\n' => '%1$sの寄付 ·%2$sを受け取りました%1$sの寄付を受け取りました ·%2$sを受け取りました',
  '\\n%1$spaid gift ·%2$s%1$spaid gifts ·%2$s\\n' . chr(0) . '\\n%1$spaid gift ·%2$s%1$spaid gifts ·%2$s\\n' => '%1$s有料ギフト ·%2$s%1$s有料ギフト ·%2$s',
