  'iyzico panel addresses' => 'iyzico パネル アドレス',
  'In the iyzico merchant panel, open the notification settings, switch payment notifications on and paste this address. iyzico allows one address per merchant; Flux Donate passes WooCommerce notifications on to the iyzico WooCommerce plugin, so the same address serves both.' => 'iyzico 販売者パネルで、通知設定を開き、支払い通知をオンにして、このアドレスを貼り付けます。 iyzico では販売者ごとに 1 つのアドレスを許可します。 Flux Donate は WooCommerce 通知を iyzico WooCommerce プラグインに渡すため、同じアドレスが両方に配信されます。',
  'Merchant notifications URL (İşyeri Bildirimleri Url)' => '販売者通知 URL (İşyeri Bildirimleri URL)',
  'Subscription notification URLs (Başarılı / Başarısız Abonelik Bildirimleri Url): not needed, leave them off.' => '定期購入通知 URL (Başarılı / Başarısız Abonelik Bildirimleri Url): 必要ありません。オフのままにしてください。',
  'They belong to iyzico\'s own subscription product; Flux Donate renews recurring donations with the saved card and its own scheduled task.' => 'これらは iyzico 独自のサブスクリプション製品に属します。 Flux Donate は、保存されたカードと独自のスケジュールされたタスクを使用して定期的な寄付を更新します。',
  'Callback URL (sent automatically with every payment, nothing to paste):' => 'コールバック URL (支払いのたびに自動的に送信され、貼り付ける必要はありません):',
  'The iyzico WooCommerce plugin has a webhook key on this site: notifications that are not for Flux Donate are forwarded to it.' => 'iyzico WooCommerce プラグインには、このサイトに Webhook キーがあります。Flux Donate 以外の通知はそこに転送されます。',
  'The Stripe secret key is not configured.' => 'Stripe 秘密キーが構成されていません。',
