  'No payment provider is available on this site. Please contact the site administrator.' => 'このサイトでは利用できる支払いプロバイダーがありません。サイト管理者に連絡してください。',
  'Too many payment attempts. Please wait a few minutes and try again.' => '支払い試行が多すぎます。数分待ってから再試行してください。',
  'The payment provider is not configured on this site. Please contact the site administrator.' => 'このサイトでは支払いプロバイダーが設定されていません。サイト管理者に連絡してください。',
  'No payment amount detected. Please review your selected items and try again. If the problem persists, contact support.' => '支払い金額が検出されませんでした。選択した項目を確認して、もう一度お試しください。問題が解決しない場合は、サポートにお問い合わせください。',
  'Too many requests. Please wait a moment and try again.' => 'リクエストが多すぎます。しばらく待ってから再試行してください。',
  'Payment not found.' => '支払いが見つかりません。',
  'Payment Intent ID is missing' => 'Payment Intent ID がありません',
  'Your payment has not been confirmed yet. Please wait a moment and try again. If the problem persists, contact the site administrator.' => 'お支払いはまだ確認されていません。しばらく待ってから、もう一度試してください。問題が解決しない場合は、サイト管理者に問い合わせてください。',
  'Online payment is not available at the moment. Please try again later or contact us.' => 'オンライン支払いは現在ご利用いただけません。後でもう一度試すか、お問い合わせください。',
  'Test provider (development only)' => 'テスト プロバイダー (開発のみ)',
  'Test outcome' => 'テスト結果',
  'Approve every payment' => 'すべての支払いを承認します',
  'Decline every payment' => 'すべての支払いを拒否します',
  'No money is taken. Development only.' => 'お金は取られません。開発のみ。',
  'TEST MODE: no card is charged.' => 'テスト モード: カードはチャージされていません。',
  'Test provider: the payment was declined.' => 'テスト プロバイダ: 支払いが拒否されました。',
  'iyzico merchant panel › Settings › Merchant settings. Sandbox keys start with "sandbox-".' => 'iyzico 販売者パネル › 設定 › 販売者設定。サンドボックス キーは「sandbox-」で始まります。',
  'Sandbox (test) mode' => 'サンドボックス (テスト) モード',
  'Uses sandbox-api.iyzipay.com; no real money is taken. Turn off with live keys.' => 'sandbox-api.iyzipay.com を使用します。実際のお金は取られません。ライブキーを使用してオフにします。',
  'Payment page' => '支払いページ',
  'Popup window (recommended: the form stays open)' => 'ポップアップ ウィンドウ (推奨: フォームは開いたままになります)',
  'Same tab (redirect to iyzico and back)' => '同じタブ (iyzico にリダイレクトして戻ってくる)',
  'With "popup" the donor returns to the open form and the form is sent as usual. When the browser blocks the popup, the same tab is used.' => '「ポップアップ」を使用すると、寄付者は開いているフォームに戻り、フォームは通常どおり送信されます。ブラウザがポップアップをブロックすると、同じタブが使用されます。',
  'Other currencies' => '他の通貨',
  'TRY is always accepted. Add others your iyzico account accepts, comma separated (e.g. USD,EUR).' => '試行はいつでも受け付けられます。 iyzico アカウントが受け入れる他のユーザーをカンマ区切りで追加します (例: USD、EUR)。',
  'Recurring gift without a saved card' => 'カードが保存されていない定期的なギフト',
  'Keep the payment as a one-time donation' => '支払いは 1 回限りの寄付として保持します',
  'Cancel the payment (like the iyzico Subscription plugin)' => '支払いをキャンセルします (iyzico サブスクリプション プラグインなど)',
  'If iyzico does not return a stored card for the first payment of a recurring gift, it cannot be charged again.' => 'iyzico が定期ギフトの最初の支払いに対して保存されたカードを返さない場合、再度請求することはできません。',
  'Read from the iyzico WooCommerce plugin (WooCommerce › Settings › Payments › iyzico). Values here are used only when that plugin has no keys.' => 'iyzico WooCommerce プラグインから読み取ります (WooCommerce › 設定 › 支払い › iyzico)。ここの値は、プラグインにキーがない場合にのみ使用されます。',
  'Read from the iyzico WooCommerce Subscription plugin. Values here are used only when it has no keys.' => 'iyzico WooCommerce サブスクリプション プラグインから読み取ります。ここの値は、キーがない場合にのみ使用されます。',
  'You will enter your card on iyzico\'s secure payment page. It opens in a new window when you press Pay.' => 'iyzico の安全な支払いページにカードを入力します。 「支払う」を押すと、新しいウィンドウで開きます。',
  'You will enter your card on iyzico\'s secure payment page and then come back here.' => 'iyzico の安全な支払いページにカードを入力してから、ここに戻ってきます。',
  'For a recurring donation, keep "Save my card" ticked on the iyzico page so the next payments can be taken automatically.' => '定期的な寄付の場合は、iyzico ページで [カードを保存] にチェックを入れたままにして、次回の支払いが自動的に行われるようにします。',
  'TEST MODE (iyzico sandbox): no real money is taken.' => 'テスト モード (iyzico サンドボックス): リアルマネーはかかりません。',
  'Complete the payment in the iyzico window…' => 'iyzico ウィンドウで支払いを完了してください...',
