  'Confirmation code' => '確認コード',
  'Make another donation' => 'もう一度寄付をしてください',
  'The payment could not be completed. Please try again or use another card.' => '支払いを完了できませんでした。もう一度試すか、別のカードを使用してください。',
  'iyzico is not configured on this site. Please contact the site administrator.' => 'iyzico はこのサイトでは設定されていません。サイト管理者に連絡してください。',
  'The currency of this form is not supported.' => 'このフォームの通貨はサポートされていません。',
  'The payment could not be verified. Please contact the site administrator.' => '支払いを確認できませんでした。サイト管理者に連絡してください。',
  'Your card could not be saved for the recurring donation, so the payment was canceled and no money was taken. Please try again and keep "Save my card" ticked.' => '定期的な寄付のためにカードを保存できなかったため、支払いはキャンセルされ、お金は引き落とされませんでした。 「カードを保存」にチェックを入れたままにして、もう一度お試しください。',
  'Your card could not be saved for the recurring donation. Please contact us; the payment will be refunded.' => '定期的な寄付のためにカードを保存できませんでした。お問い合わせください。支払いは返金されます。',
  'Your donation was received, but your card was not saved, so it will not repeat automatically.' => '寄付は受領されましたが、カードは保存されていないため、自動的には繰り返されません。',
