  'Add payment' => '支払いを追加',
  'Agreements' => '合意',
  'Agreed cost per type and option. The price valid on the day an item is sent is kept on the item. A partner whose agreements for a type are all switched off gets no new work for it.' => 'タイプおよびオプションごとの合意されたコスト。商品発送日に有効な価格が商品に記載されます。あるタイプの契約がすべてオフになっているパートナーは、そのタイプに対する新しい作業を取得できません。',
  'Valid from' => '有効期限',
  'Delete this agreement? Items already sent keep their price.' => 'この契約を削除しますか?すでに発送された商品の価格はそのままです。',
  'Donation type and option' => '寄付の種類とオプション',
  'all options' => 'オプション',
  'Add agreement' => '契約を追加',
  '%s (cost)' => '%s(コスト)',
  'Brought in (gift price)' => '持ち込み(ギフト価格)',
  'All partners' => 'すべてのパートナー',
  'Gift price' => 'ギフトの価格',
  '%d without a price' . chr(0) . '%d without a price' => '価格なしの%d',
  'Re-read prices from the agreements' => '契約書から価格を再読み込みします',
  'Donations, donors and recurring gifts at a glance.' => '寄付、寄付者、定期的なギフトの概要。',
  'Custom' => 'カスタム',
  'The dashboard needs JavaScript.' => 'ダッシュボードには JavaScript が必要です。',
  'Sorry, you are not allowed to do that.' => '申し訳ありませんが、それは許可されていません。',
  'Tracking' => '追跡',
  'Extra tabs' => '追加のタブ',
  'Settings sections' => '設定セクション',
  'Default currency' => 'デフォルトの通貨',
  'Turkish lira (₺)' => 'トルコ リラ (₺)',
  'Euro (€)' => 'ユーロ (€)',
  'US dollar ($)' => '米ドル ($)',
  'Pound sterling (£)' => '英ポンド (£)',
  'Dashboard totals are in this currency; gifts in other currencies are listed but not added to the totals.' => 'ダッシュボードの合計はこの通貨で表示されます。他の通貨でのギフトはリストに表示されますが、合計には追加されません。',
  'Tracking module' => '追跡モジュール',
  'Chosen donation types get one item per unit with a code, sent to partners (with agreed prices and settlement), files and history. Leave it off if you do not need it.' => '選択した寄付タイプでは、コード付きのユニットごとに 1 つのアイテムがパートナーに送信され (価格と決済が合意された)、ファイルと履歴が付与されます。必要ない場合はオフのままにしておきます。',
  'A Reports screen with editable JSON reports (always on with the tracking module).' => '編集可能な JSON レポートを含むレポート画面 (追跡モジュールでは常にオン)。',
  'Gifts on behalf of a person' => '個人に代わってギフト',
  'Adds a proxy (vekâlet) text the donor accepts, intentions and one item per unit with the name of the person it is given for. Turns tracking on too.' => '寄付者が受け入れる委任状 (vekâlet) テキスト、意図、および贈られた人の名前を含むユニットごとに 1 つのアイテムを追加します。追跡もオンにします。',
  'Which payments are donations?' => 'どの支払いが寄付ですか?',
  'Every payment taken through a Flux Forms form' => 'Flux Forms フォームを通じて行われたすべての支払い',
  'Only payments through the forms selected below (and forms linked to a donation type)' => '以下で選択したフォーム (および寄付タイプにリンクされたフォーム) による支払いのみ',
  'How donations are recorded' => '寄付の記録方法',
  'A donation is stored when a Flux Forms payment is completed: at the final form submission (with name, phone and e-mail from the form), from the payment provider\'s notifications (refunds, renewals of recurring gifts) and by an hourly check that catches payments whose form was not submitted.' => '寄付金は、Flux Forms の支払いが完了すると保存されます。最終的なフォーム送信時 (フォームからの名前、電話番号、電子メールによる送信)、支払いプロバイダーの通知 (払い戻し、定期的なギフトの更新)、およびフォームが送信されなかった支払いを確認する 1 時間ごとの小切手によって保存されます。',
  'Donors are matched on phone number or e-mail address, never on name alone.' => '寄付者は名前だけではなく、電話番号または電子メール アドレスで照合されます。',
  'Shown on receipts, donation pages and in exports. Empty fields fall back to the site name, the theme logo and the theme colours.' => '領収書、寄付ページ、エクスポートに表示されます。空のフィールドは、サイト名、テーマのロゴ、テーマの色に戻ります。',
  'Organisation name' => '組織名',
  'Choose a logo' => 'ロゴを選択してください',
  'Brand colour' => 'ブランドカラー',
  'Hex colour such as #1F2937. Empty = the theme\'s primary colour.' => '#1F2937 などの 16 進数の色。空 = テーマの原色。',
  'Receipt text' => '受信テキスト',
  'A thank-you note printed on the donation receipt.' => '寄付受領書に感謝のメッセージが印刷されます。',
  'Footer text' => 'フッターのテキスト',
  'Address, registration number, bank details and similar; printed at the bottom of receipts.' => '住所、登録番号、銀行口座情報など。レシートの下部に印刷されます。',
  'Donation type categories' => '寄付タイプのカテゴリ',
  'Group donation types, e.g. Kurban, Ramazan, General. The key is stored on the types; a category that is in use cannot be removed.' => 'グループ寄付のタイプ (例:犠牲、ラマダン、将軍。キーはタイプに保存されます。使用中のカテゴリは削除できません。',
  'Save categories' => 'カテゴリを保存',
  'Used by %s type' . chr(0) . 'Used by %s types' => '%sタイプによって使用されます',
  'Remove category' => 'カテゴリを削除',
  'The words on the tracking screens. A donation type can use its own words (Donation types › Tracking); empty fields use these, and empty ones here the built-in words.' => '追跡画面上の単語。寄付の種類には独自の言葉を使用できます (寄付の種類 › 追跡)。空のフィールドにはこれらの単語が使用され、空のフィールドには組み込みの単語が使用されます。',
  'Early days' => '初期の頃',
  'How many days before the target date an item may already be done. After the target day it is still allowed, but shown as late.' => '項目が目標日の何日前にすでに完了している可能性があります。対象日を過ぎても許可されますが、遅いと表示されます。',
  'Proxy (vekâlet) text' => 'プロキシ (vekâlet) テキスト',
  'The text a donor accepts to authorise the organisation to give on their behalf. Every change is saved as a new version; each donation keeps the version that was accepted.' => '寄付者が寄付者に代わって寄付を組織に許可するために受け入れるテキスト。すべての変更は新しいバージョンとして保存されます。各寄付では、受け入れられたバージョンが保持されます。',
  'Who items are sent to, their agreed prices and payments are kept under Donations › Partners.' => 'アイテムの送付先、合意された価格および支払いは、「寄付」 > 「パートナー」に保管されます。',
  'Proxy text versions' => 'プロキシ テキストのバージョン',
  'No text yet. Donations of types that require a proxy cannot be paid until a text is saved.' => 'まだテキストがありません。代理人が必要なタイプの寄付は、テキストが保存されるまで支払うことができません。',
  'Version %1$s · %2$s' => 'バージョン%1$s·%2$s',
  'Add your own tabs with fields to tracked records ("on": "item") or donations ("on": "donation"), for all or some donation types. Leave it empty if you do not need any.' => 'すべてまたは一部の寄付タイプについて、追跡レコード ("on": "item") または寄付 ("on": "donation") にフィールドを含む独自のタブを追加します。必要ない場合は空のままにしておきます。',
  'Tabs (JSON list)' => 'タブ (JSON リスト)',
  'Tabs in use' => '使用中のタブ',
  'Record page' => 'レコードページ',
  '%d field' . chr(0) . '%d fields' => '%dフィールド',
  'from a plugin' => 'プラグインから',
  'No extra tabs yet.' => '追加のタブはまだありません。',
  'Reads completed payments stored by Flux Forms and adds the missing ones as donations. Safe to run more than once: a payment is never imported twice.' => 'Flux Forms に保存されている完了した支払いを読み取り、不足している支払いを寄付として追加します。複数回実行しても安全です。支払いが 2 回インポートされることはありません。',
  'Flux Forms\'s payment table was not found. Is Flux Forms installed?' => 'Flux Forms\\ の支払いテーブルが見つかりませんでした。 Flux Forms はインストールされていますか?',
  'Importing…' => 'インポート中...',
  'Import now' => '今すぐインポート',
  'Last run %1$s: %2$s payments checked, %3$s imported.' => '最後の実行%1$s:%2$sの支払いがチェックされ、%3$sがインポートされました。',
  'Upcoming (%s)' => '今後の予定 (%s)',
  'New donation type' => '新しい寄付タイプ',
  'Donation types and campaigns' => '寄付の種類とキャンペーン',
  'What people can give for: each type has its own prices and options, dates, goal and linked forms.' => '人々が寄付できるもの: 各タイプには独自の価格、オプション、日付、目標、リンクされたフォームがあります。',
  'Open and closed' => '開いた状態と閉じた状態',
  'The archive is empty' => 'アーカイブは空です',
  'No donation types yet' => '寄付の種類はまだありません',
  'Create a type such as a general donation, a sapling or a kurban share, set its prices, and link the forms that collect for it.' => '一般寄付、苗木、クルバン株などのタイプを作成し、価格を設定し、寄付を集めるフォームをリンクします。',
  'No category' => 'カテゴリがありません',
  '(inactive)' => '(非アクティブ)',
  '(price not set)' => '(価格は設定されていません)',
  'free amount (min. %s)' => '無料金額 (最小%s)',
  'free amount' => '無料金額',
  'quantity' => '数量',
  'recurring' => '繰り返し',
  '%1$s of %2$s (%3$s%%)' => '%1$s/%2$s(%3$s%%)',
  'Open-ended' => '無制限',
  'Load sample types' => 'サンプル タイプをロードします',
  'Adds ready-made types and categories that you can edit. Types whose sample price is 0 start closed until you set their prices.' => '編集可能な既製のタイプとカテゴリを追加します。サンプル価格が 0 のタイプは、価格が設定されるまでクローズ状態になります。',
  'Sample set' => 'サンプル セット',
  'Donation type not found' => '寄付の種類が見つかりません',
  'Edit donation type' => '寄付タイプを編集',
  'Edit categories' => 'カテゴリを編集',
  'Slug' => 'ナメクジ',
  'Optional; created from the title.' => 'オプション。タイトルから作成されました。',
  'Prices and the goal are in this currency. A linked form must charge in the same currency, otherwise its payments are stopped.' => '価格と目標はこの通貨で表示されます。リンクされたフォームは同じ通貨で請求する必要があります。そうでない場合、支払いは停止されます。',
  'Sheep' => '羊',
  'Camel' => 'ラクダ',
  'Card subtitle' => 'カードのサブタイトル',
  'One short line under the title on the type cards, e.g. "Sheep or goat".' => 'タイプ カードのタイトルの下に 1 行の短い行があります。例: "羊またはヤギ".',
  'Shown when the type has no image.' => 'タイプに画像がない場合に表示されます。',
  'Choose an image' => '画像を選択してください',
  'Prices and options' => '価格とオプション',
  'One option is a fixed price per unit (e.g. one sapling). Several options give the donor a choice (e.g. adak, akika, şifa). The amount charged is always computed on the server from these prices.' => 'オプションの 1 つは、単位あたりの固定価格です (例: 苗木 1 本)。いくつかのオプションがドナーに選択肢を与えます (adak、akika、şifa など)。請求金額は常にこれらの価格に基づいてサーバー上で計算されます。',
  'A price of 0 means the price is not announced yet: the option is shown but cannot be paid. An inactive option is hidden and cannot be paid.' => '価格 0 は、価格がまだ発表されていないことを意味します。オプションは表示されていますが、支払うことはできません。非アクティブなオプションは非表示になっているため、支払うことができません。',
  'Free amount allowed' => '許可される無料金額',
  'Minimum amount' => '最低金額',
  'Quantity allowed' => '許可される数量',
  'Maximum quantity' => '最大数量',
  'Empty = no limit.' => '空 = 制限なし。',
  'Recurring giving allowed' => '定期的な寄付は許可されています',
  'Linked forms' => 'リンクされたフォーム',
  'Gifts through these Flux Forms forms count for this type. Map each priced choice of the form to an option: the form then charges the price set here.' => 'これらの Flux Forms フォームを介したギフトは、このタイプにカウントされます。フォームの各価格選択肢をオプションにマッピングします。その後、フォームはここで設定された価格を請求します。',
  'No payment form found in Flux Forms yet.' => 'Flux Forms には支払いフォームがまだ見つかりません。',
  'also linked to: %s' => '次にもリンクされています:%s',
  'Save after choosing a form to map its choices.' => 'フォームを選択した後、その選択肢をマップするために保存します。',
  'Hide the choice in the form when it was preselected' => '事前に選択されていた場合、フォーム内の選択肢を非表示にします',
  'When the page passes a choice (flxb_opt in the address or FLXB.preselect()), the form shows a short summary with a "Change" link instead of the choice list.' => 'ページが選択肢 (アドレスの flxb_opt または FLXB.preselect()) を渡すと、フォームには選択肢リストの代わりに「変更」リンクを含む短い概要が表示されます。',
  'A closed type keeps its history but its forms no longer take payments.' => 'クローズドタイプは履歴を保持しますが、そのフォームは支払いを受け付けなくなります。',
  'End date' => '終了日',
  'Goal amount' => '目標金額',
  'Optional. Shown as a progress bar.' => 'オプション。進行状況バーとして表示されます。',
  'Show it on the site' => 'サイトに表示します',
  'Add baslik="hayir" to hide the title and description.' => 'タイトルと説明を非表示にするには、baslik="hayir" を追加します。',
  'Delete this donation type' => 'この寄付タイプを削除します',
  'Delete this donation type?' => 'この寄付タイプを削除しますか?',
  'This type has gifts, so it can be archived but not deleted.' => 'このタイプにはギフトがあるため、アーカイブすることはできますが、削除することはできません。',
  'Option name' => 'オプション名',
  'e.g. Sapling, Adak, Iftar' => 'e.g.苗木、アダック、イフタール',
  'from the name' => '名前から',
  'Remove option' => 'オプションを削除',
  '— not set' => '— ノートセット',
  'Units per choice' => '選択肢ごとの単位',
  'e.g. a whole animal = 7 shares' => 'e.g.動物全体 = 7 シェア',
  'not offered' => '提供されていません',
  'Translations' => '翻訳',
  'Shown on the donation page, the cart and the checkout in that language (Flux Lang). Empty fields use the texts above. Records keep the texts above. Save once after adding options to translate their names.' => '寄付ページ、カート、チェックアウトにその言語 (Flux Lang) で表示されます。空のフィールドには上記のテキストが使用されます。記録には上記のテキストが残っています。名前を翻訳するオプションを追加した後、一度保存します。',
  'Option: %s' => 'オプション:%s',
  'Each unit of a gift becomes its own item with a 7-digit code: approved, sent to a partner, completed, delivered to the owner, with files and history.' => 'ギフトの各ユニットは、7 桁のコードを持つ独自のアイテムになります。承認、パートナーへの送信、完了、所有者への配送、ファイルと履歴が含まれます。',
  'Track every unit one by one' => 'すべてのユニットを 1 つずつ追跡します',
  'Always on for gifts given on behalf of a person.' => '個人に代わって贈られるギフトの場合は常に有効です。',
  'The first file marks it completed' => '最初のファイルは完了をマークします',
  'Words for this type' => 'このタイプの単語\'、\'en\']]',
  'On behalf of a person' => '個人を代表して',
  'For types given on behalf of a named person: each unit becomes its own item with that person\'s name, and the donor must accept the proxy (vekâlet) text.' => '指定された人物に代わって提供されたタイプの場合: 各ユニットはその人物の名前が付いた独自のアイテムとなり、寄付者は代理 (vekâlet) テキストを受け入れる必要があります。',
  'Proxy (vekâlet) required' => 'プロキシ (vekâlet) が必要です',
  'Animal' => '動物',
  'Cattle (7 shares)' => '牛 (7 株)',
  'All of the meat goes to people in need' => 'すべての肉は困っている人々に寄付されます',
  'Mapping for “%s”' => '「%s」のマッピング',
  'This form charges in %1$s but the donation type is in %2$s: its payments are stopped until both use the same currency.' => 'このフォームの料金は%1$sですが、寄付タイプは%2$sです。両方が同じ通貨を使用するまで支払いは停止されます。',
  'This form has no priced choices to map.' => 'このフォームには、マップする価格の選択肢がありません。',
  'Form choice' => 'フォームの選択',
  'Units' => '単位',
  'form price: %s' => '形式価格:%s',
  'Not mapped (form price)' => 'マッピングされていません (フォーム価格)',
  'Quantity field' => '数量フィールド',
  'Free amount field' => '無料金額フィールド',
  'On behalf of (names field)' => '(名前フィールド) を代表して',
  'One name per line. Units without a name are given on behalf of the donor.' => '1 行に 1 つの名前。名前のないユニットは寄付者に代わって提供されます。',
  'Proxy consent field' => 'プロキシ同意フィールド',
  'Monthly, weekly or yearly gifts charged automatically by the payment provider.' => '毎月、毎週、または毎年のギフトは、決済プロバイダーによって自動的に請求されます。',
  'Name, e-mail, phone, reference…' => '名前、電子メール、電話番号、参照先...',
  'No recurring donations yet' => '定期的な寄付はまだありません',
  'A recurring donation is created when a payment form is set to charge every day, week, month or year.' => '定期的な寄付は、支払いフォームが毎日、毎週、毎月、または毎年請求されるように設定されている場合に作成されます。',
  '%s recurring donation' . chr(0) . '%s recurring donations' => '%sの定期的な寄付',
  'Interval' => '間隔',
  'Next charge' => '次の充電',
  'Attempt %1$s of %2$s failed: %3$s' => '%2$sの%1$sの試行が失敗しました:%3$s',
  'canceled %s' => 'キャンセルされました%s',
  'Cancel this recurring donation at the payment provider? No further charges will be made.' => '支払いプロバイダーでこの定期的な寄付をキャンセルしますか?それ以上の料金は発生しません。',
  'Card payments: the official iyzico plugin is enabled.' => 'カード支払い: 公式 iyzico プラグインが有効になっています。',
  'Card payments: Flux Donate iyzico (the official iyzico plugin is not enabled).' => 'カード支払い: Flux Donate iyzico (公式 iyzico プラグインは有効になっていません)。',
  'Card payments: %s.' => 'カード支払い:%s。',
  'No card method is enabled (WooCommerce › Settings › Payments).' => '有効なカード方法はありません (WooCommerce › 設定 › 支払い)。',
  'Monthly donations: Flux Donate iyzico is ready.' => '毎月の寄付: Flux Donate iyzico が準備できました。',
  'Monthly donations are off: enable "Card (iyzico) - Flux Donate" and enter iyzico keys.' => '毎月の寄付はオフです: 「カード (iyzico) - Flux Donate」を有効にして、iyzico キーを入力してください。',
  'Bank transfer (donations) is enabled.' => '銀行振込 (寄付) が有効になっています。',
  'Bank transfer (donations) is disabled.' => '銀行振込(寄付)は無効になっています。',
  'Flux Certificates is connected.' => 'Flux 証明書が接続されました。',
  'Flux Certificates is active but has no active template.' => 'Flux 証明書はアクティブですが、アクティブなテンプレートがありません。',
  'Flux Certificates is not active: no certificate is made after payment.' => 'Flux 証明書がアクティブではありません。支払い後に証明書は作成されません。',
  'Donation page:' => '寄付ページ:',
  'The donation options are not on a page yet.' => '寄付オプションはまだページにありません。',
  'WooCommerce is not active. Donations are paid through WooCommerce from version 2.0: install and activate WooCommerce.' => 'WooCommerce はアクティブではありません。バージョン 2.0 以降、寄付は WooCommerce を通じて支払われます。WooCommerce をインストールしてアクティブ化します。',
  'Sapling packages, prices and badges are edited on the donation type (Donations › Donation types). Which types give a certificate is set there too.' => '苗木のパッケージ、価格、バッジは寄付の種類に応じて編集されます (寄付 › 寄付の種類)。どのタイプが証明書を与えるかもそこに設定されます。',
  'Automatic ("Fidan Bağış Sertifikası")' => '自動 ("フィダン・バシュ・セルティフィカス")',
  'When chosen, online donation certificates count for this open event.' => '選択すると、オンライン寄付証明書がこのオープン イベントにカウントされます。',
  'Send by' => '送信者',
  'When the payment is confirmed the certificate link goes out on these channels. With a WhatsApp route no SMS is sent.' => '支払いが確認されると、証明書のリンクがこれらのチャネルに送信されます。 WhatsApp ルートでは SMS は送信されません。',
  '"Online + printed certificate"' => '「オンライン + 印刷された証明書」',
  'Shown as "Coming soon" (cannot be chosen)' => '「近日公開」と表示されます(選択できません)',
  'Can be chosen' => '選択可能',
  'Printed certificate fee (per line)' => '印刷証明書の料金 (1 行あたり)',
  '0 = free. Orders with a printed certificate stay "Processing"; set them to "Completed" when sent.' => '0 = 無料。証明書が印刷された注文は「処理中」のままです。送信時に「完了」に設定します。',
  'Complete paid orders with an online certificate automatically' => 'オンライン証明書を使用して有料注文を自動的に完了します',
  'IBAN, recipient and reference code: WooCommerce › Settings › Payments › Bank transfer (donations). The transfer details and the receipt link are added to WooCommerce\'s "on hold" e-mail.' => 'IBAN、受信者および参照コード: WooCommerce › 設定 › 支払い › 銀行振込 (寄付)。送金の詳細と受領リンクが WooCommerce の「保留中」電子メールに追加されます。',
  'Short notification' => '簡単な通知',
  'A short message to the donor\'s phone when a transfer is registered (through Flux Mail, or Flux Certificates\'s providers). With both ticked, SMS only goes out when there is no WhatsApp route.' => '(Flux Mail または Flux Certificates のプロバイダー経由で) 送金が登録されるときの、寄付者の電話への短いメッセージ。両方にチェックを入れると、WhatsApp ルートがない場合にのみ SMS が送信されます。',
  'WhatsApp text' => 'WhatsApp のテキスト',
  'Placeholders: {ad} {tutar} {siparis} {alici} {iban} {aciklama} {link} {site}' => 'プレースホルダー:{ad}{tutar}{siparis}{alici}{iban}{aciklama}{link}{site}',
  'SMS text' => 'SMS テキスト',
  'Largest receipt file (MB)' => '最大のレシート ファイル (MB)',
  'Tell this address when a receipt is uploaded' => '領収書をアップロードするときにこのアドレスを教えてください',
  'After "Donate"' => '「寄付」後',
  'Go straight to the checkout' => 'そのままチェックアウトに進んでください',
  'Go to the cart' => 'カートに移動します',
  'Stay on the page' => 'ページに留まります',
  'Currencies donors can choose' => '寄付者が選択できる通貨',
  '(store currency)' => '(ストア通貨)',
  'With more than one, donors pick the currency (shortcode [flx_bagis_para_birimi] or the theme). There are no exchange rates: set each option\'s price per currency on the donation type; options without a price in a currency are not offered in it. Check that your payment methods take these currencies.' => '複数の場合、寄付者は通貨 (ショートコード [flx_bagis_para_birimi] またはテーマ) を選択します。為替レートはありません。寄付の種類に応じて通貨ごとの各オプションの価格を設定します。通貨での価格のないオプションは提供されません。お支払い方法でこれらの通貨が利用できることを確認してください。',
  'Do not ask for an address at the checkout when the cart holds only donations' => 'カートに寄付のみが入っている場合は、チェックアウト時に住所を尋ねないでください',
  'Support WhatsApp number' => 'WhatsApp 番号をサポート',
  'Shown at the checkout and with the bank transfer details as "Any trouble? Write to us on WhatsApp". Leave empty to hide.' => 'チェックアウト時に「何か問題がありましたら、WhatsApp にご連絡ください」という銀行振込の詳細が表示されます。非表示にするには空のままにしておきます。',
  '— Choose —' => '— 選択 —',
  '"Donate" links and the hidden product pages go here.' => '「寄付」リンクと非表示の製品ページはここにあります。',
  'Card payment method' => 'カード支払い方法',
  'Automatic: another virtual POS if one is enabled (e.g. EsnekPOS), otherwise iyzico' => '自動: 有効な場合は別の仮想 POS (EsnekPOS など)、そうでない場合は iyzico',
  'iyzico' => 'iyzico',
  'Show every enabled card method' => '有効なカード メソッドをすべて表示',
  'Donors see one card method; now: %s. Monthly donations always use Flux Donate iyzico (it stores the card). Bank transfer is always shown.' => '寄付者には 1 つのカード方式が表示されます。現在:%s。毎月の寄付には常に Flux Donate iyzico を使用します (カードを保存します)。銀行振込は常に表示されます。',
  'all' => '\\n\\n',
  'Show other payment plugins on the checkout block' => 'チェックアウト ブロックに他の支払いプラグインを表示します',
  'Virtual POS plugins that take the card on their own page but have no checkout block support (for example EsnekPOS) are added to the Checkout block. Plugins with their own card fields need the classic checkout.' => 'カードを独自のページに表示するが、チェックアウト ブロックをサポートしていない仮想 POS プラグイン (EsnekPOS など) は、チェックアウト ブロックに追加されます。独自のカード フィールドを持つプラグインには、クラシック チェックアウトが必要です。',
  'Flux Forms payment forms continue on the WooCommerce checkout' => 'Flux Forms 支払いフォームは引き続き WooCommerce チェックアウトで使用できます',
  'The donor picks card or bank transfer there; the form entry, the certificate automation and the donation record are completed when the order is paid.' => '寄付者はそこでカードまたは銀行振込を選択します。注文の支払いが完了すると、フォームの入力、証明書の自動化、寄付の記録が完了します。',
  'Card payment screen' => 'カード決済画面',
  'Our own card fields on the checkout (3D Secure, installments, saved cards)' => 'チェックアウト時の独自のカード フィールド (3D セキュア、分割払い、保存されたカード)',
  'iyzico payment page (as before)' => 'iyzico 支払いページ (以前と同様)',
  'Official iyzico plugin for one-time donations' => '1 回限りの寄付用の公式 iyzico プラグイン',
  'Card numbers go straight to iyzico and are never stored on this site. Monthly donations always use Flux Donate iyzico (it stores the card).' => 'カード番号は iyzico に直接送信され、このサイトに保存されることはありません。毎月の寄付には常に Flux Donate iyzico を使用します (カードが保存されます)。',
  'Most installments' => 'ほとんどの分割払い',
  'Single payment only' => '一括支払いのみ',
  'With our own card fields. The options and any interest come from iyzico for each card.' => '独自のカードフィールド付き。オプションと利息は各カードの iyzico から提供されます。',
  'Add the "Donation options" block to any page, or create a ready page:' => '「寄付オプション」ブロックを任意のページに追加するか、準備ができたページを作成します:',
  'Create the online donation page' => 'オンライン寄付ページを作成します',
  'Product list (XML)' => '製品リスト (XML)',
  'For iyzico "upload your products with XML" and Google Merchant Center. Every fixed-price option on sale is one product; free amounts are left out. Updating daily is enough.' => 'iyzico の場合は、「XML を使用して商品をアップロード」および Google Merchant Center を使用します。販売されている固定価格オプションはすべて 1 つの製品です。無料の金額は省略されています。毎日更新するだけで十分です。',
  'Shortcode and block' => 'ショートコードとブロック',
  'Without attributes it shows the donation types marked "Show in the Donation options block". tur="slug1,slug2" shows only those types; sekme="slug" opens that type\'s tab first. In the editor: "Donation options" block.' => '属性がないと、「寄付オプション ブロックに表示」とマークされた寄付タイプが表示されます。 tur="slug1,slug2" はそれらのタイプのみを表示します。 sekme="slug" は、最初にそのタイプのタブを開きます。エディタ内: 「寄付オプション」ブロック。',
  'Choose a sapling package or give any amount you like. You can pay by card or bank transfer; a certificate is made in your name.' => '苗木のパッケージを選択するか、お好きな量を与えてください。カードまたは銀行振込でお支払いいただけます。証明書はあなたの名前で作成されます。',
  'Online donation page' => 'オンライン寄付ページ',
  'How this type appears in the "Donation options" block and the WooCommerce cart. Its hidden WooCommerce product is kept in step automatically.' => 'このタイプが「寄付オプション」ブロックと WooCommerce カートにどのように表示されるか。非表示の WooCommerce 製品は自動的に同期されます。',
  'Show in the "Donation options" block (donation page) and the product XML' => '「寄付オプション」ブロック (寄付ページ) と製品 XML に表示されます',
  'Give a certificate (Flux Certificates)' => '証明書を与える (Flux 証明書)',
  'Same as the WooCommerce settings' => 'WooCommerce 設定と同じ',
  'Option with a − / + quantity' => '- / + 数量のオプション',
  'This option\'s card gets − / + buttons (e.g. "1 sapling"); price = number × this option\'s price, checked again on the server. The other options stay fixed packages. Use "Maximum quantity" above for the limit.' => 'このオプションのカードには - / + ボタンが表示されます (例: 「1 苗木」);価格 = 数値 × このオプションの価格。サーバー上で再度確認されます。他のオプションは固定パッケージのままです。制限には上記の「最大数量」を使用してください。',
  'Preset amounts (free amount)' => 'プリセット金額 (無料金額)',
  'Separated by spaces, e.g. 250 500 1000.' => 'スペースで区切ります。例: 250 500 1000。',
  'Preset amounts in %s' => '%sのプリセット量 ',
  'Page address' => 'ページアドレス',
  'Optional: where its product page and the product XML link go. Empty = the donation page in the WooCommerce settings.' => 'オプション: 製品ページと製品 XML リンクの場所。空 = WooCommerce 設定の寄付ページ。',
  'WooCommerce product #%d (hidden from the shop).' => 'WooCommerce 製品番号%d(ショップでは非表示)。',
  'This order has no donation line.' => 'この注文には寄付ラインがありません。',
  'Donation records:' => '寄付記録:',
  'Reference code:' => '参照コード:',
  'Make the certificate' => '証明書を作成します',
  'Refund this amount to the donor\'s card?' => 'この金額を寄付者のカードに返金しますか?',
  'Record this refund? The money is not sent back automatically for this payment method.' => 'この払い戻しを記録しますか?この支払い方法では、お金は自動的に返金されません。',
  'Record refund' => '払い戻しを記録する',
  'Refunded through WooCommerce and the payment method; the record follows.' => 'WooCommerce および支払い方法を通じて返金されます。記録が続きます。',
  'Recorded in WooCommerce only: send the money back yourself (e.g. by bank transfer).' => 'WooCommerce でのみ記録されます: ご自身で返金してください (銀行振込など)。',
  'Order line not found.' => '注文明細行が見つかりません。',
  'Enter an amount up to what is left to refund.' => '払い戻し可能な残額までの金額を入力してください。',
  'Refunded from Flux Donate by %s' => '%sによる Flux Donate から返金されました ',
  'No donation lines.' => '寄付ラインはありません。',
  'Unknown donation type.' => '寄付の種類が不明です。',
  'The donation product could not be created.' => '寄付商品を作成できませんでした。',
  'Recorded in Flux Chat (donation #%d).' => 'Flux Chat に記録されました (寄付 #%d)。',
  'Canceled in Flux Donate.' => 'Flux Donate でキャンセルされました。',
  'Put on hold in Flux Donate.' => 'Flux Donate を保留します。',
  'Marked as failed in Flux Donate.' => 'Flux Donate で失敗としてマークされました。',
  'This payment link has expired. Please fill in the form again.' => 'この支払いリンクの有効期限が切れています。フォームにもう一度入力してください。',
  'Flux Forms entry %s completed by this payment.' => 'この支払いにより、Flux Forms エントリ%sが完了しました。',
  'After you place the order you will see the IBAN and your own reference code. Once you have paid you can upload the receipt on the site; your certificate is sent when the payment is confirmed.' => '注文すると、IBAN と独自の参照コードが表示されます。支払いが完了したら、サイトに領収書をアップロードできます。支払いが確認されると証明書が送信されます。',
  'Your pre-registration is in' => '事前登録は完了しています',
  'To complete your donation, make a bank transfer to the account below. Please write your own reference code in the description.' => '寄付を完了するには、以下の口座に銀行振込を行ってください。説明に独自の参照コードを記述してください。',
  'The reference code lets us match your payment to your donation.' => '参照コードを使用すると、お支払いと寄付を照合できます。',
  'Receive your certificate' => '証明書を受け取ります',
  'Once the payment is confirmed your certificate is sent by WhatsApp and e-mail; it also appears under My account › Orders.' => '支払いが確認されたら、証明書は WhatsApp と電子メールで送信されます。 [マイ アカウント] › [注文] にも表示されます。',
  'We confirm your donation' => 'あなたの寄付を確認します',
  'Once the payment is confirmed the order is completed and you get an e-mail; it also appears under My account › Orders.' => '支払いが確認されると注文が完了し、電子メールが届きます。 [マイ アカウント] › [注文] にも表示されます。',
  'My pending donations' => '保留中の寄付',
  'Card number' => 'カード番号',
  'Name on the card' => 'カード上の名前',
  'Expiry (MM/YY)' => '有効期限 (MM/YY)',
  'card expiry placeholderMM/YY' => 'MM/YY',
  'CVC' => 'CVC',
  'Save my card for next time' => '次回のためにカードを保存してください',
  'iyzico keeps the card; this site never stores card numbers.' => 'iyzico はカードを保持します。このサイトではカード番号は保存されません。',
  'For the monthly donation iyzico keeps your card and charges it once a month. You can cancel at any time.' => '毎月の寄付については、iyzico がカードを保管し、月に 1 回請求します。いつでもキャンセルできます。',
  'Use another card' => '別のカードを使用してください',
  'Your saved cards' => '保存したカード',
  'Installments' => '分割払い',
  'Single payment' => '一括支払い',
  '%1$s installments × %2$s (total %3$s)' => '%1$s分割払い ×%2$s(合計%3$s)',
  'Installment options appear after the card number.' => 'インストール オプションはカード番号の後に表示されます。',
  'Please check the card number.' => 'カード番号を確認してください。',
  'Please write the name on the card.' => 'カードに名前を書いてください。',
  'Please check the expiry date.' => '有効期限を確認してください。',
  'Please check the security code (CVC).' => 'セキュリティ コード (CVC) を確認してください。',
  'Paid with 3D Secure through iyzico. Your bank may send you a code.' => 'iyzico を通じて 3D セキュアで支払いました。銀行からコードが送信される場合があります。',
  'Test mode: use an iyzico test card, e.g. 5528 7900 0000 0008, 12/30, 123.' => 'テスト モード: iyzico テスト カードを使用します。 5528 7900 0000 0008、12/30、123.',
  'Fill in the test card' => 'テストカードに記入してください',
  'Test mode accepts only iyzico test cards. Use "Fill in the test card".' => 'テスト モードでは、iyzico テスト カードのみが受け入れられます。 「テスト カードに記入」を使用してください。',
  'Card payments are not configured on this site. Please choose another payment method.' => 'このサイトではカード支払いが設定されていません。別のお支払い方法を選択してください。',
  'The amount must be greater than zero.' => '金額はゼロより大きくなければなりません。',
  'This saved card cannot be used any more. Please enter the card.' => 'この保存されたカードはもう使用できません。カードを入力してください。',
  'This installment option is not available for the card. Please choose another.' => 'このカードではこの分割払いオプションは利用できません。別のものを選択してください。',
  'Card payment could not start: %1$s (card %2$s, %3$s).' => 'カード支払いを開始できませんでした:%1$s(カード%2$s、%3$s)。',
  'test mode' => 'テストモード',
  'live' => 'ライブ',
  'Card payment started: %1$s installments, %2$s charged by the bank.' => 'カード支払いが開始されました:%1$s分割払い、銀行によって%2$s請求されます。',
  'iyzico 3D Secure: %s' => 'iyzico 3D セキュア:%s',
  'The bank did not confirm the 3D Secure code. Please try again.' => '銀行は 3D セキュア コードを確認しませんでした。もう一度試してください。',
  'This card is not enrolled for 3D Secure. Please call your bank or use another card.' => 'このカードは 3D セキュアに登録されていません。銀行に電話するか、別のカードを使用してください。',
  'The bank could not check the card. Please try again or use another card.' => '銀行はカードを確認できませんでした。もう一度試すか、別のカードを使用してください。',
  'iyzico: the payment was not completed (%s).' => 'iyzico: 支払いは完了しませんでした (%s)。',
  'Default address' => 'デフォルトのアドレス',
  'The page has expired. Please try again.' => 'ページの有効期限が切れています。もう一度試してください。',
  'Please fill in the name, address and city.' => '名前、住所、市区町村を入力してください。',
  'Address deleted.' => 'アドレスが削除されました。',
  'Default address changed.' => 'デフォルトのアドレスが変更されました。',
  'Address book' => 'アドレス帳',
  'Saved addresses are offered in a list at the checkout. The default one is filled in automatically.' => '保存された住所はチェックアウト時にリストに表示されます。デフォルトの値は自動的に入力されます。',
  'Delete this address?' => 'このアドレスを削除しますか?',
  '+ Add a new address' => '+ 新しいアドレスを追加',
  'Address name' => 'アドレス名',
  'e.g. Home, Office' => 'e.g.自宅、オフィス',
  'Saved address' => '保存されたアドレス',
  'Write the new address below; it is saved to your address book with the order.' => '新しいアドレスを下に記入してください。注文と一緒にアドレス帳に保存されます。',
  'Manage addresses' => 'アドレスの管理',
  'Keys are read from the iyzico WooCommerce plugin settings.' => 'キーは iyzico WooCommerce プラグイン設定から読み取られます。',
  'Keys are read from Donations › Settings › Payments › iyzico.' => 'キーは、寄付 › 設定 › 支払い › iyzico から読み取られます。',
  'No iyzico keys found. Enter them in the iyzico WooCommerce plugin or in Donations › Settings › Payments › iyzico.' => 'iyzico キーが見つかりません。これらを iyzico WooCommerce プラグインまたは寄付 › 設定 › 支払い › iyzico に入力してください。',
  'Environment: sandbox (test).' => '環境: サンドボックス (テスト)。',
  'Environment: live.' => '環境: ライブ。',
  'iyzico reported a payment (%s) that does not match this order (amount, currency or basket). Check it in the iyzico panel before doing anything.' => 'iyzico は、この注文 (金額、通貨、またはバスケット) と一致しない支払い (%s) を報告しました。何かを行う前に、iyzico パネルで確認してください。',
  'iyzico payment received: %1$s, payment id %2$s (%3$s).' => 'iyzico 支払いを受け取りました:%1$s、支払い ID%2$s(%3$s)。',
  'Enter an amount to refund.' => '返金する金額を入力してください。',
  'This order has no iyzico transaction to refund.' => 'この注文には返金する iyzico トランザクションがありません。',
  'The amount is more than what is left to refund at iyzico.' => '金額が iyzico で返金できる残額を超えています。',
  'iyzico refused the refund: %s' => 'iyzico が払い戻しを拒否しました:%s',
  'Refunded at iyzico: %1$s. %2$s' => 'iyzico で返金:%1$s。%2$s',
  'Classic' => 'クラシック',
  'One card: type tabs on top, the choices under them, the total at the bottom.' => '1 枚のカード: 上部にタブ、その下に選択肢、下部に合計を入力します。',
  'A · Steps + summary' => 'A · 手順 + 概要',
  'Numbered steps on the left, a summary with the total and the button on the right.' => '左側に番号付きのステップ、右側に合計の概要とボタンが表示されます。',
  'B · Two panels' => 'B · 2 つのパネル',
  'Types as a list on the left, the details on the right; a dark total bar.' => '左側にリストとして入力し、右側に詳細を入力します。暗い合計バー。',
  'C · Picture cards' => 'C · 絵カード',
  'Large cards with the type picture or icon; the details open below.' => 'タイプの画像またはアイコンが付いた大きなカード。詳細は以下で開きます。',
  'All options one under the other.' => 'すべてのオプションは下にあります。',
  'Drop-down' => 'ドロップダウン',
  'One row: the option in a drop-down menu and the quantity beside it.' => '1 行: ドロップダウン メニューのオプションとその横の数量。',
  'List, then one row' => 'リスト、次に 1 行',
  'The list first; after a pick it folds into one row (drop-down + quantity) and the rest of the form opens.' => 'リストが最初です。選択後、1 行 (ドロップダウン + 数量) に折りたたまれ、フォームの残りの部分が開きます。',
  'The look of WooCommerce and the theme.' => 'WooCommerce の外観とテーマ。',
  'Methods as cards with icons; the details of the picked one below.' => 'アイコン付きのカードとしてのメソッド。選択したものの詳細は以下をご覧ください。',
  'Rows one under the other; the picked row opens.' => '行を上下に並べます。選択した行が開きます。',
  'One row of tab buttons; the details of the picked one below.' => '1 行のタブ ボタン。選択したものの詳細は以下をご覧ください。',
  'Options and amount' => 'オプションと金額',
  'On whose behalf' => '誰に代わって',
  'Certificate design' => '証明書のデザイン',
  'Repeat every month' => '毎月繰り返します',
  'How the "Donation options" block looks on the site. Prices, options and names are set under Donation types.' => 'サイト上の「寄付オプション」ブロックの外観。価格、オプション、名前は「寄付の種類」で設定します。',
  'View the page' => 'ページを見る',
  'Heading over the types' => 'タイプの見出し',
  'Shown in the A and C layouts.' => 'A および C レイアウトで表示されます。',
  'Heading over the options' => 'オプションの見出し',
  'Choose an option' => 'オプションを選択してください',
  'How the options are shown' => 'オプションの表示方法',
  'Order of the sections' => 'セクションの順序',
  'The type choice is always first and the total always last. Sections a type does not use are skipped.' => 'タイプの選択は常に最初であり、合計は常に最後になります。タイプが使用しないセクションはスキップされます。',
  'Ask a phone number for every share (types with a proxy). The video or certificate of that share can be sent there too.' => 'すべての共有について電話番号を尋ねます (プロキシを使用するタイプ)。その共有のビデオまたは証明書もそこに送信できます。',
  'Payment options at the checkout' => 'チェックアウト時の支払いオプション',
  'How card, PayPal, bank transfer and the other methods are shown. The methods themselves are turned on under WooCommerce › Settings › Payments.' => 'カード、PayPal、銀行振込、その他の方法が表示されます。メソッド自体は、「WooCommerce」 > 「設定」 > 「支払い」で有効になります。',
  'Colours and corners' => '色と角',
  'Used by the form and the payment options. Empty fields follow the theme.' => 'フォームと支払いオプションで使用されます。空のフィールドはテーマに従います。',
  'Corner radius (px)' => 'コーナー半径 (ピクセル)',
  '0 = square, 4 = plain corporate, 16 = round.' => '0 = 正方形、4 = 普通の企業、16 = 円形。',
  'Transaction fee' => '取引手数料',
  'Donors can choose to also pay the fee of the payment method, so the whole donation reaches you. The fee is added at the checkout for the method they pick.' => '寄付者は、寄付金全額が届くように、支払い方法の手数料も支払うことを選択できます。料金は、選択した方法に応じてチェックアウト時に追加されます。',
  'Show "I will cover the transaction fee" on the donation form' => '寄付フォームに「取引手数料は私が負担します」と表示します',
  'Ticked by default' => 'デフォルトでチェックマークが付いています',
  'Fixed' => '修正されました',
  'Empty or 0 = no fee for that method (for example bank transfer). Fee = donation × % + fixed.' => '空または 0 = その方法 (銀行振込など) の手数料はかかりません。料金 = 寄付 × % + 固定。',
  'Please choose what you would like to donate for.' => '寄付したいものを選択してください。',
  'This option cannot be donated in %s. Please choose another currency.' => 'このオプションは%sでは寄付できません。別の通貨を選択してください。',
  'This option cannot be donated online at the moment.' => 'このオプションは現時点ではオンラインで寄付できません。',
  'The number must be between 1 and %s.' => '数値は 1 ~%sの間である必要があります。',
  'The amount must be at least %s.' => '金額は少なくとも%sである必要があります。',
  'For this amount please get in touch with us.' => 'この金額については、お問い合わせください。',
  'Please choose an option.' => 'オプションを選択してください。',
  'Printed certificates are not available yet. Please choose the online certificate.' => '印刷された証明書はまだ利用できません。オンライン証明書を選択してください。',
  'Please write the postal address for the printed certificate.' => '印刷された証明書の住所を記入してください。',
  'Please write the name of the person you are donating for.' => '寄付する人の名前を書いてください。',
  'This donation needs a proxy (vekâlet) consent, but it is not set up yet. Please contact the site administrator.' => 'この寄付には代理人 (vekâlet) の同意が必要ですが、まだ設定されていません。サイト管理者に連絡してください。',
  'The proxy (vekâlet) text has been updated. Please read it again and accept it.' => 'プロキシ (vekâlet) テキストが更新されました。もう一度読んで同意してください。',
  'Please write at most %s name (one per share).' . chr(0) . 'Please write at most %s names (one per share).' => '%s名は最大でも書き込んでください (1 シェアにつき 1 つ)。',
  'The phone number does not look right. Example: 0532 123 45 67' => '電話番号が正しくありません。例: 0532 123 45 67',
  'The e-mail address does not look right.' => '電子メール アドレスが正しくありません。',
  'This cause does not take monthly donations.' => 'この活動には毎月の寄付は必要ありません。',
  'Monthly donations are not available at the moment.' => '現在、毎月の寄付はご利用いただけません。',
  'Donations in %s cannot be paid here at the moment.' => '%sでの寄付は、現時点ではここでお支払いいただけません。',
  'The donation product could not be found.' => '寄付製品が見つかりませんでした。',
  'It could not be added to the cart.' => 'カートに追加できませんでした。',
  'A donation in your cart cannot be paid in %s and was removed.' => 'カート内の寄付は%sで支払うことができないため、削除されました。',
  'A donation in your cart is no longer available and was removed.' => 'カート内の寄付は利用できなくなったため、削除されました。',
  'Printed certificates can only be paid in the store currency; your certificate will be sent online.' => '印刷された証明書はストア通貨でのみ支払うことができます。証明書はオンラインで送信されます。',
  'Products in your cart can only be paid in %1$s. <a href="%2$s">Switch to %1$s</a>' => 'カート内の商品は%1$sでのみお支払いいただけます。<a href="%2$s">%1$s</a>に切り替えます ',
  'Printed certificate delivery' => '印刷された証明書の配信',
  'Repeats' => '繰り返し',
  'Names (one per share)' => '名前 (共有ごとに 1 つ)',
  'Design' => 'デザイン',
  'Name on the certificate' => '証明書の名前',
  'Sent to' => '送信先',
  'copy to me' => '私にコピーしてください',
  'Postal address' => '郵便番号',
  'accepted (text version %s)' => '受け入れられました (テキスト バージョン%s)',
  'Online + printed' => 'オンライン + 印刷',
  '%s Sapling Donation' => '%s苗木の寄付',
  'Certificate no' => '証明書がありません',
  'The certificate could not be made: no Flux Certificates template was found (Donations › Settings › WooCommerce).' => '証明書を作成できませんでした。Flux 証明書テンプレートが見つかりませんでした (寄付 › 設定 › WooCommerce)。',
  'The certificate could not be made: %s' => '証明書を作成できませんでした:%s',
  'Not sent yet.' => 'まだ送信されていません。',
  'Certificate made: %1$s (%2$s). %3$s' => '作成された証明書:%1$s(%2$s)。%3$s',
  'Certificates made again (%d); the old ones were revoked.' => '証明書が再度作成されました (%d);古いものは取り消されました。',
  'No delivery channel is chosen.' => '配信チャネルが選択されていません。',
  'Queued: %s.' => 'キューに登録されました:%s。',
  'Copy to the donor: %s.' => '寄付者にコピーします:%s。',
  'The preview could not be drawn. You can open it with "View certificate".' => 'プレビューを描画できませんでした。 「証明書の表示」で開くことができます。',
  'Your certificate is ready' . chr(0) . 'Your certificates are ready' => '証明書の準備ができました',
  'No: %s' => 'いいえ:%s',
  'View certificate' => '証明書を表示',
  'Your certificate is being prepared. It will be sent by WhatsApp and e-mail in a few minutes; you can also refresh this page to see it.' => '証明書を準備中です。数分以内に WhatsApp と電子メールで送信されます。このページを更新して表示することもできます。',
  'This certificate design cannot be chosen any more. Please pick another one.' => 'この証明書のデザインはもう選択できません。別のものを選択してください。',
  'Please fill in "%s" for the certificate.' => '証明書には「%s」と入力してください。',
  'Pick the design of your certificate. The donation amount does not change.' => '証明書のデザインを選択してください。寄付額は変わりません。',
  '"%s" was paid once: the card was not stored, so it will not repeat monthly.' => '「%s」は一度支払われました: カードは保存されていないため、毎月繰り返されることはありません。',
  '"%1$s" repeats monthly (recurring donation #%2$d); the card is stored at iyzico.' => '「%1$s」は毎月繰り返されます (定期的な寄付 #%2$d)。カードは iyzico に保管されます。',
  'Card (iyzico), monthly' => 'カード (iyzico)、毎月',
  'Monthly renewal of recurring donation #%1$d (first order #%2$s).' => '定期的な寄付 #%1$dの毎月の更新 (最初の注文 #%2$s)。',
  'Monthly charge accepted by iyzico: %1$s, payment id %2$s.' => 'iyzico が受け入れた月額料金:%1$s、支払い ID%2$s。',
  'Monthly charge failed after the last attempt: %s' => '最後の試行後に月額請求が失敗しました:%s',
  'Monthly charge failed, it will be retried: %s' => '月額請求に失敗しました。再試行されます:%s',
  'Flux Donate always uses EsnekPOS\'s secure payment page; the bank asks for 3D Secure there when needed.' => 'Flux Donate は常に EsnekPOS の安全な支払いページを使用します。銀行は必要に応じて 3D セキュアを要求します。',
  'Flux Donate' => 'フラックス寄付',
  'Flux Donate runs this payment method: classic and block checkout, payment links without a cart, and every payment is confirmed with EsnekPOS from the server before the order is marked paid. For a test, enter merchant TEST1234 and the test merchant key from EsnekPOS\'s developer page.' => 'Flux Donate は、この支払い方法を実行します。クラシック チェックアウトとブロック チェックアウト、カートを使用しない支払いリンク、注文が支払い済みとしてマークされる前に、すべての支払いがサーバーから EsnekPOS で確認されます。テストするには、EsnekPOS の開発者ページから販売者 TEST1234 とテスト販売者キーを入力します。',
  'Donation #%d' => '寄付 #%d',
  'EsnekPOS did not answer (HTTP %d).' => 'EsnekPOS が応答しませんでした (HTTP%d)。',
  'EsnekPOS payment could not start: %s' => 'EsnekPOS 支払いを開始できませんでした:%s',
  'EsnekPOS payment could not start: %1$s (%2$s).' => 'EsnekPOS 支払いを開始できませんでした:%1$s(%2$s)。',
  'The payment is being checked. Please wait a moment and refresh the page.' => '支払いを確認中です。しばらく待ってからページを更新してください。',
  'EsnekPOS payment could not be checked: %s' => 'EsnekPOS 支払いを確認できませんでした:%s',
  'The payment could not be verified yet. If money was taken from your card, please contact us before trying again.' => '支払いはまだ確認できませんでした。カードからお金が引き落とされた場合は、再試行する前に当社にご連絡ください。',
  'EsnekPOS payment received: reference %1$s, %2$s installment(s), %3$s charged.' => 'EsnekPOS 支払いを受け取りました: 参照%1$s、%2$s分割払い、%3$sが請求されました。',
  'EsnekPOS reported a payment (%s) that does not match this order (amount or reference). Check it in the EsnekPOS panel before doing anything.' => 'EsnekPOS は、この注文 (金額または参照) と一致しない支払い (%s) を報告しました。何かを行う前に、EsnekPOS パネルで確認してください。',
  'EsnekPOS return said success but EsnekPOS did not confirm the payment: %s' => 'EsnekPOS 返品は成功と表示されましたが、EsnekPOS は支払いを確認しませんでした:%s',
  'EsnekPOS: the payment was not completed (%s).' => 'EsnekPOS: 支払いが完了しませんでした (%s)。',
  'Test mode (merchant TEST1234).' => 'テスト モード (マーチャント TEST1234)。',
  'Flux Donate sends the order lines, no cart needed.' => 'Flux Donate は注文明細を送信します。カートは必要ありません。',
  'Flux Donate asks EsnekPOS (ProcessQuery) before the order is marked paid.' => 'Flux Donate は、注文が支払い済みとしてマークされる前に EsnekPOS (ProcessQuery) を要求します。',
  'On EsnekPOS\'s payment page, as set in the EsnekPOS panel.' => 'EsnekPOS パネルで設定された EsnekPOS の支払いページ。',
  'Refund in the EsnekPOS panel, then mark the order refunded.' => 'EsnekPOS パネルで返金し、注文に返金済みのマークを付けます。',
  'Donation of %1$s sapling. %2$s plants it for you and sends an online certificate in your name. Pay by card or bank transfer.' . chr(0) . 'Donation of %1$s saplings. %2$s plants them for you and sends an online certificate in your name. Pay by card or bank transfer.' => '%1$sの苗木を寄贈。%2$sはあなたのためにそれらを植え、あなたの名前でオンライン証明書を送信します。カードまたは銀行振込でお支払いください。',
  'Donation packages' => '寄付パッケージ',
  'Donation > %s' => '寄付 >%s',
  'I will also cover the transaction fee' => '取引手数料も私が負担します',
  'So your whole donation reaches its purpose. The exact fee depends on the payment method and is shown at the checkout.' => 'したがって、あなたの寄付金はすべてその目的を達成できます。正確な料金は支払い方法によって異なり、チェックアウト時に表示されます。',
  'Transaction fee (covered by you)' => '取引手数料 (お客様負担)',
  'Any trouble? Write to us on WhatsApp:' => '何か問題はありますか? WhatsApp でご連絡ください:',
  'No badge' => 'バッジがありません',
  'Best value' => '最良の価値',
  'Most popular' => '最も人気のある\'、\'en\']]',
  'Family pack' => 'ファミリー パック',
  'Hello {ad}, your donation of {tutar} is registered. IBAN: {iban} Reference: {aciklama} Upload your receipt: {link}' => 'こんにちは{ad}さん。{tutar}の寄付が登録されました。 IBAN:{iban}参照:{aciklama}領収書のアップロード:{link}',
  'Hello {ad} 🌱' . chr(10) . '' . chr(10) . 'Your donation of *{tutar}* is registered (No: {siparis}).' . chr(10) . '' . chr(10) . 'Bank transfer details:' . chr(10) . 'Recipient: {alici}' . chr(10) . 'IBAN: {iban}' . chr(10) . 'Reference: *{aciklama}*' . chr(10) . '' . chr(10) . 'After the transfer you can upload your receipt here:' . chr(10) . '{link}' . chr(10) . '' . chr(10) . 'Thank you,' . chr(10) . '{site}' => 'こんにちは{ad}🌱' . chr(10) . '' . chr(10) . 'あなたの *{tutar}* の寄付が登録されました (いいえ:{siparis})。' . chr(10) . '' . chr(10) . '銀行振込の詳細:' . chr(10) . '受取人:{alici}' . chr(10) . 'IBAN:{iban}' . chr(10) . '参照: *{aciklama}*' . chr(10) . '' . chr(10) . '送金後、ここに領収書をアップロードできます:' . chr(10) . '{link}' . chr(10) . '' . chr(10) . 'ありがとうございます。' . chr(10) . '{site}',
  'Pending transfer notification sent: %s.' => '送信された保留中の転送通知:%s。',
  'WooCommerce checks' => 'WooCommerce チェック',
  'Version %1$s is active. Flux Donate was checked up to %2$s; it uses only stable public WooCommerce functions, but test a donation after big WooCommerce updates.' => 'バージョン%1$sはアクティブです。 Flux Donate は%2$sまでチェックされました。安定した公開 WooCommerce 機能のみを使用しますが、WooCommerce の大幅な更新後に寄付をテストします。',
  'Active, version %s. Donations are paid through the WooCommerce cart and checkout.' => 'アクティブ、バージョン%s。寄付は、WooCommerce カートとチェックアウトを通じて支払われます。',
  'One-time card payments are taken by %s; iyzico is not shown at the checkout.' => '1 回限りのカード支払いは%sによって行われます。 iyzico はチェックアウト時に表示されません。',
  'One-time card payments are taken by the official iyzico WooCommerce plugin.' => '1 回限りのカード支払いは、公式 iyzico WooCommerce プラグインによって行われます。',
  'Card payments use our own card fields on the checkout (iyzico 3D Secure, installments, saved cards).' => 'カード支払いでは、チェックアウト時に独自のカード フィールドを使用します (iyzico 3D セキュア、分割払い、保存されたカード)。',
  'One-time card payments are taken by Flux Donate iyzico (the official iyzico plugin is not enabled).' => '1 回限りのカード支払いは Flux Donate iyzico によって行われます (公式 iyzico プラグインは有効になっていません)。',
  'Card payments are taken by: %s.' => 'カード支払いは%sによって行われます。',
  'No card method is enabled; donations can only be paid by bank transfer.' => '有効なカード メソッドはありません。寄付は銀行振込でのみお支払いいただけます。',
  'Card payments (WooCommerce)' => 'カード支払い (WooCommerce)',
  'Monthly donations' => '毎月の寄付',
  'Flux Donate iyzico stores the card at the first payment; a renewal order is opened and charged every month.' => 'Flux Donate iyzico は最初の支払い時にカードを保管します。更新注文がオープンされ、毎月請求されます。',
  'Monthly donations are off: enable "Card (iyzico) - Flux Donate" in WooCommerce › Settings › Payments and enter iyzico keys.' => '毎月の寄付はオフです: WooCommerce › 設定 › 支払いで「カード (iyzico) - Flux Donate」を有効にし、iyzico キーを入力します。',
  'Bank transfer (donations)' => '銀行振込(寄付)',
  'No IBAN entered.' => 'IBAN が入力されていません。',
  'The payment method is disabled.' => 'お支払い方法が無効になっています。',
  'Bank transfer settings' => '銀行振込設定',
  'Two bank transfer methods' => '2 つの銀行振込方法',
  'WooCommerce\'s own "Direct bank transfer" is enabled next to the donation bank transfer. Donors see two similar choices and the receipt upload works only with the donation one; disable "Direct bank transfer".' => 'WooCommerce\\ 独自の「直接銀行振込」は寄付銀行振込の隣で有効になります。寄付者には同様の 2 つの選択肢が表示され、領収書のアップロードは寄付の場合にのみ機能します。 「直接銀行振込」を無効にします。',
  'The shop currency is %1$s; these types use another currency and are charged in %1$s at the same number: %2$s' => 'ショップ通貨は%1$sです。これらのタイプは別の通貨を使用し、同じ番号%1$sで請求されます:%2$s',
  'WooCommerce settings' => 'WooCommerce 設定',
  'Donation types and the shop use %s.' => '寄付の種類とショップでは%sを使用します。',
  'Donation products' => '寄付商品',
  'These types get their hidden WooCommerce product the first time they are donated to or saved: %s' => 'これらのタイプは、初めて寄付または保存されたときに非表示の WooCommerce 製品を取得します:%s',
  '%d active type has its hidden WooCommerce product.' . chr(0) . '%d active types have their hidden WooCommerce products.' => '%dアクティブ タイプには、非表示の WooCommerce 製品があります。',
  'No page with the donation options block is selected.' => '寄付オプション ブロックのあるページが選択されていません。',
  'Other payment plugins' => 'その他の支払いプラグイン',
  'Check these on the donation checkout: %s. Details: Donations › Settings › WooCommerce › Payment methods.' => '寄付チェックアウトでこれらをチェックしてください:%s。詳細: 寄付 › 設定 › WooCommerce › 支払い方法。',
  'Enabled and shown on the donation checkout: %s.' => '有効化され、寄付チェックアウトに表示されます:%s。',
  'Certificates after payment' => '支払い後の証明書',
  'Flux Certificates makes the certificates of paid donation lines.' => 'Flux Certificates は、有償寄付ラインの証明書を作成します。',
  'Flux Certificates has no active template.' => 'Flux 証明書にはアクティブなテンプレートがありません。',
  'Product XML' => 'プロダクト XML',
  '%1$s lists %2$d donation packages (Google Merchant format, e.g. for iyzico).' => '%1$sには%2$d寄付パッケージのリストが表示されます (Google Merchant 形式、iyzico など)。',
  'Payment forms on the checkout' => 'チェックアウト時の支払いフォーム',
  'Donation forms send their choice to the WooCommerce cart; "Payment completed" automations run when the order is paid.' => '寄付フォームは選択内容を WooCommerce カートに送信します。注文の支払いが完了すると、「支払い完了」の自動化が実行されます。',
  'Flux Forms %s is active. Forms are paid on the checkout, but their "Payment completed" automations need Flux Forms 2.1.0 or later.' => 'Flux フォーム%sがアクティブです。フォームの支払いはチェックアウト時に行われますが、「支払い完了」の自動化には Flux Forms 2.1.0 以降が必要です。',
  'Donation e-mails' => '寄付メール',
  'Sent by Flux Mail; the templates (group "Flux Donate") can be edited there. WooCommerce order e-mails stay in WooCommerce › Settings › Emails.' => 'Flux メールで送信。テンプレート (グループ「Flux Donate」) はそこで編集できます。 WooCommerce の注文メールは、WooCommerce › 設定 › 電子メールに残ります。',
  'E-mail templates' => '電子メール テンプレート',
  'Flux Mail is not active: the donation e-mails are sent as plain text with their default wording.' => 'Flux Mail はアクティブではありません。寄付電子メールは、デフォルトの文言を含むプレーン テキストとして送信されます。',
  'Bank transfer (donation)' => '銀行振込(寄付)',
  'The donor transfers the money with an order-specific reference and uploads the receipt on the site. The certificate is issued when you confirm the payment.' => '寄付者は注文固有の参照を使用して送金し、サイトに領収書をアップロードします。支払いを確認すると証明書が発行されます。',
  'Take donations by bank transfer' => '銀行振込で寄付を受け付けます',
  'Empty = the holder of the bank account below or, without an IBAN here, of WooCommerce\'s "Direct bank transfer" account (else the theme settings).' => '空 = 以下の銀行口座の所有者、またはここで IBAN を持たない WooCommerce の「直接銀行振込」口座の所有者 (それ以外の場合はテーマ設定)。',
  'The account shown everywhere (donation page, checkout, call center). Empty = the first account of WooCommerce\'s "Direct bank transfer", else the theme settings; recipient and bank then come from that account too.' => 'アカウントはあらゆる場所 (寄付ページ、チェックアウト、コールセンター) に表示されます。空 = WooCommerce の「直接銀行振込」の最初のアカウント、それ以外の場合はテーマ設定。受信者と銀行もその口座から取得されます。',
  'What the donor writes in the transfer description. Placeholders: {tur} (sapling donation / donation), {kod} (prefix + order no), {siparis}, {ad}. Empty: {tur} {kod} {ad}' => '寄付者が譲渡説明に記入する内容。プレースホルダー:{tur}(苗木寄付 / 寄付)、{kod}(プレフィックス + 注文番号)、{siparis}、{ad}。空:{tur}{kod}{ad}',
  'Bank transfer pre-registration: waiting for the payment.' => '銀行振込事前登録: 支払いを待っています。',
  'Card (iyzico) - Flux Donate' => 'カード (iyzico) - Flux Donate',
  'Card payments on iyzico\'s secure page. Required for monthly donations (the card is stored by iyzico and charged each month); also used for one-time donations when the official iyzico plugin is not active.' => 'iyzico の安全なページでのカード支払い。毎月の寄付に必要です (カードは iyzico によって保管され、毎月請求されます)。公式 iyzico プラグインがアクティブでない場合の 1 回限りの寄付にも使用されます。',
  'Card payments through Flux Donate (iyzico)' => 'Flux Donate (iyzico) によるカード支払い',
  'Credit / debit card (iyzico)' => 'クレジット/デビット カード (iyzico)',
  'You will pay on iyzico\'s secure page. For monthly donations your card is stored by iyzico and charged once a month; you can cancel at any time.' => '支払いは iyzico の安全なページで行われます。毎月の寄付の場合、カードは iyzico によって保管され、月に 1 回請求されます。いつでもキャンセルできます。',
  'Donation options' => '寄付オプション',
  'Sapling packages, causes and free-amount donations; added to the cart and paid with WooCommerce.' => '苗木パッケージ、寄付金、および無償寄付金。カートに追加され、WooCommerce で支払いました。',
  'Tab shown first' => 'タブが最初に表示されます',
  'The first one' => '最初のもの',
  'None chosen = the types marked "Show in the Donation options block".' => '何も選択されていない = 「寄付オプション ブロックに表示」とマークされたタイプ。',
  'Prices and options: Donations › Donation types. Certificates and cart: Donations › Settings › WooCommerce.' => '価格とオプション: 寄付 › 寄付の種類。証明書とカート: 寄付 › 設定 › WooCommerce。',
  'Could not copy, please select it by hand.' => 'コピーできませんでした。手動で選択してください。',
  'We have your receipt. Thank you! We will let you know once the payment is confirmed.' => '領収書を受け取りました。ありがとう!支払いが確認され次第、お知らせいたします。',
  'Receipt under review' => '領収書は審査中です',
  'Please write a WhatsApp number or an e-mail address (at least one).' => 'WhatsApp 番号または電子メール アドレス (少なくとも 1 つ) を入力してください。',
  'Please enter a valid e-mail address.' => '有効な電子メール アドレスを入力してください。',
  'Please enter a valid phone number.' => '有効な電話番号を入力してください。',
  'Please write at most one name per share.' => '1 つの共有につき最大 1 つの名前を入力してください。',
  '/ month' => '/月',
  '(up to %s)' => '(%sまで)',
  '%s Sapling' . chr(0) . '%s Saplings' => '%s苗木',
  'Who is this donation for?' => 'この寄付は誰のためのものですか?',
  'For myself' => '自分用',
  'On behalf of someone else' => '他の人の代理として',
  'Their name' => '彼らの名前',
  'e.g. Ayşe Yılmaz or the Yılmaz family' => 'e.g.アイシェ・ユルマズまたはユルマズ家',
  'Optional. If you leave it empty, the name from the checkout is used.' => 'オプション。空のままにすると、チェックアウトの名前が使用されます。',
  'Written on the certificate and the donation record.' => '証明書と寄付記録に記載されます。',
  'Written on the donation record.' => '寄付記録に記載されています。',
  'Where should the certificate go?' => '証明書はどこに行けばよいですか?',
  'Empty fields use the phone and e-mail of your account or the checkout.' => '空のフィールドでは、アカウントまたはチェックアウトの電話と電子メールが使用されます。',
  'Their phone and e-mail. Empty fields use yours.' => '電話と電子メール。空のフィールドにはあなたのフィールドを使用してください。',
  'Send me a copy too' => '私にもコピーを送ってください',
  'Online certificate' => 'オンライン証明書',
  'Sent by WhatsApp and e-mail once the payment is confirmed, ready to download.' => '支払いが確認されたら、WhatsApp と電子メールで送信され、ダウンロードの準備が整います。',
  'Online + printed certificate' => 'オンライン + 印刷された証明書',
  'A printed certificate is also posted to your address.' => '印刷された証明書もあなたの住所に郵送されます。',
  'Postal address for the printed certificate' => '印刷された証明書の住所',
  'Name, full address, district / city, phone' => '名前、完全な住所、地区/都市、電話番号',
  'By card, stop any time.' => 'カードでいつでも停止できます。',
  'Your donation was added to the cart.' => 'あなたの寄付がカートに追加されました。',
  'Go to cart' => 'カートに移動',
  'Your donation' => 'あなたの寄付',
  'from %s' => '%sから ',
  'Payments are taken securely by iyzico.' => '支払いは iyzico によって安全に行われます。',
  'Pay safely by card or bank transfer.' => 'カードまたは銀行振込で安全にお支払いください。',
  'Your card details are never stored on our site.' => 'あなたのカードの詳細が当社のサイトに保存されることはありません。',
  'How many saplings would you like to donate?' => '何本の苗木を寄付したいですか?',
  'Another amount' => '別の金額',
  'Or write another amount' => 'または別の金額を記入してください',
  'At least %s' => '少なくとも%s',
  'On whose behalf?' => '誰に代わって?',
  'Given in your name, as you write it at the checkout.' => 'チェックアウト時に記入するあなたの名前が与えられます。',
  'Shares without a name are given in the name from the checkout. With a phone number we can also send that person the news on WhatsApp.' => '名前のない共有には、チェックアウト時の名前が付けられます。電話番号を使用すると、WhatsApp でその人にニュースを送信することもできます。',
  'Shares without a name are given in the name from the checkout.' => '名前のない共有には、チェックアウト時の名前が付けられます。',
  'Read the proxy (vekâlet) text (version %s)' => 'プロキシ (vekâlet) テキストを読み取ります (バージョン%s)',
  'I give my proxy (vekâlet) for the sacrifice according to this text.' => 'このテキストに従って、私は犠牲の代理人 (vekâlet) を捧げます。',
  'Share %s' => '%sを共有',
  'Apply to all' => 'すべてに適用',
  'e.g. Ali Yılmaz' => 'e.g.アリ・ユルマズ',
  'No receipt is expected for this donation.' => 'この寄付には領収書は必要ありません。',
  'At most 5 receipts can be uploaded for a donation.' => '寄付のためにアップロードできる領収書は最大 5 枚です。',
  'The donor uploaded a receipt: %1$s (%2$s). Check the payment and confirm it.' => '寄付者が領収書をアップロードしました:%1$s(%2$s)。支払いを確認して確定します。',
  'the site' => 'サイト',
  'Warning: this receipt was uploaded before (%1$d time, via %2$s). Check it before confirming the payment.' . chr(0) . 'Warning: this receipt was uploaded before (%1$d times, via %2$s). Check it before confirming the payment.' => '警告: この領収書は以前 (%1$d回、%2$s経由) にアップロードされました。ご入金確認前にご確認ください。',
  'Earlier donation: #%d.' => '以前の寄付: #%d。',
  'WooCommerce checkout' => 'WooCommerce チェックアウト',
  'You will choose how to pay (card or bank transfer) on the next page.' => '次のページで支払い方法 (カードまたは銀行振込) を選択します。',
  'Monthly donations are paid by card; the card is stored by iyzico and charged once a month.' => '毎月の寄付はカードで支払われます。カードは iyzico によって保管され、月に 1 回請求されます。',
  'This form is not linked to a donation type. Please contact the site administrator.' => 'このフォームは寄付の種類にリンクされていません。サイト管理者に連絡してください。',
  'The donation type of this form was not found.' => 'このフォームの寄付タイプが見つかりませんでした。',
  'The amount could not be calculated. Please review your choices and try again.' => '金額を計算できませんでした。選択内容を確認して、再試行してください。',
  'You have no pending donations.' => '保留中の寄付はありません。',
  'Donations made by bank transfer appear here until the payment is confirmed.' => '銀行振込による寄付は、支払いが確認されるまでここに表示されます。',
  'Your bank transfer donations. If you have made the payment, upload your receipt; your certificate is sent once it is confirmed.' => '銀行振込による寄付。支払いを完了した場合は、領収書をアップロードしてください。証明書が確認されると送信されます。',
  'Donation #%s' => '寄付 #%s',
  '%s donation is awaiting payment' . chr(0) . '%s donations are awaiting payment' => '%sの寄付は支払い待ちです',
  'If you have made the transfer, upload your receipt.' => '送金を行った場合は、領収書をアップロードしてください。',
  'Please write your e-mail or phone number (at least one).' => '電子メール アドレスまたは電話番号 (少なくとも 1 つ) を入力してください。',
  'Write at least one. We send your receipt and certificate there.' => '少なくとも 1 つ書き込んでください。領収書と証明書をそこにお送りします。',
  'Continue to payment' => '支払いを続行',
  'I have read and accept the %1$sprivacy policy%2$s and the %3$sdonation agreement%4$s.' => '%1$sプライバシー ポリシー%2$sおよび%3$s寄付契約%4$sを読み、同意します。',
  'Make payment' => '支払いを行う',
  'Please read and accept the terms to continue.' => '続行するには、規約を読んで同意してください。',
  'Donation terms' => '寄付条件',
  'Privacy policy' => 'プライバシー ポリシー',
  'These terms apply to donations made on this site to %s.' => 'これらの規約は、このサイトで%sに行われた寄付に適用されます。',
  'A donation is a gift without anything in return. It is used for the purpose chosen on the donation form (for example sapling planting). When a purpose is fully funded, the association may use the donation for a similar purpose.' => '寄付は何も見返りのない贈り物です。寄付フォームに記載された目的(苗木の植樹など)に使用させていただきます。目的の資金が全額満たされた場合、協会はその寄付を同様の目的に使用することができます。',
  'Card payments are processed by the licensed payment institution iyzico with 3D Secure. Card details are not stored on this site. For bank transfers, the donation is confirmed when the money reaches the association account.' => 'カード支払いは、3D セキュアを使用して認可された支払い機関 iyzico によって処理されます。カードの詳細はこのサイトには保存されません。銀行振込の場合、寄付金が協会の口座に到着した時点で寄付が確認されます。',
  'A monthly donation is charged to the same card every month until you cancel it. You can cancel it at any time from your account page or by writing to us.' => '毎月の寄付は、キャンセルするまで毎月同じカードに請求されます。アカウント ページから、または当社に書面で連絡することで、いつでもキャンセルできます。',
  'The online certificate is sent to the e-mail address or phone number you give after the payment is confirmed. Please check the names you write on the certificate.' => 'オンライン証明書は、支払いが確認された後、指定した電子メール アドレスまたは電話番号に送信されます。証明書に記入した名前を確認してください。',
  'Cancellation and refunds' => 'キャンセルと返金',
  'If a donation was made by mistake (wrong amount or a double payment), write to us within 14 days and it is refunded to the same card or account.' => '寄付が誤って行われた場合(金額の間違いまたは二重支払い)、14 日以内に私たちに書面でご連絡いただければ、同じカードまたは口座に返金されます。',
  'Your name and contact details are used to record the donation, send the receipt and certificate, and contact you about your donation. See the privacy policy for details.' => 'あなたの名前と連絡先の詳細は、寄付の記録、領収書と証明書の送付、寄付に関する連絡に使用されます。詳細については、プライバシー ポリシーを参照してください。',
  'For any question about your donation, write to us on WhatsApp: %s' => '寄付に関するご質問は、WhatsApp:%sまでお問い合わせください ',
  'For any question about your donation, write to us through the contact page.' => '寄付に関するご質問は、お問い合わせページからご連絡ください。',
  '%s processes your personal data under the Turkish Personal Data Protection Law (KVKK).' => '%sは、トルコ個人データ保護法 (KVKK) に基づいてお客様の個人データを処理します。',
  'What we collect' => '収集するもの',
  'Name, e-mail address, phone number and the details of your donation. Card details are entered on the payment institution and are not stored by us.' => '名前、電子メール アドレス、電話番号、および寄付の詳細。カードの詳細は支払い機関に入力され、当社では保管されません。',
  'To record donations, send receipts and certificates, meet legal obligations and answer your questions.' => '寄付を記録し、領収書と証明書を送信し、法的義務を果たし、質問に答えます。',
  'Your rights' => 'あなたの権利',
  'You can ask what data we hold about you, have it corrected or deleted, by writing to us.' => '弊社があなたに関してどのようなデータを保持しているのか、修正または削除を依頼するには、書面で問い合わせることができます。',
  'Block checkout' => 'チェックアウトをブロック',
  'No address' => 'アドレスがありません',
  'Server check' => 'サーバーチェック',
  'Saved cards' => '保存されたカード',
  'Refund from site' => 'サイトからの返金',
  'Shown on a checkout page built with the Checkout block. The classic checkout ([woocommerce_checkout]) shows every method.' => 'チェックアウト ブロックで構築されたチェックアウト ページに表示されます。従来のチェックアウト ([woocommerce_checkout]) にはすべてのメソッドが表示されます。',
  'Pays an existing order from its payment link (call center, "pay again"), without a cart.' => 'カートを使用せずに、支払いリンク (コールセンター、「再支払い」) から既存の注文を支払います。',
  'Works on our checkout that asks no address: Flux Donate fills the organisation\'s city and address in.' => '住所を要求しないチェックアウトでは機能します: Flux Donate は組織の都市と住所を入力します。',
  'The payment is confirmed with the provider from the server before the order is marked paid.' => '注文が支払い済みとしてマークされる前に、サーバーからプロバイダーに支払いが確認されます。',
  'The donor can pay in installments.' => '寄付者は分割払いも可能です。',
  'The donor can save a card for the next donation.' => '寄付者は次回の寄付のためにカードを保存できます。',
  'The Refund button on the order sends the refund to the provider.' => '注文の [返金] ボタンをクリックすると、プロバイダに返金が送信されます。',
  'Monthly donations charge a stored card every month. Only Flux Donate iyzico does this.' => '毎月の寄付では、保存されているカードに毎月請求されます。これを行うのは Flux Donate iyzico だけです。',
  'Added by Flux Donate (the plugin has no block support).' => 'Flux Donate によって追加されました (プラグインはブロックをサポートしていません)。',
  'Added by Flux Donate once the method is enabled.' => 'メソッドが有効になると、Flux Donate によって追加されます。',
  'Turn on "Show other payment plugins on the checkout block".' => '「チェックアウト ブロックに他の支払いプラグインを表示する」をオンにしてください。',
  'The plugin shows its own card fields only on the classic checkout. Use the classic checkout page or ask the provider for block support.' => 'プラグインは、クラシック チェックアウトでのみ独自のカード フィールドを表示します。従来のチェックアウト ページを使用するか、プロバイダにブロック サポートを依頼してください。',
  'Most plugins work; try a payment link once.' => 'ほとんどのプラグインは動作します。支払いリンクを一度試してください。',
  'Depends on the plugin; ask the provider.' => 'プラグインによって異なります。プロバイダに問い合わせてください。',
  'If the provider offers it, on its payment page.' => 'プロバイダーが提供する場合は、その支払いページで。',
  'Refund in the provider\'s panel, then mark the order refunded.' => 'プロバイダーのパネルで返金し、注文に返金済みのマークを付けます。',
  'Confirmed by hand after the receipt.' => '受領後、手作業で確認されました。',
  'not shown on the block checkout page' => 'ブロック チェックアウト ページには表示されません',
  'Yes, by Flux Donate' => 'はい、Flux Donate により',
  'On the provider\'s page' => 'プロバイダのページ',
  'Every WooCommerce payment plugin (virtual POS) works on the donation checkout: install it, enter its settings in WooCommerce › Settings › Payments and enable it. This table shows what each one can do here.' => 'すべての WooCommerce 支払いプラグイン (仮想 POS) は寄付チェックアウトで動作します。インストールし、WooCommerce › 設定 › 支払いに設定を入力して有効にします。この表は、ここで各ユーザーができることを示しています。',
  'WooCommerce payments' => 'WooCommerce での支払い',
  'Payment logos on the site' => 'サイト上の支払いロゴ',
  'Checkout page: %s.' => 'チェックアウト ページ:%s。',
  'Checkout block' => 'チェックアウトブロック',
  'classic' => 'クラシック',
  'Only one card method is shown to donors. Change it under Cart and checkout › Card payment method.' => '寄付者に表示されるカード方法は 1 つだけです。 [カートとチェックアウト] › カード支払い方法で変更します。',
  'Hidden at checkout' => 'チェックアウト時に非表示',
  'on the provider\'s page' => 'プロバイダーのページ',
  'unknown, test it' => '不明です、テストしてください',
  'Point at a mark for details.' => '詳細については、マークをポイントしてください。',
  'Donation type not found.' => '寄付の種類が見つかりません。',
  'of %s goal' => '%sゴール',
  'Goal progress' => '目標の進捗状況',
  'reached' => '到達しました',
  'donor' . chr(0) . 'donors' => '寄付者',
  'day left' . chr(0) . 'days left' => '残り日数',
  'Enter a name.' => '名前を入力してください。',
  'Partner not found.' => 'パートナーが見つかりません。',
  'Each tab must be a JSON object.' => '各タブは JSON オブジェクトである必要があります。',
  'A tab needs an "id".' => 'タブには「ID」が必要です。',
  'Tab %1$s: "on" must be item or donation, not %2$s.' => 'Tab%1$s: "on" は%2$sではなく、アイテムまたは寄付である必要があります。',
  'Tab %s: every field needs a "key".' => 'タブ%s: すべてのフィールドには「キー」が必要です。',
  'Tab %1$s, field %2$s: unknown type %3$s.' => 'タブ%1$s、フィールド%2$s: 不明なタイプ%3$s.',
  'The JSON could not be read: %s' => 'JSON を読み取れませんでした:%s',
  'Tracked items' => '追跡対象アイテム',
  'Sent to partner' => 'パートナーに送信されました',
  'Delivered to owner' => '所有者に届けられました',
  'Send to a partner' => 'パートナーに送信',
  'Take back from the partner' => 'パートナーから取り戻す',
  'Mark completed' => '完了としてマークを付ける',
  'Your gift on behalf of %1$s is completed. Thank you. Code: %2$s' => '%1$sを代表するギフトが完了しました。ありがとう。コード:%2$s',
  'Page title' => 'ページのタイトル',
  'One item' => '1 つのアイテム',
  'Status: sent to partner' => 'ステータス: パートナーに送信済み',
  'Status: completed' => 'ステータス: 完了',
  'Button: send to partner' => 'ボタン: パートナーに送信',
  'Button: take back' => 'ボタン: 取り戻す',
  'Button: mark completed' => 'ボタン: 完了マークを付けます',
  'WhatsApp text with the file (%1$s name, %2$s code)' => 'WhatsApp テキストとファイル (%1$s名、%2$sコード)',
  'File added' => 'ファイルが追加されました',
  'File removed' => 'ファイルが削除されました',
  'File sent to owner' => 'ファイルは所有者に送信されました',
  'Details changed' => '詳細が変更されました',
  'Choose: %s.' => '選択:%s。',
  'not waiting' => '待っていません',
  'approve it first' => 'まず承認してください',
  'already completed or canceled' => 'すでに完了またはキャンセルされました',
  'payment not received' => '支払いが受け取られていません',
  'already with this partner' => 'すでにこのパートナーと付き合っています',
  'not with a partner, or already completed' => 'パートナーと協力していないか、すでに完了しています',
  'send it to a partner first' => 'まずパートナーに送信します',
