  'monthly' => '毎月',
  'Your recurring donation to {kurum}' => '{kurum}への定期的な寄付 ',
  'Thank you, {ad}' => 'ありがとう、{ad}',
  'Your {aralik} donation of {tutar} is set up. The next payment will be taken on {sonraki}.' => '{tutar}の{aralik}寄付が設定されました。次の支払いは{sonraki}に行われます。',
  'You can cancel your recurring donation at any time with the button below.' => '下のボタンでいつでも定期的な寄付をキャンセルできます。',
  'Recurring donation could not be charged' => '定期的な寄付を請求できませんでした',
  'Sent to the donor when the card was declined on every attempt and the recurring donation is paused.' => 'カードがすべての試行で拒否され、定期的な寄付が一時停止された場合に寄付者に送信されます。',
  'Number of attempts' => '試行回数',
  'We could not take your donation to {kurum}' => 'あなたの寄付を{kurum}\', \'en\' に受け取ることができませんでした]]',
  'Your recurring donation is paused' => '定期的な寄付は一時停止されています',
  'Dear {ad},' => '{ad}様',
  'We tried {deneme} times but could not charge your card for your {aralik} donation of {tutar}, so it is paused. If you would like to continue, please make a new donation on our website or contact us.' => '{deneme}回試しましたが、{tutar}の{aralik}寄付をカードに請求できなかったため、一時停止されています。継続をご希望の場合は、当社の Web サイトで新たに寄付を行うか、当社までご連絡ください。',
  'Donate again' => 'もう一度寄付してください',
  'Bank transfer receipt uploaded' => '銀行振込領収書がアップロードされました',
  'Sent to the donations manager when a donor uploads a transfer receipt (dekont).' => '寄付者が振込受領書 (dekont) をアップロードすると、寄付マネージャーに送信されます。',
  'Order number' => '注文番号',
  'Transfer reference' => '転送リファレンス',
  'File name' => 'ファイル名',
  'Order link (admin)' => '注文リンク (管理者)',
  'Receipt uploaded: donation #{siparis} ({ad})' => '領収書のアップロード: 寄付 #{siparis}({ad})',
  'A transfer receipt was uploaded' => '振込受領書がアップロードされました',
  'Amount: {tutar}' => '金額:{tutar}',
  'Reference: {aciklama}' => '参照:{aciklama}',
  'File: {dosya}' => 'ファイル:{dosya}',
  'Check the payment at the bank and press "Confirm payment" on the order; the certificate is then issued and sent automatically.' => '銀行で支払いを確認し、注文の「支払いを確認する」を押してください。その後、証明書が発行され、自動的に送信されます。',
  'Open the order' => '注文を開く',
  'Sent to the donor when a manager rejects a bank transfer, with the reason.' => 'マネージャーが銀行振込を拒否した場合、その理由とともに寄付者に送信されます。',
  'We could not confirm your donation payment' => '寄付金の支払いを確認できませんでした',
  'We could not confirm your payment' => 'お支払いを確認できませんでした',
  'Hello {ad},' => '{ad}さん、こんにちは。',
  'We could not confirm the payment of your {tutar} donation.' => '{tutar}寄付金の支払いを確認できませんでした。',
  'Reason: {aciklama}' => '理由:{aciklama}',
  'If you think this is a mistake, please reply to this e-mail. Thank you.' => 'これが間違いだと思われる場合は、このメールにご返信ください。ありがとうございます。',
  'Set the organisation name' => '組織名を設定します',
  'The name shown on receipts and donor e-mails (max. 190 characters).' => '領収書および寄付者の電子メールに表示される名前 (最大 190 文字)。',
  'The organisation name cannot be empty.' => '組織名を空にすることはできません。',
  'Organisation name saved: %s' => '保存された組織名:%s',
  'Set the default currency' => 'デフォルトの通貨を設定します',
  'Used for new donation types and manual entries.' => '新しい寄付タイプと手動入力に使用されます。',
  'Unsupported currency.' => 'サポートされていない通貨です。',
  'Default currency: %s' => 'デフォルトの通貨:%s',
  'Open a donation type' => '寄付の種類を開く',
  'Sets a closed donation type that already has a price (or a free amount) to active. Value: the type slug.' => 'すでに価格 (または無料金額) が設定されているクローズ済みの寄付タイプを有効に設定します。値: タイプ スラッグ。',
  'This type has no option with a price and no free amount; set a price first.' => 'このタイプには、価格や無料金額のオプションはありません。最初に価格を設定してください。',
  'Donation type opened: %s' => 'オープンした寄付タイプ:%s',
  'Set a donation type\'s unit price' => '寄付タイプの単価を設定します',
  'Value "slug=price", e.g. "fidan=150". Every active option gets price × its units (1 sapling 150, 5 saplings 750). Linked forms update automatically.' => '値「slug=price」、例: 「フィダン=150」。すべてのアクティブなオプションは、価格×その単位を取得します (苗木 1 つで 150、苗木 5 つで 750)。リンクされたフォームは自動的に更新されます。',
  'The price must be greater than 0.' => '価格は 0 より大きくなければなりません。',
  'This type has no active option; add one on the Donation types page.' => 'このタイプにはアクティブなオプションがありません。寄付の種類ページに追加してください。',
  'Unit price of %1$s set to %2$s %3$s.' => '%1$sの単価が%2$s%3$sに設定されました。',
  'Link a form to a donation type' => 'フォームを寄付タイプにリンクする',
  'Value "slug=form id", e.g. "fidan=3". Forms: %s' => '値「slug=フォームID」、例: 「フィダン=3」。フォーム:%s',
  'No form with this id.' => 'この ID のフォームはありません。',
  'The form is already linked.' => 'フォームはすでにリンクされています。',
  'The form could not be linked.' => 'フォームをリンクできませんでした。',
  'Form "%1$s" linked to %2$s.' => 'フォーム「%1$s」は%2$sにリンクされています。',
  'Use the form "slug=value".' => '「slug=value」という形式を使用してください。',
  'No donation type with this slug.' => 'このナメクジには寄付タイプがありません。',
  'Tracked records' => '追跡されたレコード',
  'Partner group' => 'パートナー グループ',
  'Region' => '地域',
  'One-time / regular' => '一回限り/定期',
  'Margin' => 'マージン',
  'The report must be a JSON object.' => 'レポートは JSON オブジェクトである必要があります。',
  'The report needs an "id" (letters, digits, dash).' => 'レポートには「ID」(文字、数字、ダッシュ) が必要です。',
  'Unknown "source": %s. Use donations or items.' => '不明な「ソース」:%s。寄付またはアイテムを使用してください。',
  'Unknown "group" value: %s' => '不明な「グループ」値:%s',
  'Group by at most two dimensions.' => '最大でも 2 つの次元でグループ化します。',
  'Unknown "metrics" value: %s' => '不明な「メトリクス」値:%s',
  '"sort" must be one of the group or metrics values: %s' => '「sort」はグループ値またはメトリック値のいずれかである必要があります:%s',
  'piece' => 'ピース',
  'pieces' => '個',
  'shares' => '共有',
  'people' => '人々',
  'sapling' => '苗木',
  'saplings' => '苗木',
  'package' => 'パッケージ',
  'packages' => 'パッケージ',
  'In the trash' => 'ゴミ箱の中',
  'Yearly' => '毎年',
  'Test provider' => 'テストプロバイダ',
  '%1$s (%2$s)' => '%1$s(%2$s)',
  'Last test %1$s: %2$s' => '最後のテスト%1$s:%2$s',
  'WP-Cron is turned off in wp-config.php (DISABLE_WP_CRON). That is fine only if a server cron job calls %s every 5–15 minutes; without it recurring charges, retries and other scheduled tasks never run.' => 'WP-Cron は wp-config.php (DISABLE_WP_CRON) でオフになっています。これは、サーバー cron ジョブが 5 ~ 15 分ごとに%sを呼び出す場合にのみ問題ありません。これがないと、定期的な料金、再試行、その他のスケジュールされたタスクは実行されません。',
  'Scheduled tasks are running, so a server cron is in place.' => 'スケジュールされたタスクが実行されているため、サーバー cron が配置されています。',
  'Scheduled tasks have not run recently: check the server cron job (Hostinger: hPanel › Advanced › Cron Jobs).' => 'スケジュールされたタスクは最近実行されていません: サーバーの cron ジョブを確認してください (Hostinger: hPanel › Advanced › Cron Jobs)。',
  'WP-Cron runs when someone visits the site. On a quiet site tasks can run late; for reliable recurring charges add a server cron job that calls wp-cron.php every 15 minutes and set DISABLE_WP_CRON to true (see KURULUM.md).' => '誰かがサイトにアクセスすると、WP-Cron が実行されます。静かなサイトではタスクの実行が遅くなる可能性があります。信頼性の高い定期的な料金を得るには、15 分ごとに wp-cron.php を呼び出すサーバー cron ジョブを追加し、DISABLE_WP_CRON を true に設定します (KURULUM.md を参照)。',
  'ALTERNATE_WP_CRON is on.' => 'ALTERNATE_WP_CRON がオンになっています。',
  'Flux Donate hourly task' => 'Flux 時間単位のタスクを寄付',
  'Last run: %s. Recurring iyzico charges are checked every hour.' => '最終実行:%s。 iyzico の定期的な料金は 1 時間ごとにチェックされます。',
  'Not run yet; the first run is scheduled for %s.' => 'まだ実行されていません。最初の実行は%sにスケジュールされています。',
  'Last run: %s, more than 2 hours ago.' => '最終実行:%s、2 時間以上前。',
  'It has never run.' => '一度も実行されていません。',
  'WP-Cron is off, so a server cron job must call wp-cron.php. It seems to be missing or failing.' => 'WP-Cron がオフになっているため、サーバー cron ジョブは wp-cron.php を呼び出す必要があります。見つからないか、失敗しているようです。',
  'WP-Cron only runs on visits and may be blocked by the host or a security plugin. Use "Test cron" or add a server cron job.' => 'WP-Cron は訪問時にのみ実行され、ホストまたはセキュリティ プラグインによってブロックされる可能性があります。 「Test cron」を使用するか、サーバー cron ジョブを追加します。',
  'Next scheduled: %s.' => '次のスケジュール:%s。',
  'The task is not scheduled; it is added again on the next page load.' => 'タスクはスケジュールされていません。次のページのロード時に再び追加されます。',
  'Test cron' => 'cron をテストします',
  'Overdue scheduled tasks' => '期限を過ぎたスケジュールされたタスク',
  '%1$d task is more than 15 minutes late: %2$s.' . chr(0) . '%1$d tasks are more than 15 minutes late: %2$s.' => '%1$dタスクは 15 分以上遅れています:%2$s。',
  'A few late tasks right after a quiet period are normal; many mean cron is not running.' => '静かな期間の直後にいくつかのタスクが遅れるのは正常なことです。多くの場合、cron が実行されていないことを意味します。',
  'No task is late.' => '遅れているタスクはありません。',
  'Cron test' => 'Cron テスト',
  'Not tested. The test asks this server to call wp-cron.php once, as WordPress does after a visit.' => 'テストされていません。テストでは、WordPress がアクセス後に行うのと同じように、このサーバーに wp-cron.php を 1 回呼び出すように要求します。',
  'Card payment provider' => 'カード決済プロバイダー',
  'No payment provider is available.' => '利用可能な支払いプロバイダーがありません。',
  'Payment settings' => '支払い設定',
  'Card payments are taken with %s.' => 'カード支払いは%sで行われます。',
  '%s is the active provider but its keys are missing, so donation forms show "Online payment is unavailable".' => '%sはアクティブなプロバイダですが、そのキーが見つからないため、寄付フォームには「オンライン支払いは利用できません」と表示されます。',
  'Enter keys' => 'キーを入力してください',
  'Keys are read from the iyzico Subscription plugin settings.' => 'キーは iyzico サブスクリプション プラグイン設定から読み取られます。',
  'Keys are entered in Donations › Payments › iyzico.' => 'キーは、寄付 › 支払い › iyzico に入力されます。',
  'No iyzico API key and secret key found (neither in the iyzico WooCommerce plugin nor in Flux Donate).' => 'iyzico API キーと秘密キーが見つかりません (iyzico WooCommerce プラグインにも Flux Donate にもありません)。',
  'Mode: sandbox (test). No real money is collected; switch to live keys before launch.' => 'モード: サンドボックス (テスト)。実際のお金は集められません。起動前にライブキーに切り替えてください。',
  'Mode: live. Real payments are taken.' => 'モード: ライブ。実際の支払いが行われます。',
  'Use "Test connection" to check the keys with iyzico.' => '「接続のテスト」を使用して、iyzico でキーを確認します。',
  'iyzico keys' => 'iyzico キー',
  'Paste into iyzico panel › Merchant notifications URL (İşyeri Bildirimleri Url): %s. Subscription notification URLs are not needed.' => 'iyzico パネルに貼り付けます › 販売者通知 URL (İşyeri Bildirimleri Url):%s。サブスクリプション通知 URL は必要ありません。',
  'Last notification received: %s.' => '最後に受信した通知:%s。',
  'No notification received in the last 30 days (normal until the address is saved in the iyzico panel and a payment is made).' => '過去 30 日間に通知を受信していません (アドレスが iyzico パネルに保存され、支払いが行われるまでは通常の状態です)。',
  'Notifications for WooCommerce orders are forwarded to the iyzico WooCommerce plugin.' => 'WooCommerce 注文の通知は iyzico WooCommerce プラグインに転送されます。',
  'iyzico notification URL' => 'iyzico 通知 URL',
  'Show addresses' => 'アドレスを表示',
  'Failed recurring charges' => '定期的な請求が失敗しました',
  '%d recurring donation stopped after its card was declined 3 times.' . chr(0) . '%d recurring donations stopped after their cards were declined 3 times.' => '%dの定期的な寄付は、カードが 3 回拒否された後停止されました。',
  'Stripe keys' => 'ストライプ キー',
  'The Stripe publishable key and secret key are missing.' => 'Stripe 公開可能キーと秘密キーがありません。',
  'Mode: live.' => 'モード: ライブ。',
  'Mode: test (pk_test_). No real money is collected.' => 'モード: テスト (pk_test_)。実際のお金は徴収されません。',
  'Webhook signing secret is set.' => 'Webhook 署名シークレットが設定されています。',
  'Webhook signing secret is missing: refunds and renewals made in Stripe will not show up in Flux Donate.' => 'Webhook 署名シークレットがありません: Stripe で行われた払い戻しと更新は Flux Donate に表示されません。',
  'Flux Forms is not active. Donation forms and card payments need it.' => 'Flux フォームはアクティブではありません。寄付フォームとカード支払いが必要です。',
  'Active, version %s.' => 'アクティブ、バージョン%s。',
  'Version %1$s is active; Flux Donate needs %2$s or later for payments and prices to work together.' => 'バージョン%1$sはアクティブです。 Flux Donate で支払いと価格を連携するには%2$s以降が必要です。',
  'Active, version %s. Certificates can be sent after donations.' => 'アクティブ、バージョン%s。寄付後に証明書を送信できます。',
  'Version %1$s is active; %2$s or later is recommended.' => 'バージョン%1$sはアクティブです。%2$s以降を推奨します。',
  'Not active. Donations are recorded, but no certificate is created or sent.' => 'アクティブではありません。寄付は記録されますが、証明書の作成や送信は行われません。',
  'WooCommerce is older than %s. Flux Donate 2.0 takes donations through WooCommerce; update it.' => 'WooCommerce は%sよりも古いです。 Flux Donate 2.0 は WooCommerce を通じて寄付を受け付けています。更新してください。',
  'WooCommerce is not active. Flux Donate 2.0 takes donations through the WooCommerce cart and checkout; until it is active, only the older Flux Forms payment layer works.' => 'WooCommerce はアクティブではありません。 Flux Donate 2.0 は、WooCommerce カートとチェックアウトを通じて寄付を受け付けます。アクティブになるまでは、古い Flux Forms 支払いレイヤーのみが機能します。',
  'The old Flux WooCommerce Bağış plugin is still active. Flux Donate 2.0 replaces it: deactivate and delete it, otherwise orders get two certificates and two messages.' => '古い Flux WooCommerce Bağış プラグインはまだアクティブです。 Flux Donate 2.0 がこれを置き換えます。無効化して削除します。そうでない場合、オーダーは 2 つの証明書と 2 つのメッセージを取得します。',
  'WooCommerce is active.' => 'WooCommerce はアクティブです。',
  'The iyzico WooCommerce plugin is active: it takes one-time card payments, and Flux Donate reads its iyzico keys for monthly donations.' => 'iyzico WooCommerce プラグインはアクティブです。カード支払いは 1 回限りで、Flux Donate は毎月の寄付のために iyzico キーを読み取ります。',
  'The iyzico WooCommerce plugin is not active, but its saved keys are still used.' => 'iyzico WooCommerce プラグインはアクティブではありませんが、保存されたキーは引き続き使用されます。',
  'The iyzico WooCommerce plugin is not active; Flux Donate uses its own iyzico keys.' => 'iyzico WooCommerce プラグインはアクティブではありません。 Flux Donate は独自の iyzico キーを使用します。',
  'The iyzico Subscription plugin is active; it renews WooCommerce subscriptions only. Flux Donate recurring donations use their own hourly task.' => 'iyzico サブスクリプション プラグインはアクティブです。 WooCommerce サブスクリプションのみを更新します。 Flux Donate の定期的な寄付では、独自の時間ごとのタスクが使用されます。',
  'WooCommerce and iyzico plugins' => 'WooCommerce および iyzico プラグイン',
  'Open donation types' => '寄付タイプを開く',
  '%d donation type is open and priced.' . chr(0) . '%d donation types are open and priced.' => '%dの寄付タイプはオープンで価格も設定されています。',
  'No donation type is open with a price (or free amount), so forms cannot take donations.' => '価格 (または無料金額) が公開されている寄付タイプがないため、フォームで寄付を受け付けることはできません。',
  'Forms of open donation types' => 'オープンな寄付タイプのフォーム',
  'No (existing) form is linked to: %s. Visitors cannot give to these types online.' => '(既存の) フォームが%sにリンクされていません。訪問者はこれらのタイプにオンラインで寄付することはできません。',
  'Every open donation type has a form.' => 'すべてのオープンな寄付タイプにはフォームがあります。',
  'Default currency: %s.' => 'デフォルトの通貨:%s。',
  'iyzico is not set up for this currency (Donations › Payments › iyzico › currencies).' => 'iyzico はこの通貨に設定されていません (寄付 › 支払い › iyzico › 通貨)。',
  'Bank accounts (transfer)' => '銀行口座 (振込)',
  '%d bank account is listed for bank transfer gifts.' . chr(0) . '%d bank accounts are listed for bank transfer gifts.' => '銀行振込ギフト用の%d銀行口座がリストされています。',
  'No bank account is listed. They come from the theme (filter flxb_bank_accounts) and are used when recording bank transfer gifts.' => '銀行口座がリストされていません。これらはテーマ (フィルター flxb_bank_accounts) から取得され、銀行振込ギフトを記録するときに使用されます。',
  'Receipts and e-mails show "%s".' => '領収書と電子メールには「%s」が表示されます。',
  'Not set; receipts and e-mails use the site title "%s".' => '設定されていません。領収書と電子メールでは、サイト タイトル「%s」が使用されます。',
  'E-mail sending' => '電子メール送信',
  'Not tested. Donor e-mails (recurring donation started, card declined) go out with wp_mail. The test sends one message to %s.' => 'テストされていません。寄付者の電子メール (定期的な寄付が開始され、カードが拒否されました) は wp_mail で送信されます。テストは 1 つのメッセージを%sに送信します。',
  'Send test e-mail' => 'テスト電子メールを送信',
  'Plain permalinks are in use. Payment callbacks still work through ?rest_route=, but some hosts and security plugins block that; choose "Post name".' => 'プレーンパーマリンクが使用されています。支払いコールバックは ?rest_route= を通じて引き続き機能しますが、一部のホストとセキュリティ プラグインはそれをブロックします。 「投稿名」を選択してください。',
  'Pretty permalinks are on; REST callbacks use /wp-json/.' => 'きれいなパーマリンクがオンになっています。 REST コールバックは /wp-json/ を使用します。',
  'The site runs on HTTPS.' => 'サイトは HTTPS で実行されます。',
  'Local test site without HTTPS. The live site must use HTTPS; payment providers refuse plain HTTP.' => 'HTTPS を使用しないローカル テスト サイト。ライブ サイトでは HTTPS を使用する必要があります。支払いプロバイダはプレーン HTTP を拒否します。',
  'The site address is not HTTPS. Card payments and payment callbacks need HTTPS (Settings › General, and an SSL certificate from the host).' => 'サイトのアドレスは HTTPS ではありません。カード支払いと支払いコールバックには HTTPS ([設定] › [一般]、およびホストからの SSL 証明書) が必要です。',
  'WordPress security keys (salts)' => 'WordPress セキュリティ キー (ソルト)',
  'Missing or weak in wp-config.php: %s. Saved iyzico cards are encrypted with these keys; set unique values once (https://api.wordpress.org/secret-key/1.1/salt/) and do not change them afterwards, or saved cards stop working.' => 'wp-config.php:%sが欠落しているか弱い。保存された iyzico カードはこれらのキーで暗号化されます。一意の値を一度設定 (https://api.wordpress.org/secret-key/1.1/salt/) し、その後は変更しないでください。変更しないと、保存されたカードが機能しなくなります。',
  'Set in wp-config.php. Saved iyzico cards are encrypted with them: do not change them, or saved cards stop working.' => 'wp-config.php で設定します。保存された iyzico カードは暗号化されます。変更しないでください。変更しないと、保存されたカードが機能しなくなります。',
  'Up to date (%s).' => '最新の状態 (%s)。',
  'Tables are at version %1$s, expected %2$s. Deactivate and activate Flux Donate to update them.' => 'テーブルのバージョンは%1$sですが、%2$sが必要です。 Flux Donate を非アクティブにしてからアクティブにして更新してください。',
  'No iyzico keys to test.' => 'テストする iyzico キーがありません。',
  'sandbox' => 'サンドボックス',
  'Connected; iyzico accepted the keys (%s).' => '接続されました; iyzico はキー (%s) を受け入れました。',
  'iyzico refused the keys (%1$s): %2$s. Check that the keys belong to this environment.' => 'iyzico はキー (%1$s) を拒否しました:%2$s。キーがこの環境に属していることを確認してください。',
  'This server could not reach its own wp-cron.php (%s). WP-Cron cannot start from visits; add a server cron job.' => 'このサーバーは独自の wp-cron.php (%s) にアクセスできませんでした。 WP-Cron は訪問から開始できません。サーバー cron ジョブを追加します。',
  'wp-cron.php answered; WP-Cron can start.' => 'wp-cron.php が答えました。 WP-Cron を開始できます。',
  'wp-cron.php answered with HTTP %d (blocked by the host or a security plugin?). Add a server cron job.' => 'wp-cron.php は HTTP%dで応答しました (ホストまたはセキュリティ プラグインによってブロックされました?)。サーバー cron ジョブを追加します。',
  '[%s] Test e-mail from Flux Donate' => '[%s] Flux Donate からのテスト電子メール',
  'This is a test from Donations › Settings › System check. If you can read it, donor e-mails can be sent.' => 'これは、「寄付」 > 「設定」 > 「システムチェック」からのテストです。読むことができれば、寄付者の電子メールを送信できます。',
  'Sent to %s. Check that it arrived (and not in spam).' => '%sに送信されます。受信したことを確認してください (スパムではないこと)。',
  'Sending failed: %s. Set up SMTP (e.g. an SMTP plugin with your mail account).' => '送信に失敗しました:%s。 SMTP をセットアップします (メール アカウントを使用した SMTP プラグインなど)。',
  'Donations on WooCommerce: donation types and sapling packages sold as hidden products, cart and checkout (iyzico, bank transfer with receipt upload), monthly donations, online and printed certificates, donors, campaigns and a donation dashboard. Includes Flux WooCommerce Bağış.' => 'WooCommerce での寄付: 非表示の商品として販売される寄付タイプと苗木パッケージ、カートとチェックアウト (iyzico、領収書のアップロードによる銀行振込)、毎月の寄付、オンラインおよび印刷された証明書、寄付者、キャンペーン、寄付ダッシュボード。 Flux WooCommerce Bağış.\', \'en\']] が含まれます。',
  '%1$s·%2$s' => '%1$s·%2$s',
