  'Donation >%s' => '寄付 >%s',
  'Hello{ad}, your donation of{tutar}is registered. IBAN:{iban}Reference:{aciklama}Upload your receipt:{link}' => 'こんにちは{ad}さん。{tutar}の寄付が登録されました。 IBAN:{iban}参照:{aciklama}領収書のアップロード:{link}',
