  'Pending transfer notification sent:%s.' => '送信された保留中の転送通知:%s。',
  'Version%1$sis active. Flux Donate was checked up to%2$s; it uses only stable public WooCommerce functions, but test a donation after big WooCommerce updates.' => 'バージョン%1$sはアクティブです。 Flux Donate は%2$sまでチェックされました。安定した公開 WooCommerce 機能のみを使用しますが、WooCommerce の大幅な更新後に寄付をテストします。',
  'Active, version%s. Donations are paid through the WooCommerce cart and checkout.' => 'アクティブ、バージョン%s。寄付は、WooCommerce カートとチェックアウトを通じて支払われます。',
  'One-time card payments are taken by%s; iyzico is not shown at the checkout.' => '1 回限りのカード支払いは%sによって行われます。 iyzico はチェックアウト時に表示されません。',
  'Card payments are taken by:%s.' => 'カード支払いは%sによって行われます。',
  'The shop currency is%1$s; these types use another currency and are charged in%1$sat the same number:%2$s' => 'ショップ通貨は%1$sです。これらのタイプは別の通貨を使用し、同じ番号%1$sで請求されます:%2$s',
  'Donation types and the shop use%s.' => '寄付の種類とショップでは%sを使用します。',
  'These types get their hidden WooCommerce product the first time they are donated to or saved:%s' => 'これらのタイプは、初めて寄付または保存されたときに非表示の WooCommerce 製品を取得します:%s',
  '%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.' => '%dアクティブ タイプには、非表示の WooCommerce 製品があります。%dアクティブ タイプには、非表示の WooCommerce 製品があります。',
  'Check these on the donation checkout:%s. Details: Donations › Settings › WooCommerce › Payment methods.' => '寄付チェックアウトでこれらをチェックしてください:%s。詳細: 寄付 › 設定 › WooCommerce › 支払い方法。',
  'Enabled and shown on the donation checkout:%s.' => '有効化され、寄付チェックアウトに表示されます:%s。',
  '%1$slists%2$ddonation packages (Google Merchant format, e.g. for iyzico).' => '%1$sには%2$d寄付パッケージのリストが表示されます (Google Merchant 形式、iyzico など)。',
  'Flux Forms%sis active. Forms are paid on the checkout, but their "Payment completed" automations need Flux Forms 2.1.0 or later.' => 'Flux フォーム%sがアクティブです。フォームの支払いはチェックアウト時に行われますが、「支払い完了」の自動化には Flux Forms 2.1.0 以降が必要です。',
  'What the donor writes in the transfer description. Placeholders:{tur}(sapling donation / donation),{kod}(prefix + order no),{siparis},{ad}. Empty:{tur}{kod}{ad}' => '寄付者が譲渡説明に記入する内容。プレースホルダー:{tur}(苗木寄付 / 寄付)、{kod}(プレフィックス + 注文番号)、{siparis}、{ad}。空:{tur}{kod}{ad}',
  '(up to%s)' => '(%sまで)',
  '%sSapling' . chr(0) . '%sSaplings' => '%s苗木',
  'from%s' => '%sから ',
  'At least%s' => '少なくとも%s',
  'Read the proxy (vekâlet) text (version%s)' => 'プロキシ (vekâlet) テキストを読み取ります (バージョン%s)',
  'Share%s' => '%sを共有',
  'The donor uploaded a receipt:%1$s(%2$s). Check the payment and confirm it.' => '寄付者が領収書をアップロードしました:%1$s(%2$s)。支払いを確認して確定します。',
  'Warning: this receipt was uploaded before (%1$dtime, via%2$s). Check it before confirming the payment.' . chr(0) . 'Warning: this receipt was uploaded before (%1$dtimes, via%2$s). Check it before confirming the payment.' => '警告: この領収書は以前 (%1$d回、%2$s経由) にアップロードされました。支払いを確認する前に必ずご確認ください。',
  '%sdonation is awaiting payment' . chr(0) . '%sdonations are awaiting payment' => '%sの寄付は支払いを待っています',
  'I have read and accept the%1$sprivacy policy%2$sand the%3$sdonation agreement%4$s.' => '%1$sプライバシー ポリシー%2$sおよび%3$s寄付契約%4$sを読み、同意します。',
  'These terms apply to donations made on this site to%s.' => 'これらの規約は、このサイトで%sに行われた寄付に適用されます。',
  'For any question about your donation, write to us on WhatsApp:%s' => '寄付に関するご質問は、WhatsApp:%sまでお問い合わせください ',
  '%sprocesses your personal data under the Turkish Personal Data Protection Law (KVKK).' => '%sは、トルコ個人データ保護法 (KVKK) に基づいてお客様の個人データを処理します。',
  'Checkout page:%s.' => 'チェックアウト ページ:%s。',
  'of%sgoal' => '%sゴール',
  'Tab%1$s: "on" must be item or donation, not%2$s.' => 'Tab%1$s: "on" は%2$sではなく、アイテムまたは寄付である必要があります。',
  'Tab%s: every field needs a "key".' => 'タブ%s: すべてのフィールドには「キー」が必要です。',
  'Tab%1$s, field%2$s: unknown type%3$s.' => 'タブ%1$s、フィールド%2$s: 不明なタイプ%3$s.',
  'The JSON could not be read:%s' => 'JSON を読み取れませんでした:%s',
  'Your gift on behalf of%1$sis completed. Thank you. Code:%2$s' => '%1$sを代表するギフトが完了しました。ありがとう。コード:%2$s',
  'WhatsApp text with the file (%1$sname,%2$scode)' => 'WhatsApp テキストとファイル (%1$s名、%2$sコード)',
  'Choose:%s.' => '選択:%s。',
  'received%s' => '%sを受信しました',
  'Interval (monthly...)' => '間隔 (毎月...)',
  'Your recurring donation to{kurum}' => '{kurum}への定期的な寄付 ',
  'Thank you,{ad}' => 'ありがとう、{ad}',
  'Your{aralik}donation of{tutar}is set up. The next payment will be taken on{sonraki}.' => '{tutar}の{aralik}寄付が設定されました。次の支払いは{sonraki}に行われます。',
  'We could not take your donation to{kurum}' => 'あなたの寄付を{kurum}\', \'en\' に受け取ることができませんでした]]',
  'Dear{ad},' => '{ad}様',
  'We tried{deneme}times but could not charge your card for your{aralik}donation of{tutar}, so it is paused. If you would like to continue, please make a new donation on our website or contact us.' => '{deneme}回試しましたが、{tutar}の{aralik}寄付をカードに請求できなかったため、一時停止されています。継続をご希望の場合は、当社の Web サイトで新たに寄付を行うか、当社までご連絡ください。',
  'Receipt uploaded: donation #{siparis}({ad})' => '領収書のアップロード: 寄付 #{siparis}({ad})',
  'Amount:{tutar}' => '金額:{tutar}',
  'Reference:{aciklama}' => '参照:{aciklama}',
  'File:{dosya}' => 'ファイル:{dosya}',
  'Hello{ad},' => '{ad}さん、こんにちは。',
  'We could not confirm the payment of your{tutar}donation.' => '{tutar}寄付金の支払いを確認できませんでした。',
  'Reason:{aciklama}' => '理由:{aciklama}',
  'Organisation name saved:%s' => '保存された組織名:%s',
  'Default currency:%s' => 'デフォルトの通貨:%s',
  'Donation type opened:%s' => 'オープンした寄付タイプ:%s',
  'Unit price of%1$sset to%2$s%3$s.' => '%1$sの単価が%2$s%3$sに設定されました。',
  'Value "slug=form id", e.g. "fidan=3". Forms:%s' => '値「slug=フォームID」、例: 「フィダン=3」。フォーム:%s',
  'Form "%1$s" linked to%2$s.' => 'フォーム「%1$s」は%2$sにリンクされています。',
  'Unknown "source":%s. Use donations or items.' => '不明な「ソース」:%s。寄付またはアイテムを使用してください。',
  'Unknown "group" value:%s' => '不明な「グループ」値:%s',
  'Unknown "metrics" value:%s' => '不明な「メトリクス」値:%s',
  '"sort" must be one of the group or metrics values:%s' => '「sort」はグループ値またはメトリック値のいずれかである必要があります:%s',
  '%1$s(%2$s)' => '%1$s(%2$s)',
  'Last test%1$s:%2$s' => '最後のテスト%1$s:%2$s',
  'WP-Cron is turned off in wp-config.php (DISABLE_WP_CRON). That is fine only if a server cron job calls%severy 5–15 minutes; without it recurring charges, retries and other scheduled tasks never run.' => 'WP-Cron は wp-config.php (DISABLE_WP_CRON) でオフになっています。これは、サーバー cron ジョブが 5 ~ 15 分ごとに%sを呼び出す場合にのみ問題ありません。これがないと、定期的な料金、再試行、その他のスケジュールされたタスクは実行されません。',
  'Last run:%s. Recurring iyzico charges are checked every hour.' => '最終実行:%s。 iyzico の定期的な料金は 1 時間ごとにチェックされます。',
  'Not run yet; the first run is scheduled for%s.' => 'まだ実行されていません。最初の実行は%sにスケジュールされています。',
  'Last run:%s, more than 2 hours ago.' => '最終実行:%s、2 時間以上前。',
  'Next scheduled:%s.' => '次のスケジュール:%s。',
  '%1$dtask is more than 15 minutes late:%2$s.%1$dtasks are more than 15 minutes late:%2$s.' => '%1$dタスクは 15 分以上遅れています:%2$s。%1$dタスクが 15 分以上遅れています:%2$s。',
  'Card payments are taken with%s.' => 'カード支払いは%sで行われます。',
  '%sis the active provider but its keys are missing, so donation forms show "Online payment is unavailable".' => '%sはアクティブなプロバイダですが、そのキーが見つからないため、寄付フォームには「オンライン支払いは利用できません」と表示されます。',
  'Paste into iyzico panel › Merchant notifications URL (İşyeri Bildirimleri Url):%s. Subscription notification URLs are not needed.' => 'iyzico パネルに貼り付けます › 販売者通知 URL (İşyeri Bildirimleri Url):%s。サブスクリプション通知 URL は必要ありません。',
  'Last notification received:%s.' => '最後に受信した通知:%s。',
  '%drecurring donation stopped after its card was declined 3 times.' . chr(0) . '%drecurring donations stopped after their cards were declined 3 times.' => '%dの定期的な寄付は、カードが 3 回拒否された後停止されました。',
  'Active, version%s.' => 'アクティブ、バージョン%s。',
  'Version%1$sis active; Flux Donate needs%2$sor later for payments and prices to work together.' => 'バージョン%1$sはアクティブです。 Flux Donate で支払いと価格を連携するには%2$s以降が必要です。',
  'Active, version%s. Certificates can be sent after donations.' => 'アクティブ、バージョン%s。寄付後に証明書を送信できます。',
  'Version%1$sis active;%2$sor later is recommended.' => 'バージョン%1$sはアクティブです。%2$s以降を推奨します。',
  'WooCommerce is older than%s. Flux Donate 2.0 takes donations through WooCommerce; update it.' => 'WooCommerce は%sよりも古いです。 Flux Donate 2.0 は WooCommerce を通じて寄付を受け付けています。更新してください。',
  '%ddonation type is open and priced.' . chr(0) . '%ddonation types are open and priced.' => '%d寄付タイプはオープンで価格も設定されています。',
  'No (existing) form is linked to:%s. Visitors cannot give to these types online.' => '(既存の) フォームが%sにリンクされていません。訪問者はこれらのタイプにオンラインで寄付することはできません。',
  'Default currency:%s.' => 'デフォルトの通貨:%s。',
  '%dbank account is listed for bank transfer gifts.' . chr(0) . '%dbank accounts are listed for bank transfer gifts.' => '%d銀行口座は銀行振込ギフト用にリストされています。',
  'Not tested. Donor e-mails (recurring donation started, card declined) go out with wp_mail. The test sends one message to%s.' => 'テストされていません。寄付者の電子メール (定期的な寄付が開始され、カードが拒否されました) は wp_mail で送信されます。テストは 1 つのメッセージを%sに送信します。',
  'Missing or weak in wp-config.php:%s. Saved iyzico cards are encrypted with these keys; set unique values once (https://api.wordpress.org/secret-key/1.1/salt/) and do not change them afterwards, or saved cards stop working.' => 'wp-config.php:%sが欠落しているか弱い。保存された iyzico カードはこれらのキーで暗号化されます。一意の値を一度設定 (https://api.wordpress.org/secret-key/1.1/salt/) し、その後は変更しないでください。変更しないと、保存されたカードが機能しなくなります。',
  'Tables are at version%1$s, expected%2$s. Deactivate and activate Flux Donate to update them.' => 'テーブルのバージョンは%1$sですが、%2$sが必要です。 Flux Donate を非アクティブにしてからアクティブにして更新してください。',
  'iyzico refused the keys (%1$s):%2$s. Check that the keys belong to this environment.' => 'iyzico はキー (%1$s) を拒否しました:%2$s。キーがこの環境に属していることを確認してください。',
  'wp-cron.php answered with HTTP%d(blocked by the host or a security plugin?). Add a server cron job.' => 'wp-cron.php は HTTP%dで応答しました (ホストまたはセキュリティ プラグインによってブロックされました?)。サーバー cron ジョブを追加します。',
  'Sent to%s. Check that it arrived (and not in spam).' => '%sに送信されます。受信したことを確認してください (スパムではないこと)。',
  'Sending failed:%s. Set up SMTP (e.g. an SMTP plugin with your mail account).' => '送信に失敗しました:%s。 SMTP をセットアップします (メール アカウントを使用した SMTP プラグインなど)。',
  '%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived' . chr(0) . '%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived' => '%1$sの寄付 ·%2$sを受け取りました%1$sの寄付を受け取りました ·%2$sを受け取りました',
  '%1$spaid gift ·%2$s%1$spaid gifts ·%2$s' . chr(0) . '%1$spaid gift ·%2$s%1$spaid gifts ·%2$s' => '%1$s有料ギフト ·%2$s%1$s有料ギフト ·%2$s',
  '%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.' . chr(0) . '%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.' => '%dアクティブ タイプには、非表示の WooCommerce 製品があります。%dアクティブ タイプには、非表示の WooCommerce 製品があります。',
  '%1$dtask is more than 15 minutes late:%2$s.%1$dtasks are more than 15 minutes late:%2$s.' . chr(0) . '%1$dtask is more than 15 minutes late:%2$s.%1$dtasks are more than 15 minutes late:%2$s.' => '%1$dタスクは 15 分以上遅れています:%2$s。%1$dタスクが 15 分以上遅れています:%2$s。',
  '%srecurring donation could not be charged through iyzico after all attempts and is now past due. The donor was e-mailed.\\x00%srecurring donations could not be charged through iyzico after all attempts and are now past due. The donors were e-mailed.' => '%sの定期的な寄付は、すべての試みの後、iyzico を通じて請求できず、現在期限を過ぎています。寄付者には電子メールが送信されました。',
  '%sdonor\\x00%sdonors' => '%s寄付者',
