  'Please write at most%sname (one per share).\\x00Please write at most%snames (one per share).' => '%s名は最大でも 1 つずつ書いてください (シェアごとに 1 つ)。',
  'Your certificate is ready\\x00Your certificates are ready' => '証明書の準備ができました',
